(
  'dd70c340-9a28-5bee-a392-25605ce759be',
  'machine pullover',
  'Machine Pullover',
  'back',
  'leverage machine',
  'latissimus dorsi',
  ARRAY['triceps', 'deltoids']::text[],
  ARRAY['Step:1 Set the seat and handles of the leverage machine to a comfortable position.', 'Step:2 Take a seat on the machine with your back against the pad and Hold the handles with palms facing down.', 'Step:3 Set the ribs down and keep a small elbow bend before lowering the weight.', 'Step:4 Lower the weight in an arc behind your head until you feel a comfortable shoulder stretch.', 'Step:5 Keep the ribs down as the arms travel overhead.', 'Step:6 Pull the weight back over the chest along the same arc, without lifting the ribs.']::text[],
  'https://static.exercisedb.dev/media/4U7iLb5.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  '7bc82fe6-d269-591b-aa64-059489684491',
  'hyperextension machine reverse',
  'Machine Reverse Hyperextension',
  'legs',
  'leverage machine',
  'glutes',
  ARRAY['hamstrings', 'erector spinae']::text[],
  ARRAY['Step:1 Set the leverage machine to fit your body and secure your feet in the foot pads.', 'Step:2 Position yourself face down on the machine with your upper body hanging off the edge and your hips resting on the pad.', 'Step:3 Secure the hips and feet on the support before lifting.', 'Step:4 Raise your torso or legs until they line up with your body, without arching sharply at the lower back.', 'Step:5 Finish in a straight body line, before the lower back overarches.', 'Step:6 Ease back to the start before repeating.']::text[],
  'https://static.exercisedb.dev/media/Krmb3cB.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  'f9a3dca7-b248-532b-b854-ab5426931bbc',
  'bar machine reverse row t',
  'Machine Reverse T-Bar Row',
  'back',
  'leverage machine',
  'upper back',
  ARRAY['biceps', 'forearms']::text[],
  ARRAY['Step:1 Set the seat height and footplate position on the leverage machine.', 'Step:2 Take a seat on the machine with your chest against the pad and your feet flat on the footplate.', 'Step:3 Set the torso and allow the arms to reach forward without rounding excessively.', 'Step:4 Draw your elbows back and bring the handle or weight toward your torso.', 'Step:5 Bring the elbows back without jerking the torso.', 'Step:6 Reach the arms forward again without letting the torso lurch.']::text[],
  'https://static.exercisedb.dev/media/BgljGjd.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  'd2c820a3-98b5-5266-bbe3-3211c9da2bbd',
  'lateral machine pulldown reverse',
  'Machine Reverse-Grip Lateral Pulldown',
  'back',
  'leverage machine',
  'latissimus dorsi',
  ARRAY['biceps', 'rhomboids', 'rear deltoids']::text[],
  ARRAY['Step:1 Fit the seat to your body, then settle into the machine.', 'Step:2 Hold the handles with palms facing down, just beyond shoulder width.', 'Step:3 Sit tall and set the shoulders before drawing the handle down.', 'Step:4 Pull the handle down by driving your elbows toward your ribs, keep your torso steady.', 'Step:5 Keep the palms in the chosen grip without bending the wrists back.', 'Step:6 Let the handle rise steadily until the arms are long, then reset the shoulders.']::text[],
  'https://static.exercisedb.dev/media/ky8FLU8.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
