  'curl machine preacher reverse',
  'Machine Reverse-Grip Preacher Curl',
  'biceps',
  'leverage machine',
  'biceps',
  ARRAY['forearms']::text[],
  ARRAY['Step:1 Fit the seat to your body, then settle into the machine.', 'Step:2 Hold the handles with palms facing up.', 'Step:3 Set the working upper arm against the preacher pad and leave the elbow free to bend.', 'Step:4 Curl the weight while your upper arms stay in contact with the pad.', 'Step:5 Keep the palms in the chosen grip without bending the wrists back.', 'Step:6 Lower until the elbows are nearly straight, keeping the upper arms still.']::text[],
  'https://static.exercisedb.dev/media/7y9JIMj.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
