  ARRAY['biceps', 'forearms']::text[],
  ARRAY['Step:1 Set the seat height and footplate position to ensure proper alignment.', 'Step:2 Take a seat on the machine with your chest against the pad and your feet flat on the footplate.', 'Step:3 Set the torso and allow the arms to reach forward without rounding excessively.', 'Step:4 Draw your elbows back and bring the handle or weight toward your torso.', 'Step:5 Keep the palms in the chosen grip without bending the wrists back.', 'Step:6 Reach the arms forward again without letting the torso lurch.']::text[],
  'https://static.exercisedb.dev/media/ZqNOWQ6.gif',
