(
  'd1c030e0-5d69-5eb5-856f-17a310a46897',
  'calf machine rotary',
  'Machine Rotary Calf',
  'legs',
  'leverage machine',
  'calves',
  ARRAY['soleus', 'ankle stabilizers']::text[],
  ARRAY['Step:1 Set the seat height so that your knees are soft and your feet are flat on the footplate.', 'Step:2 Set your toes on the footplate, with your heels hanging off the edge.', 'Step:3 Let the ankles move freely while the rest of the body stays quiet.', 'Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Step:5 Pause at the top without rolling the ankles outward.', 'Step:6 Lower the heels at a measured pace before rising again.']::text[],
  'https://static.exercisedb.dev/media/MrgP9L6.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
