  'calf machine press seated',
  'Machine Seated Calf Press',
  'legs',
  'leverage machine',
  'calves',
  ARRAY['soleus', 'hamstrings']::text[],
  ARRAY['Step:1 Set the seat of the machine so that your shoulders are aligned with the lever pad.', 'Step:2 Set your toes on the lower portion of the platform and position your knees under the lever pad.', 'Step:3 Let the ankles move freely while the rest of the body stays quiet.', 'Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Step:5 Pause at the top without rolling the ankles outward.', 'Step:6 Lower the heels at a measured pace before rising again.']::text[],
  'https://static.exercisedb.dev/media/Ie9UGty.gif',
