  'leverage machine',
  'abdominals',
  ARRAY['obliques', 'hip flexors']::text[],
  ARRAY['Step:1 Take a seat on the leverage machine with your back against the pad and your feet secured under the footpads.', 'Step:2 Set your hands on the handles or the sides of the seat for support.', 'Step:3 Set the pelvis and keep the neck relaxed before curling upward.', 'Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.', 'Step:5 Leave a little space between the chin and chest, keep the movement in the torso.', 'Step:6 Lower the shoulders or torso with control before the next curl.']::text[],
