  ARRAY['Step:1 Set the seat height and chest pad position according to your comfort.', 'Step:2 Take a seat on the machine with your back against the chest pad and your feet planted.', 'Step:3 Set the pelvis and keep the neck relaxed before curling upward.', 'Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.', 'Step:5 Leave a little space between the chin and chest, keep the movement in the torso.', 'Step:6 Lower the shoulders or torso with control before the next curl.']::text[],
