  'leverage machine',
  'triceps',
  ARRAY['pectorals', 'deltoids']::text[],
  ARRAY['Step:1 Set the seat height so that your feet are flat on the ground and your knees are at a 90-degree angle.', 'Step:2 Hold the handles of the leverage machine with your palms facing down and your arms straight.', 'Step:3 Set the shoulders down and keep the elbows pointed mostly behind you.', 'Step:4 Bend the elbows to lower between the supports, stop at a comfortable shoulder depth.', 'Step:5 Choose a depth that lets the shoulders stay comfortable.', 'Step:6 Press through the hands to rise, then reset the shoulders before another rep.']::text[],
