  'leverage machine',
  'pectorals',
  ARRAY['deltoids', 'trapezius']::text[],
  ARRAY['Step:1 Fit the seat to your body, then settle into the machine.', 'Step:2 Hold the handles with a pronated grip and keep your elbows soft.', 'Step:3 Keep a soft elbow bend and set the shoulders before moving the arms.', 'Step:4 With a soft bend in the elbows, sweep your arms together in a wide arc.', 'Step:5 Keep the elbow angle nearly unchanged through the arc.', 'Step:6 Open the arms back along the same arc without dropping the load.']::text[],
