  'Machine Seated Good Morning',
  'legs',
  'leverage machine',
  'glutes',
  ARRAY['hamstrings', 'erector spinae']::text[],
  ARRAY['Step:1 Set the seat height so that your hips are slightly higher than your knees.', 'Step:2 Take a seat on the machine with your back against the pad and your feet flat on the footrests.', 'Step:3 Unlock the knees and brace the abdomen before moving the hips back.', 'Step:4 Push the hips back while keeping the load close and the spine steady.', 'Step:5 Keep the weight close to the legs and stop when the back would begin to round.', 'Step:6 Drive the hips forward to stand tall without leaning back at the top.']::text[],
  'https://static.exercisedb.dev/media/XsCcxCC.gif',
