  ARRAY['quadriceps', 'hamstrings', 'glutes']::text[],
  ARRAY['Step:1 Move the leg-press seat until the knees remain soft at the start.', 'Step:2 Take a seat on the machine with your back against the backrest and your feet flat on the footplate, about shoulder width.', 'Step:3 Brace the abdomen and spread pressure across the whole foot.', 'Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Step:5 Drive upward with the chest and hips rising together, keep the knees from collapsing inward.', 'Step:6 Stand fully, reset your footing and breathing, then begin the next descent.']::text[],
