  '8f23a97d-ff92-59a0-a128-fb8cb1e8d5fd',
  'machine military press shoulder',
  'Machine Shoulder (Military) Press',
  'shoulders',
  'machine',
  'shoulders',
  ARRAY['triceps']::text[],
  ARRAY['Sit down on the Shoulder Press Machine and select the weight.', 'Grab the handles to your sides as you keep the elbows bent and in line with your torso. This will be your starting position.', 'Now lift the handles as you exhale and you extend the arms fully. At the top of the position make sure that you hold the contraction for a second.', 'Lower the handles slowly back to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Machine_Shoulder_Military_Press/0.jpg',
