  'deltoids',
  ARRAY['triceps', 'pectorals']::text[],
  ARRAY['Step:1 Fit the seat to your body, then settle into the machine.', 'Step:2 Hold the handles with palms facing down and position your hands at shoulder level.', 'Step:3 Brace the torso and align the wrists with the forearms.', 'Step:4 Press the weight or handles away while keeping your trunk braced.', 'Step:5 Keep the wrists stacked and use a shoulder path that feels natural.', 'Step:6 Lower the weight to its starting height under control before pressing again.']::text[],
