  ARRAY['Step:1 Fit the seat to your body, then settle into the machine.', 'Step:2 Hold the handles with palms facing down and keep your arms straight.', 'Step:3 Let the arms hang long and keep the head neutral.', 'Step:4 Lift your shoulders toward your ears without bending the elbows or rolling the shoulders.', 'Step:5 Lift and lower vertically without circling the shoulders.', 'Step:6 Ease back to the start before repeating.']::text[],
