  ARRAY['Step:1 Begin in a push-up position with your hands directly under your shoulders and your body in a straight line.', 'Step:2 Lower your body down toward the ground by bending your elbows, keeping them close to your sides.', 'Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Step:4 Bend your elbows to lower your chest while keeping your body in one line.', 'Step:5 Keep the head in line with the spine as the elbows bend.', 'Step:6 Press back to straight arms, keeping the body line intact.']::text[],
  'https://static.exercisedb.dev/media/arvaszz.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  '566a8b1d-0ffa-5401-80c4-cf9545d065b4',
