  'monster walk',
  'legs',
  'bodyweight',
  'glutes',
  ARRAY['hamstrings', 'quadriceps']::text[],
  ARRAY['Step:1 Set a resistance band around your ankles.', 'Step:2 Stand and set your feet about shoulder width and slightly bend your knees.', 'Step:3 Stand tall with the load secure and the shoulders level.', 'Step:4 Walk at a controlled pace, keeping your shoulders level and your steps even.', 'Step:5 Keep steps even and avoid leaning away from the load.', 'Step:6 Stop before posture breaks down, set the load down safely, and reset for the next walk.']::text[],
  'https://static.exercisedb.dev/media/O95afRA.gif',
