  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  '7cab291b-3664-5024-a0b7-e0d1ac834f88',
  'climber mountain',
  'mountain climber',
  'cardio',
  'bodyweight',
  'cardiovascular system',
  ARRAY['core', 'deltoids', 'triceps']::text[],
  ARRAY['Step:1 Begin in a high plank position with your hands directly under your shoulders and your body in a straight line.', 'Step:2 Brace your trunk and bring your right knee toward your chest, then quickly switch and bring your left knee toward your chest.', 'Step:3 Brace the trunk lightly before moving a limb.', 'Step:4 Move the working arm or leg while keeping the trunk steady and the breathing even.', 'Step:5 Keep the pelvis from rocking as the arm or leg moves.', 'Step:6 Reset your posture before changing sides or beginning the next rep.']::text[],
  'https://static.exercisedb.dev/media/RJgzwny.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  '61d2580d-0b55-53e8-b8ab-a8adfa1156bc',
  'climbers mountain',
  'Mountain Climbers',
  'legs',
  '',
  'quadriceps',
  ARRAY['chest', 'hamstrings', 'shoulders']::text[],
  ARRAY['Begin in a pushup position, with your weight supported by your hands and toes. Flexing the knee and hip, bring one leg until the knee is approximately under the hip. This will be your starting position.', 'Explosively reverse the positions of your legs, extending the bent leg until the leg is straight and supported by the toe, and bringing the other foot up with the hip and knee flexed. Repeat in an alternating fashion for 20-30 seconds.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Mountain_Climbers/0.jpg',
  'image',
