),
(
  '57ecd8fe-af1d-58f3-ad39-2c515b8a7f82',
  'claw moving series',
  'Moving Claw Series',
  'legs',
  '',
  'hamstrings',
  ARRAY['calves', 'quadriceps']::text[],
  ARRAY['This move helps prepare your running form to help you excel at sprinting. As you run, be sure to flex the knee, aiming to kick your glutes as the hip extends.', 'Reload the quad as the leg moves back forward, attacking the ground on the next step.', 'Ensure that as you run, you block with the arms, punching through in a rapid 1-2 motion.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Moving_Claw_Series/0.jpg',
