),
(
  'f4187224-d17a-5a39-b887-924a071b1224',
  'muscle snatch',
  'Muscle Snatch',
  'legs',
  'barbell',
  'hamstrings',
  ARRAY['glutes', 'lower back', 'quadriceps', 'shoulders', 'triceps']::text[],
  ARRAY['Begin with a loaded barbell held at the mid thigh position with a wide grip. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position.', 'Begin the pull by driving through the front of the heels, raising the bar. Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body.', 'Continue raising the bar to the overhead position, without rebending the knees.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Muscle_Snatch/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'ed57d830-610a-59dc-96ad-0a0a11e7fb1a',
  'muscle up',
  'muscle up',
  'back',
  'bodyweight',
  'latissimus dorsi',
  ARRAY['biceps', 'triceps', 'deltoids', 'pectorals']::text[],
  ARRAY['Step:1 Begin by hanging from a pull-up bar with your palms turned away from you and your arms straight.', 'Step:2 Brace your trunk and pull your body up toward the bar, leading with your chest.', 'Step:3 Begin from a controlled hang with the shoulders active rather than slack.', 'Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.', 'Step:5 Avoid swinging the legs to clear the bar.', 'Step:6 Lower to long arms without dropping suddenly from the top.']::text[],
  'https://static.exercisedb.dev/media/yJUHKTn.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
