  'muscle-up (on vertical bar)',
  'back',
  'bodyweight',
  'latissimus dorsi',
  ARRAY['biceps', 'triceps', 'forearms']::text[],
  ARRAY['Step:1 Begin by hanging from a vertical bar with your palms turned away from you and your arms straight.', 'Step:2 Brace your trunk and pull your body up toward the bar, leading with your chest.', 'Step:3 Begin from a controlled hang with the shoulders active rather than slack.', 'Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.', 'Step:5 Avoid swinging the legs to clear the bar.', 'Step:6 Lower to long arms without dropping suddenly from the top.']::text[],
  'https://static.exercisedb.dev/media/Af0EW2I.gif',
