  'stability ball',
  'triceps',
  ARRAY['pectorals', 'deltoids']::text[],
  ARRAY['Step:1 Set the stability ball on the ground and position yourself in a push-up position with your hands on the ball, slightly narrower than about shoulder width.', 'Step:2 Brace your trunk and keep your body in a straight line from head to toe.', 'Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Step:4 Bend your elbows to lower your chest while keeping your body in one line.', 'Step:5 Keep the ball steady and use the feet to manage your balance.', 'Step:6 Press back to straight arms, keeping the body line intact.']::text[],
  'https://static.exercisedb.dev/media/4cWjYEN.gif',
