  '',
  '{}'::text[],
  ARRAY['Starting position:', 'Start sitting or standing. Lean your head against one of your shoulders, but don''t push.', 'Steps:', 'In one slower fluid motion and with your head relaxed and not pushing in any direction:', '1. bring your head down toward your chest.', '2. then lean back aganst your other shoulder.', '3. then back toward the chest again.4.and finally toward the starting position.', 'Keep repeating this.']::text[],
