  ARRAY['Step:1 Stand tall with your feet about shoulder width and hold an Olympic barbell with palms facing down.', 'Step:2 Keep the barbell hanging at arm''s length ahead of your thighs, with your palms facing your body.', 'Step:3 Set the shoulders and upper arms before bending the elbows.', 'Step:4 Curl with palms facing each other and elbows near your sides, avoid rocking back.', 'Step:5 Keep the palms facing each other and the wrists straight.', 'Step:6 Lower until the elbows are nearly straight, keeping the upper arms still.']::text[],
