  'quadriceps',
  ARRAY['calves', 'glutes', 'hamstrings']::text[],
  ARRAY['Begin with a barbell supported on top of the traps. The chest should be up, and the head facing forward. Adopt a hip width stance with the feet turned out as needed.', 'Descend by flexing the knees, refraining from moving the hips back as much as possible. This requires that the knees travel forward, ensure that they stay aligned with the feet. The goal is to keep the torso as upright as possible. Continue all the way down, keeping the weight on the front of the heel.', 'At the moment the upper legs contact the lower, reverse the motion, driving the weight upward.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Olympic_Squat/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'e261cca8-089d-5345-ae16-e41ee1961aac',
  'cable cross omni over',
  'Omni Cable Cross-over',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Adjust the weights based on the', 'motion. When pulling from top to bottom, increase the weight by 20% to 40%', 'more than the bottom-to-top motion. This accounts for the fact that when', 'operating from top down, the upper chest muscles are naturally weaker than', 'the lower chest muscles. So, adjust your weight stack to', 'compensate.', '1. Position one cable at a high', 'setting and the other at the lowest level setting. Get into a staggered', 'stance in between the cable towers.', '2. For the cable set low, pull it', 'upward and across your body. This effectively targets the upper chest.', '3. For the cable set high, draw it', 'downward and across your body. This will primarily engage the lower chest.', 'Once you’re done, swap the', 'positions of the cables. Change the previously high cable to the lowest', 'position and vice versa. Repeat the exercise sequence, ensuring you’re', 'targeting both chest regions effectively.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'Moffi'
),
(
  '3d6cc69a-fbaf-5225-a817-7df35bd251c4',
  'quad side stretch',
  'On Your Side Quad Stretch',
  'legs',
  '',
  'quadriceps',
  '{}'::text[],
  ARRAY['Start off by lying on your right side, with your right knee bent at a 90-degree angle resting on the floor in front of you (this stabilizes the torso).', 'Bend your left knee behind you and hold your left foot with your left hand. To stretch your hip flexor, press your left hip forward as you push your left foot back into your hand. Switch sides.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/On_Your_Side_Quad_Stretch/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '537c5746-6261-5141-b587-d00af0f68c7b',
  'back quad stretch',
  'On-Your-Back Quad Stretch',
  'legs',
  'other',
  'quadriceps',
  '{}'::text[],
  ARRAY['Lie on a flat bench or step, and hang one leg and arm over the side.', 'Bend the knee and hold the top of the foot. As you do this, be careful not to arch your lower back.', 'Pull the belly button to the spine to stay in neutral. Press your foot down and into your hand. To add the hip stretch, lift the hip of the leg you''re holding up toward the ceiling.', 'Switch sides.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/On-Your-Back_Quad_Stretch/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
