(
  'd0d9efca-b0fc-55d2-9e15-b5e0fac0a286',
  'bench dumbbell press singlearm',
  'One Arm Dumbbell Bench Press',
  'chest',
  'dumbbell',
  'chest',
  ARRAY['shoulders', 'triceps']::text[],
  ARRAY['Lie down on a flat bench with a dumbbell in one hand on top of your thigh.', 'By using your thigh to help you get the dumbbell up, clean the dumbbell up so that you can hold it in front of you at shoulder width. Use the hand you are not lifting with to help position the dumbbell over you properly.', 'Once at shoulder width, rotate your wrist forward so that the palm of your hand is facing away from you. This will be your starting position.', 'Bring down the weights slowly to your side as you breathe in. Keep full control of the dumbbell at all times. Tip: Use the hand that you are not lifting with to help keep the dumbbell balance as you may struggle a bit at first. Only use your non-lifting hand if it is needed. Otherwise, keep it resting to the side.', 'As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions of your training program.', 'Switch arms and repeat the movement.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Arm_Dumbbell_Bench_Press/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'bc90496d-a058-552a-92dc-7d48da68d127',
  'curl dumbbell preacher singlearm',
  'One Arm Dumbbell Preacher Curl',
  'biceps',
  'dumbbell',
  'biceps',
  '{}'::text[],
  ARRAY['Grab a dumbbell with the right arm and place the upper arm on top of the preacher bench or the incline bench. The dumbbell should be held at shoulder length. This will be your starting position.', 'As you breathe in, slowly lower the dumbbell until your upper arm is extended and the biceps is fully stretched.', 'As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the dumbbell is at shoulder height. Again, remember that to ensure full contraction you need to bring that small finger higher than the thumb.', 'Squeeze the biceps hard for a second at the contracted position and repeat for the recommended amount of repetitions.', 'Switch arms and repeat the movement.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Arm_Dumbbell_Preacher_Curl/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'c61c31e5-8b98-5a8c-ba92-94a7bc154caf',
  'floor press singlearm',
  'One Arm Floor Press',
  'triceps',
  'barbell',
  'triceps',
  ARRAY['chest', 'shoulders']::text[],
  ARRAY['Lie down on a flat surface with your back pressing against the floor or an exercise mat. Make sure your knees are bent.', 'Have a partner hand you the bar on one hand. When starting, your arm should be just about fully extended, similar to the starting position of a barbell bench press. However, this time your grip will be neutral (palms facing your torso).', 'Make sure the hand you are not using to lift the weight is placed by your side.', 'Begin the exercise by lowering the barbell until your elbow touches the ground. Make sure to breathe in as this is the eccentric (lowering part of the exercise).', 'Then start lifting the barbell back up to the original starting position. Remember to breathe out during the concentric (lifting part of the exercise).', 'Repeat until you have performed your recommended repetitions.', 'Switch arms and repeat the movement.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Arm_Floor_Press/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '3cf543c9-223a-5331-83f5-b1398c2788cc',
  'lat pulldown singlearm',
  'One Arm Lat Pulldown',
  'back',
  'cable',
  'lats',
  ARRAY['biceps', 'middle back']::text[],
  ARRAY['Select an appropriate weight and adjust the knee pad to help keep you down. Grasp the handle with a pronated grip. This will be your starting position.', 'Pull the handle down, squeezing your elbow to your side as you flex the elbow.', 'Pause at the bottom of the motion, and then slowly return the handle to the starting position.', 'For multiple repetitions, avoid completely returning the weight to keep tension on the muscles being worked.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Arm_Lat_Pulldown/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'd33ae257-26ad-5893-85fe-2719e53a0eed',
  'cable extension overhead singlearm tricep',
  'One Arm Overhead Cable Tricep Extension',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Set the pulley at the bottom of the cable machine and grab onto it without using any attachments. Extend the cable directly overhead.', 'While keeping your back straight and upper arm stationary, lower the cable behind your head until you feel a good stretch in your triceps, and then extend it back upward until your elbow is locked out.']::text[],
