(
  '243aa6b5-5f1b-55c2-bd94-d0bca4756093',
  'dumbbell extension pronated singlearm triceps',
  'One Arm Pronated Dumbbell Triceps Extension',
  'triceps',
  'dumbbell',
  'triceps',
  '{}'::text[],
  ARRAY['Lie flat on a bench while holding a dumbbell at arms length. Your arm should be perpendicular to your body. The palm of your hand should be facing towards your feet as a pronated grip is required to perform this exercise.', 'Place your non lifting hand on your bicep for support.', 'Slowly begin to lower the dumbbell down as you breathe in.', 'Then, begin lifting the dumbbell upward as you contract the triceps. Remember to breathe out during the concentric (lifting part of the exercise).', 'Repeat until you have performed your set repetitions.', 'Switch arms and repeat the movement.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Arm_Pronated_Dumbbell_Triceps_Extension/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '9e91245c-8541-5948-bc9e-8e7ef3415568',
  'dumbbell extension singlearm supinated triceps',
  'One Arm Supinated Dumbbell Triceps Extension',
  'triceps',
  'dumbbell',
  'triceps',
  '{}'::text[],
  ARRAY['Lie flat on a bench while holding a dumbbell at arms length. Your arm should be perpendicular to your body. The palm of your hand should be facing towards your face as a supinated grip is required to perform this exercise.', 'Place your non lifting hand on your bicep for support.', 'Slowly begin to lower the dumbbell down as you breathe in.', 'Then, begin lifting the dumbbell upward as you contract the triceps. Remember to breathe out during the concentric (lifting part of the exercise).', 'Repeat until you have performed your set repetitions.', 'Switch arms and repeat the movement.', 'Switch arms again and repeat the movement.']::text[],
