(
  '3ae117e9-61e4-5bc3-81eb-67b5389f26b6',
  'half locust one',
  'One Half Locust',
  'legs',
  '',
  'quadriceps',
  ARRAY['abdominals', 'biceps', 'chest']::text[],
  ARRAY['Lie facedown on the floor.', 'Put your left hand under your left hipbone to pad your hip and pubic bone.', 'Bend your right knee so you can hold the foot in your right hand.', 'Lift the foot in the air and simultaneously lift your shoulders off the floor. This also stretches the right hip flexor and the chest and shoulders. Switch sides. If it doesn''t bother your back, you can try it with both arms and legs at the same time.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Half_Locust/0.jpg',
