  'c1aee283-1b36-564b-9dc5-8d6a48c1c41b',
  'hang singlearm',
  'One Handed Hang',
  'back',
  'other',
  'lats',
  ARRAY['biceps']::text[],
  ARRAY['Grab onto a chinup bar with one hand, using a pronated grip. Keep your feet on the floor or a step. Allow the majority of your weight to hang from that hand, while keeping your feet on the ground. Hold for 10-20 seconds and switch sides.']::text[],
