(
  '351fabef-76bd-513f-b773-31d458a8956b',
  'chest knee one',
  'One Knee To Chest',
  'legs',
  '',
  'glutes',
  ARRAY['hamstrings', 'lower back']::text[],
  ARRAY['Start off by lying on the floor.', 'Extend one leg straight and pull the other knee to your chest. Hold under the knee joint to protect the kneecap.', 'Gently tug that knee toward your nose.', 'Switch sides. This stretches the buttocks and lower back of the bent leg and the hip flexor of the straight leg.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Knee_To_Chest/0.jpg',
