),
(
  '068c7231-3262-5aeb-8247-e0ff161ef8a9',
  'dumbbell row singlearm',
  'One-Arm Dumbbell Row',
  'back',
  'dumbbell',
  'middle back',
  ARRAY['biceps', 'lats', 'shoulders']::text[],
  ARRAY['Choose a flat bench and place a dumbbell on each side of it.', 'Place the right leg on top of the end of the bench, bend your torso forward from the waist until your upper body is parallel to the floor, and place your right hand on the other end of the bench for support.', 'Use the left hand to pick up the dumbbell on the floor and hold the weight while keeping your lower back straight. The palm of the hand should be facing your torso. This will be your starting position.', 'Pull the resistance straight up to the side of your chest, keeping your upper arm close to your side and keeping the torso stationary. Breathe out as you perform this step. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. Also, make sure that the force is performed with the back muscles and not the arms. Finally, the upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the dumbbell, therefore do not try to pull the dumbbell up using the forearms.', 'Lower the resistance straight down to the starting position. Breathe in as you perform this step.', 'Repeat the movement for the specified amount of repetitions.', 'Switch sides and repeat again with the other arm.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Dumbbell_Row/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '527f8dd8-a51b-51a5-bf89-756e1453b00d',
  'bench dumbbell flye singlearm',
  'One-Arm Flat Bench Dumbbell Flye',
  'chest',
  'dumbbell',
  'chest',
  '{}'::text[],
  ARRAY['Lie down on a flat bench with a dumbbell in one hand resting on top of your thigh. The palm of your hand with the dumbbell in it should be at a neutral grip.', 'By using your thighs to help you get the dumbbell up, clean the dumbbell so that you can hold it in front of you with your lifting arm being fully extended. Remember to maintain a neutral grip with this exercise. Your non lifting hand should be to the side holding the flat bench for better support. This will be your starting position.', 'Your arm with the weight should have a slight bend on your elbow in order to prevent stress at the biceps tendon. Begin by lowering your arm with the weight in it out in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, your lifting arm should remain stationary, the movement should only occur at the shoulder joint.', 'Return your lifting arm back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.', 'Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions.', 'Switch arms and repeat the exercise.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Flat_Bench_Dumbbell_Flye/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'feadcdbd-3992-5803-a5f4-01ca5af66666',
  'heavy row singlearm',
  'One-Arm Heavy Row',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['### **Execution**', '1. **Rowing phase (concentric):**', '* Pull the dumbbell **toward your lower chest or waist**, leading with your **elbow**.', '* Keep your torso **stable** — avoid twisting or rotating your shoulders.', '* Pause at the top and **squeeze your lats**.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'daiben'
),
(
  '10dbde24-6abb-518d-b698-8acce6dae9d7',
  'bends cable high pulley side singlearm',
  'One-Arm High-Pulley Cable Side Bends',
  'core',
  'cable',
  'abdominals',
  '{}'::text[],
  ARRAY['Connect a standard handle to a tower. Move cable to highest pulley position.', 'Stand with side to cable. With one hand, reach up and grab handle with underhand grip.', 'Pull down cable until elbow touches your side and the handle is by your shoulder.', 'Position feet hip-width apart. Place free hand on hip to help gauge pivot point.', 'Keep arm in static position. Contract oblique to bring the weight down in a side crunch.', 'Once you reach maximum contraction, slowly release the weight to the starting position. The weight stack should never be unloaded in a resting position. The aim is constant tension during the set.', 'Repeat to failure.', 'Then, reposition and repeat the same series of movements on the opposite side.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_High-Pulley_Cable_Side_Bends/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '900fb51c-5317-57d9-9186-09961c491619',
  'incline lateral raise singlearm',
  'One-Arm Incline Lateral Raise',
  'shoulders',
  'dumbbell',
  'shoulders',
  '{}'::text[],
  ARRAY['Lie down sideways on an incline bench press with a dumbbell in the hand. Make sure the shoulder is pressing against the incline bench and the arm is lying across your body with the palm around your navel.', 'Hold a dumbbell in your uppermost arm while keeping it extended in front of you parallel to the floor. This is your starting position.', 'While keeping the dumbbell parallel to the floor at all times, perform a lateral raise. Your arm should travel straight up until it is pointing at the ceiling. Tip: Exhale as you perform this movement. Hold the dumbbell in the position and feel the contraction in the shoulders for a second.', 'While inhaling lower the weight across your body back into the starting position.', 'Repeat the movement for the prescribed amount of repetitions.', 'Switch arms and repeat the movement.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Incline_Lateral_Raise/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '9e539e27-e886-5164-94a4-406a63f117df',
  'clean kettlebell singlearm',
  'One-Arm Kettlebell Clean',
  'legs',
  'kettlebells',
  'hamstrings',
  ARRAY['glutes', 'lower back', 'shoulders', 'traps']::text[],
  ARRAY['Place a kettlebell between your feet. As you bend down to grab the kettlebell, push your butt back and keep your eyes looking forward.', 'Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so.', 'Return the weight to the starting position.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Clean/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '03f6ede4-d3e3-5fb2-8dc1-caf9742983ac',
  'kettlebell para press singlearm',
  'One-Arm Kettlebell Para Press',
  'shoulders',
  'kettlebells',
  'shoulders',
  ARRAY['triceps']::text[],
  ARRAY['Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.', 'Hold the kettlebell with the elbow out to the side, and press it up and out until it is locked out overhead.', 'Lower the kettlebell back to your shoulder under control and repeat. Make sure to contract your lat, butt, and stomach forcefully for added stability and strength.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Para_Press/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'daf48347-0612-54f4-91c7-c531a9e0442e',
  'jerk kettlebell singlearm split',
  'One-Arm Kettlebell Split Jerk',
  'shoulders',
  'kettlebells',
  'shoulders',
  ARRAY['glutes', 'hamstrings', 'quadriceps', 'triceps']::text[],
  ARRAY['Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.', 'Dip your body by bending the knees, keeping your torso upright.', 'Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body''s momentum to move the weight.', 'Receive the weight overhead by returning to a squat position underneath the weight, positioning one leg in front of you and one leg behind you.', 'Keeping the weight overhead, return to a standing position and bring your feet together. Lower the weight to perform the next repetition.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Split_Jerk/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'c431f55e-030b-5b82-907f-47ee81addc3d',
  'kettlebell singlearm snatch split',
  'One-Arm Kettlebell Split Snatch',
  'shoulders',
  'kettlebells',
  'shoulders',
  ARRAY['hamstrings', 'quadriceps']::text[],
  ARRAY['Hold a kettlebell in one hand by the handle.', 'Squat towards the floor, and then reverse the motion, extending the hips, knees, and finally the ankles, to raise the kettlebell overhead.', 'After fully extending the body, descend into a lunge position to receive the weights overhead, one leg forward and one leg back. Ensure you drive through with your hips and lock the ketttlebells overhead in one uninterrupted motion.', 'Return to a standing position, holding the weight overhead, and bring the feet together. Lower the weight to return to the starting position.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Split_Snatch/0.jpg',
  'image',
