  null
),
(
  '0add820c-fca4-5416-ab41-27148911756b',
  'clean kettlebell open palm singlearm',
  'One-Arm Open Palm Kettlebell Clean',
  'legs',
  'kettlebells',
  'hamstrings',
  ARRAY['forearms', 'glutes', 'lower back', 'quadriceps', 'shoulders']::text[],
  ARRAY['Place one kettlebell between your feet.', 'Grab the handle with one hand and raise the kettlebell rapidly, let it flip so that the ball of the kettlebell lands in the palm of your hand.', 'Throw the kettlebell out in front of you and catch the handle with one hand.', 'Take the kettlebell to the floor and repeat. Make sure to work both arms.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Open_Palm_Kettlebell_Clean/0.jpg',
