(
  '520208a5-2022-53fb-b2c5-bb1053ff198d',
  'cable ged kickback singleleg',
  'One-Legged Cable Kickback',
  'legs',
  'cable',
  'glutes',
  ARRAY['hamstrings']::text[],
  ARRAY['Hook a leather ankle cuff to a low cable pulley and then attach the cuff to your ankle.', 'Face the weight stack from a distance of about two feet, grasping the steel frame for support.', 'While keeping your knees and hips bent slightly and your abs tight, contract your glutes to slowly "kick" the working leg back in a semicircular arc as high as it will comfortably go as you breathe out. Tip: At full extension, squeeze your glutes for a second in order to achieve a peak contraction.', 'Now slowly bring your working leg forward, resisting the pull of the cable until you reach the starting position.', 'Repeat for the recommended amount of repetitions.', 'Switch legs and repeat the movement for the other side.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Legged_Cable_Kickback/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
