  ARRAY['Step:1 Begin in a push-up position with your hands just beyond shoulder width and your feet together.', 'Step:2 Lower your body toward the ground by bending your elbows, with your spine steady and core engaged.', 'Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Step:4 Bend your elbows to lower your chest while keeping your body in one line.', 'Step:5 Keep the head in line with the spine as the elbows bend.', 'Step:6 Press back to straight arms, keeping the body line intact.']::text[],
