(
  'fd7e7b4a-f6db-5188-a74c-d19fa42f9983',
  'extension overhead triceps',
  'Overhead Triceps Extension',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['**Overhead Triceps Extension with EZ Bar – Quick Guide**', 'The **overhead position** *emphasizes the long head* of the triceps (because it''s stretched under load), the exercise **does engage all three triceps heads** (long, lateral, and medial) to some degree during extension.', '1. **Setup**:', 'Sit on a bench (or stand) and hold an EZ bar with a narrow, overhand', 'grip. Lift the bar overhead, arms fully extended. Keep your core tight', 'and elbows close to your head.', '2. **Execution**:', 'Slowly lower the bar behind your head by bending your elbows until they', 'reach ~90°. Keep elbows pointed forward (not flaring out).', '3. **Finish**: Extend your arms back up to the starting position, squeezing your triceps at the top.', '**Tips**:', '* Control the movement to avoid straining your shoulders.', '* Use a moderate weight for full range of motion.', '* Keep your back straight and avoid arching.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'benjamin.yildiz@proton.me'
),
(
  '1ae08284-38a9-5d23-b274-e181868c77fc',
  'overhead stretch triceps',
  'overhead triceps stretch',
  'triceps',
  'bodyweight',
  'triceps',
  ARRAY['deltoids']::text[],
  ARRAY['Step:1 Either stand or sit upright with your feet about shoulder width.', 'Step:2 Extend one arm overhead, bending at the elbow so that your hand reaches toward the opposite shoulder blade.', 'Step:3 Settle into the starting position and take an easy breath before moving deeper.', 'Step:4 Ease toward the stretch until you feel mild tension, keep breathing and avoid bouncing.', 'Step:5 Stay in a mild stretch rather than pulling farther with momentum.', 'Step:6 Hold the position with steady breathing, then release gently, repeat on the other side if needed.']::text[],
  'https://static.exercisedb.dev/media/Z5YStHW.gif',
