),
(
  '98e03cca-d2a6-5417-b4f2-f547373c6abf',
  'pallof press',
  'Pallof Press',
  'core',
  'cable',
  'abdominals',
  ARRAY['chest', 'shoulders', 'triceps']::text[],
  ARRAY['Connect a standard handle to a tower, and—if possible—position the cable to shoulder height. If not, a low pulley will suffice.', 'With your side to the cable, grab the handle with both hands and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable.', 'With your feet positioned hip-width apart and knees slightly bent, hold the cable to the middle of your chest. This will be your starting position.', 'Press the cable away from your chest, fully extending both arms. You core should be tight and engaged.', 'Hold the repetition for several seconds before returning to the starting position.', 'At the conclusion of the set, repeat facing the other direction.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pallof_Press/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '3aa2f71f-ef03-5d99-8d4e-5d1dfbbc20ce',
  'pallof press rotation',
  'Pallof Press With Rotation',
  'core',
  'cable',
  'abdominals',
  ARRAY['chest', 'shoulders', 'triceps']::text[],
  ARRAY['Connect a standard handle to a tower, and position the cable to shoulder height.', 'With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Align outstretched arm with cable.', 'With your feet positioned hip-width apart, pull the cable into your chest and grab the handle with your other hand. Both hands should be on the handle at this time.', 'Facing forward, press the cable away from your chest. You core should be tight and engaged.', 'Keeping your hips straight, twist your torso away from the pulley until you get a full quarter rotation.', 'Maintain your rigid stance and straight arms. Return to the neutral position in a slow and controlled manner. Your arms should be extended in front of you.', 'With the side tension still engaging your core, bring your hands to your chest and immediately press outward to a fully extended position. This constitutes one rep.', 'Repeat to failure.', 'Then, reposition and repeat the same series of movements on the opposite side.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pallof_Press_With_Rotation/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '13e8afc1-065c-5efc-89c2-a7a4a2a374fc',
  'bench curl down dumbbell over palms wrist',
  'Palms-Down Dumbbell Wrist Curl Over A Bench',
  'forearms',
  'dumbbell',
  'forearms',
  '{}'::text[],
  ARRAY['Start out by placing two dumbbells on one side of a flat bench.', 'Kneel down on both of your knees so that your body is facing the flat bench.', 'Use your arms to grab both of the dumbbells with a pronated grip (palms facing down) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.', 'Start out by curling your wrist upwards and exhaling.', 'Slowly lower your wrists back down to the starting position while inhaling.', 'Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
