  'a496dcbf-81e0-5acc-a959-4db9db2b31e1',
  'peroneals stretch',
  'peroneals stretch',
  'legs',
  'rope',
  'calves',
  ARRAY['ankles', 'feet']::text[],
  ARRAY['Step:1 Take a seat on the ground with your legs extended in front of you.', 'Step:2 Thread the rope around the ball of your foot and hold the ends of the rope with your hands.', 'Step:3 Settle into the starting position and take an easy breath before moving deeper.', 'Step:4 Ease toward the stretch until you feel mild tension, keep breathing and avoid bouncing.', 'Step:5 Stay in a mild stretch rather than pulling farther with momentum.', 'Step:6 Hold the position with steady breathing, then release gently, repeat on the other side if needed.']::text[],
  'https://static.exercisedb.dev/media/XhfS1DZ.gif',
