(
  '839f6a7a-c9bb-547b-9347-71a9161f06f4',
  'peroneals smr',
  'Peroneals-SMR',
  'other',
  'foam roll',
  'calves',
  '{}'::text[],
  ARRAY['Lay on your side, supporting your weight on your forearm and on a foam roller placed on the outside of your lower leg. Your upper leg can either be on top of your lower leg, or you can cross it in front of you. This will be your starting position.', 'Raise your hips off of the ground and begin to roll from below the knee to above the ankle on the side of your leg, pausing at points of tension for 10-30 seconds. Repeat on the other leg.']::text[],
