  '30b21179-8412-5048-bb47-8c9e591c83c6',
  'pinch plate',
  'Plate Pinch',
  'forearms',
  'other',
  'forearms',
  '{}'::text[],
  ARRAY['Grab two wide-rimmed plates and put them together with the smooth sides facing outward', 'Use your fingers to grip the outside part of the plate and your thumb for the other side thus holding both plates together. This is the starting position.', 'Squeeze the plate with your fingers and thumb. Hold this position for as long as you can.', 'Repeat for the recommended amount of sets prescribed in your program.', 'Switch arms and repeat the movements.']::text[],
