(
  'f537c5a5-efd9-5c76-a2af-977f1e6cc465',
  'hold pinch plate',
  'Plate Pinch Hold',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['The plate pinch hold is a grip strength exercise designed to target the forearms and improve grip endurance. Select one or two weight plates (smooth-edged plates work best) and pinch them together between your thumb and fingers. Hold the plates with your arm straight down by your side or extended slightly in front of you. Maintain the hold for as long as you can, keeping your shoulders relaxed and your grip firm. This exercise can be done for time or repetitions.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'hpmbala@gmail.com'
),
(
  '2c2473ff-fc50-5296-8db3-4d69fa3fcd77',
  'plate twist',
  'Plate Twist',
  'core',
  'other',
  'abdominals',
  '{}'::text[],
  ARRAY['Lie down on the floor or an exercise mat with your legs fully extended and your upper body upright. Grab the plate by its sides with both hands out in front of your abdominals with your arms slightly bent.', 'Slowly cross your legs near your ankles and lift them up off the ground. Your knees should also be bent slightly. Note: Move your upper body back slightly to help keep you balanced turning this exercise. This is the starting position.', 'Move the plate to the left side and touch the floor with it. Breathe out as you perform that movement.', 'Come back to the starting position as you breathe in and then repeat the movement but this time to the right side of the body. Tip: Use a slow controlled movement at all times. Jerking motions can injure the back.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Plate_Twist/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
