  'Plate-Loaded Lat Pulldown',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Sit at a plate-loaded (lever) lat pulldown machine with your thighs secured under the pads. Grip the handles overhead with arms fully extended. Pull the handles down toward your upper chest by driving your elbows down and back, squeezing your lats at the bottom. Return slowly to full extension. Resistance comes from weight plates loaded on the machine''s lever arms rather than a cable stack.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'trs1800'
),
(
  '0bb7a1d5-2051-5495-a9ce-0b3172620549',
  'hamstring platform slides',
  'Platform Hamstring Slides',
  'legs',
  'other',
  'hamstrings',
  ARRAY['glutes']::text[],
  ARRAY['For this movement a wooden floor or similar is needed. Lay on your back with your legs extended. Place a gym towel or a light weight underneath your heel. This will be your starting position.', 'Begin the movement by flexing the knee, keeping your other leg straight.', 'Continue bringing the heel closer to you, sliding it on the floor.', 'At full knee flexion, reverse the movement to return to the starting position.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Platform_Hamstring_Slides/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '393097a5-e6d1-5d6d-91c0-3152353390ce',
  'dumbbell plie squat',
  'Plie Dumbbell Squat',
  'legs',
  'dumbbell',
  'quadriceps',
  ARRAY['abdominals', 'calves', 'glutes', 'hamstrings']::text[],
  ARRAY['Hold a dumbbell at the base with both hands and stand straight up. Move your legs so that they are wider than shoulder width apart from each other with your knees slightly bent.', 'Your toes should be facing out. Note: Your arms should be stationary while performing the exercise. This is the starting position.', 'Slowly bend the knees and lower your legs until your thighs are parallel to the floor. Make sure to inhale as this is the eccentric part of the exercise.', 'Press mainly with the heel of the foot to bring the body back to the starting position while exhaling.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Plie_Dumbbell_Squat/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '64660e94-2f5b-5c21-8f7b-847cbafc87b9',
  'plyo pushup',
  'plyo push up',
  'chest',
  'bodyweight',
  'pectorals',
  ARRAY['triceps', 'deltoids', 'core']::text[],
  ARRAY['Step:1 Begin in a high plank position with your hands just beyond shoulder width.', 'Step:2 Lower your chest toward the ground by bending your elbows, keeping your body in a straight line.', 'Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Step:4 Bend your elbows to lower your chest while keeping your body in one line.', 'Step:5 Keep the head in line with the spine as the elbows bend.', 'Step:6 Press back to straight arms, keeping the body line intact.']::text[],
  'https://static.exercisedb.dev/media/Snj1wSv.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  '83b4cf4f-32e2-5320-b641-b7fb8c8380e9',
  'pelvic posterior tilt',
  'Posterior Pelvic Tilt',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Lie on your back with knees bent, feet flat on the floor. Flatten your lower back against the floor by tilting your pelvis posteriorly, engaging your abs and glutes. Hold 5 seconds, release. This retrains pelvic positioning to counter anterior pelvic tilt.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'Raj'
),
(
  '349005aa-398a-5138-a2c2-77ff278a3e6d',
  'overhead posterior reach step',
  'posterior step to overhead reach',
  'core',
  'bodyweight',
  'abdominals',
  ARRAY['glutes', 'hamstrings', 'quadriceps', 'deltoids']::text[],
  ARRAY['Step:1 Stand and set your feet about hip width and your arms by your sides.', 'Step:2 Step back with your right foot, landing on the ball of your foot.', 'Step:3 Set your stance wide enough to balance before bending either knee.', 'Step:4 Step back into a lunge while reaching both arms overhead, then drive forward to stand.', 'Step:5 Keep the front foot planted and avoid collapsing inward at the knee.', 'Step:6 Push through the lead foot to return to the start, then change legs as planned.']::text[],
  'https://static.exercisedb.dev/media/ErqK3UL.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  '8fb0bf19-b500-585f-aa33-b198934ee466',
  'posterior stretch tibialis',
  'posterior tibialis stretch',
  'legs',
  'rope',
  'calves',
  ARRAY['hamstrings', 'quadriceps']::text[],
  ARRAY['Step:1 Take a seat on the ground with your legs extended in front of you.', 'Step:2 Thread the rope around the ball of your foot and hold the ends of the rope with your hands.', 'Step:3 Settle into the starting position and take an easy breath before moving deeper.', 'Step:4 Ease toward the stretch until you feel mild tension, keep breathing and avoid bouncing.', 'Step:5 Stay in a mild stretch rather than pulling farther with momentum.', 'Step:6 Hold the position with steady breathing, then release gently, repeat on the other side if needed.']::text[],
  'https://static.exercisedb.dev/media/DEEqoI2.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  'b13ba2ae-86f6-512a-b7a3-5adf67bf97b7',
  'potty squat',
  'potty squat',
  'core',
  'bodyweight',
  'abdominals',
  ARRAY['quadriceps', 'glutes']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width, toes pointing slightly outward.', 'Step:2 Before moving, lower your body down by bending your knees and pushing your hips back as if you were sitting on a chair.', 'Step:3 Brace the abdomen and spread pressure across the whole foot.', 'Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Step:5 Drive upward with the chest and hips rising together, keep the knees from collapsing inward.', 'Step:6 Stand fully, reset your footing and breathing, then begin the next descent.']::text[],
  'https://static.exercisedb.dev/media/75Bgtjy.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  'cd377a4f-941c-5212-928d-6e9694e9194e',
  'potty squat support',
  'potty squat with support',
  'legs',
  'bodyweight',
  'glutes',
  ARRAY['quadriceps', 'hamstrings', 'calves']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width, toes pointing slightly outward.', 'Step:2 Use a stable support, such as a chair or wall, for balance.', 'Step:3 Brace the abdomen and spread pressure across the whole foot.', 'Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Step:5 Drive upward with the chest and hips rising together, keep the knees from collapsing inward.', 'Step:6 Stand fully, reset your footing and breathing, then begin the next descent.']::text[],
  'https://static.exercisedb.dev/media/b63ZzGe.gif',
