(
  '751286b2-371e-5269-bda0-fc8cc2a93302',
  'clean power',
  'power clean',
  'legs',
  'barbell',
  'hamstrings',
  ARRAY['glutes', 'quadriceps', 'calves']::text[],
  ARRAY['Step:1 Start with the barbell on the ground in front of you, with your feet about shoulder width.', 'Step:2 Bend down and grip the barbell with palms facing down, just beyond shoulder width.', 'Step:3 Brace before the pull and keep the load close to the body.', 'Step:4 Drive through the legs and hips, then guide the weight to its receiving position.', 'Step:5 Receive the load with the torso braced and feet stable.', 'Step:6 Stand tall to finish, then lower the weight under control before the next rep.']::text[],
  'https://static.exercisedb.dev/media/SiWCcTN.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  'd3f3d0bf-8058-5e7f-8dd9-ebb34c28a983',
  'blocks clean power',
  'Power Clean from Blocks',
  'legs',
  'barbell',
  'hamstrings',
  ARRAY['quadriceps']::text[],
  ARRAY['With a barbell on boxes of the desired height, take a grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.', 'Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. As the bar approaches the mid-thigh position, begin extending through the hips.', 'In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight. At the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.', 'As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, pull yourself under the bar far enough that it can be racked onto the shoulders, rotating your elbows under the bar as you do so. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed.', 'Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position, and complete the repetition by returning the weight to the boxes.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Power_Clean_from_Blocks/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'f5100018-c0ea-59d5-8d22-f2591b7aef8f',
  'jerk power',
  'Power Jerk',
  'legs',
  'barbell',
  'quadriceps',
  ARRAY['abdominals', 'calves', 'glutes', 'hamstrings', 'shoulders', 'triceps']::text[],
  ARRAY['Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible.', 'Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders.', 'At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible. In the brief moment the feet are not actively driving against the platform, the athletes effort to push the bar up will drive them down. The feet should be moved to a slightly wider stance, with the knees partially bent.', 'Receive the bar with the arms locked out overhead.', 'Return to a standing position.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Power_Jerk/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '8a83f7e7-c082-540b-a00f-1aaae8627a19',
  'partials power',
  'Power Partials',
  'shoulders',
  'dumbbell',
  'shoulders',
  '{}'::text[],
  ARRAY['Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso.', 'The palms of the hands should be facing your torso. Your feet should be about shoulder width apart. This will be your starting position.', 'Keeping your arms straight and the torso stationary, lift the weights out to your sides until they are about shoulder level height while exhaling.', 'Feel the contraction for a second and begin to lower the weights back down to the starting position while inhaling. Tip: Keep the palms facing down with the little finger slightly higher while lifting and lowering the weights as it will concentrate the stress on your shoulders mainly.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Power_Partials/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '02843960-a782-5e13-9fa4-b576b9284926',
  'plank point power',
  'power point plank',
  'core',
  'bodyweight',
  'abdominals',
  ARRAY['deltoids', 'triceps', 'glutes']::text[],
  ARRAY['Step:1 Begin in a high plank position with your hands directly under your shoulders and your body in a straight line from head to toe.', 'Step:2 Brace your trunk and squeeze your glutes to maintain a stable position.', 'Step:3 Brace the abdomen and find a position you can maintain without holding your breath.', 'Step:4 Brace your midsection and hold the position while breathing normally.', 'Step:5 Keep breathing steadily as you maintain the same body line.', 'Step:6 Keep the shape for the planned time, then come out of it with control.']::text[],
  'https://static.exercisedb.dev/media/hCjGsRQ.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  '90870ad5-250e-5811-81a5-f9a19647a758',
  'power snatch',
  'Power Snatch',
  'legs',
  'barbell',
  'hamstrings',
  ARRAY['calves', 'glutes', 'lower back', 'quadriceps', 'shoulders', 'traps', 'triceps']::text[],
  ARRAY['Begin with a loaded barbell on the floor. The bar should be close to or touching the shins, and a wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position.', 'Begin the first pull by driving through the front of the heels, raising the bar from the ground. The back angle should stay the same until the bar passes the knees.', 'Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side.', 'As you move your feet into the receiving position, a slightly wider position, pull yourself below the bar as you elevate the bar overhead. The bar should be received in a partial squat. Continue raising the bar to the overhead position, receiving the bar locked out overhead.', 'Return to a standing position with the weight over head.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Power_Snatch/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'fc0c58be-113f-55d9-b3fd-d68b00831b3c',
  'blocks power snatch',
  'Power Snatch from Blocks',
  'legs',
  'barbell',
  'quadriceps',
  ARRAY['calves', 'forearms', 'glutes', 'hamstrings', 'lower back', 'shoulders', 'traps', 'triceps']::text[],
  ARRAY['Begin with a loaded barbell on boxes or stands of the desired height. A wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar, with the elbows pointed out. This will be the starting position.', 'Begin the first pull by driving through the front of the heels, raising the bar from the boxes.', 'Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side.', 'As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. The feet should move to just outside the hips, turned out as necessary. Receive the bar above a full squat and with the arms fully extended overhead.', 'Keeping the bar aligned over the front of the heels, your head and chest up, drive through heels of the feet to move to a standing position. Carefully return the weight to the boxes.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Power_Snatch_from_Blocks/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'c3931a8e-7c25-5341-92e3-c2769e05b4a1',
  'power stairs',
  'Power Stairs',
  'legs',
  'other',
  'hamstrings',
  ARRAY['adductors', 'calves', 'glutes', 'lower back', 'quadriceps', 'shoulders', 'traps']::text[],
  ARRAY['In the power stairs, implements are moved up a staircase. For training purposes, these can be performed with a tire or box.', 'Begin by taking the implement with both hands. Set your feet wide, with your head and chest up. Drive through the ground with your heels, extending your knees and hips to raise the weight from the ground.', 'As you lean back, attempt to swing the weight onto the stairs, which are usually around 16-18" high. You can use your legs to help push the weight onto the stair.', 'Repeat for 3-5 repetitions, and continue with a heavier weight, moving as fast as possible.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Power_Stairs/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '00acfddf-9f11-59fd-aa04-1da4ca878202',
  'curl preacher',
  'Preacher Curl',
  'biceps',
  'barbell',
  'biceps',
  '{}'::text[],
  ARRAY['To perform this movement you will need a preacher bench and an E-Z bar. Grab the E-Z curl bar at the close inner handle (either have someone hand you the bar which is preferable or grab the bar from the front bar rest provided by most preacher benches). The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar.', 'With the upper arms positioned against the preacher bench pad and the chest against it, hold the E-Z Curl Bar at shoulder length. This will be your starting position.', 'As you breathe in, slowly lower the bar until your upper arm is extended and the biceps is fully stretched.', 'As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the bar is at shoulder height. Squeeze the biceps hard and hold this position for a second.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Preacher_Curl/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
