(
  'ae733ece-b792-58ad-aa04-5916ea42db65',
  'press sit up',
  'Press Sit-Up',
  'core',
  'barbell',
  'abdominals',
  ARRAY['chest', 'shoulders', 'triceps']::text[],
  ARRAY['To begin, lie down on a bench with a barbell resting on your chest. Position your legs so they are secure on the extension of the abdominal bench. This is the starting position.', 'While inhaling, tighten your abdominals and glutes. Simultaneously curl your torso as you do when performing a sit-up and press the barbell to an overhead position while exhaling. Tip: Use your arms to push the barbell out as you perform this exercise while still focusing on the abdominal muscles.', 'Lower your upper body back down to the starting position while bringing the barbell back down to your torso. Remember to breathe in while lowering the body.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Press_Sit-Up/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
