  'prone stabilityball twist',
  'prone twist on stability ball',
  'core',
  'stability ball',
  'abdominals',
  ARRAY['obliques', 'erector spinae']::text[],
  ARRAY['Step:1 Begin by lying face down on a stability ball with your feet about shoulder width and your toes touching the ground.', 'Step:2 Set your hands behind your head or cross them over your chest.', 'Step:3 Set the pelvis and make the turn through the rib cage.', 'Step:4 Turn through the torso while the hips and lower body stay as steady as the setup allows.', 'Step:5 Keep the ball steady and use the feet to manage your balance.', 'Step:6 Return through center before turning to the other side.']::text[],
