  'Prowler Sprint',
  'legs',
  'other',
  'hamstrings',
  ARRAY['calves', 'chest', 'glutes', 'quadriceps', 'shoulders']::text[],
  ARRAY['Place your sled on an appropriate surface, loaded to a suitable weight. The sled should provide enough resistance to require effort, but not so heavy that you are significantly slowed down.', 'You may use the upright or the low handles for this exercise. Place your hands on the handles with your arms extended, leaning into the implement.', 'With good posture, drive through the ground with alternating, short steps. Move as fast as you can for a short distance.']::text[],
