(
  '5c71fd25-0eb1-5791-b3ae-a2649d7e08be',
  'pull through',
  'Pull Through',
  'legs',
  'cable',
  'glutes',
  ARRAY['hamstrings', 'lower back']::text[],
  ARRAY['Begin standing a few feet in front of a low pulley with a rope or handle attached. Face away from the machine, straddling the cable, with your feet set wide apart.', 'Begin the movement by reaching through your legs as far as possible, bending at the hips. Keep your knees slightly bent. Keeping your arms straight, extend through the hip to stand straight up. Avoid pulling upward through the shoulders, all of the motion should originate through the hips.']::text[],
