(
  '3fca807f-88ab-5f52-8597-deca6ae91650',
  'pushup rotations',
  'Push-up rotations',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Starting position:', 'Get into the starting push-up position, with your hands and toes touching the ground and back, arms and legs straight. To get to this position, you can lie down on your stomach, place your hands facing down next to your head, and lifting your arms up until they are straight.', 'Steps:', '1. Perform a standard push-up:', '1.a Bend arms until chest almost touches the ground, making sure the back is straight.1.b Use your arms to lift yourself back up to starting position.', '2. Rotate your body to the side so that the back is straight, the bottom hand supporting the body is fully extended, and only the bottom hand and foot touch the floor.', '3. Repeat, changing sides at step 2 each time.']::text[],
  null,
  null,
