  ARRAY['Step:1 Begin in a push-up position with your hands about shoulder width and your body in a straight line.', 'Step:2 Lower your body toward the ground by bending your elbows, keeping your core engaged.', 'Step:3 Brace the abdomen and find a position you can maintain without holding your breath.', 'Step:4 Brace your midsection and hold the position while breathing normally.', 'Step:5 Keep breathing steadily as you maintain the same body line.', 'Step:6 Keep the shape for the planned time, then come out of it with control.']::text[],
