(
  '1b2a2ea1-3c00-5f6c-82d8-386cf3515779',
  'close position pushup triceps',
  'Push-Ups - Close Triceps Position',
  'triceps',
  'body only',
  'triceps',
  ARRAY['chest', 'shoulders']::text[],
  ARRAY['Lie on the floor face down and place your hands closer than shoulder width for a close hand position. Make sure that you are holding your torso up at arms'' length.', 'Lower yourself until your chest almost touches the floor as you inhale.', 'Using your triceps and some of your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.', 'After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Push-Ups_-_Close_Triceps_Position/0.jpg',
  'image',
