),
(
  '924c42d6-f0e0-5efb-953e-0d6ce6bcda6f',
  'parallettes pushup',
  'Push-Ups | Parallettes',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Parallettes push-ups are a variation of the traditional push-up that are performed with the hands on parallel bars, known as parallettes. To perform a parallettes push-up, assume a push-up position with your hands on the parallettes and your feet on the ground. Lower your body towards the ground while keeping your elbows close to your sides, and then push back up to the starting position.', 'Parallettes push-ups place more emphasis on the chest and shoulders compared to traditional push-ups, as they allow for a greater range of motion in the shoulder joint. This increased range of motion can also help to improve shoulder stability and mobility. Additionally, parallettes push-ups engage the core muscles more than traditional push-ups, as the instability of the parallettes requires greater activation of the core muscles to maintain proper form.', 'The added challenge of balancing on the parallettes also requires greater upper body strength and control, making parallettes push-ups a more advanced variation of the traditional push-up. They can be a great way to challenge yourself and add variety to your upper body workout routine. As always, be sure to use proper form and start with a level that is appropriate for your strength and fitness level.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'anon1337'
),
(
  '928b46e3-7047-5f1d-804b-256768c34a5f',
  'elevated feet pushup',
  'Push-Ups With Feet Elevated',
  'chest',
  'body only',
  'chest',
  ARRAY['shoulders', 'triceps']::text[],
  ARRAY['Lie on the floor face down and place your hands about 36 inches apart from each other holding your torso up at arms length.', 'Place your toes on top of a flat bench. This will allow your body to be elevated. Note: The higher the elevation of the flat bench, the higher the resistance of the exercise is.', 'Lower yourself until your chest almost touches the floor as you inhale.', 'Using your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.', 'After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Push-Ups_With_Feet_Elevated/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
