  '',
  '{}'::text[],
  ARRAY['# What Are Quad Sets?', 'Quad sets are a fundamental exercise used in knee rehabilitation. They focus on strengthening the quadriceps muscles located at the front of the thigh. This exercise is particularly beneficial for individuals recovering from knee injuries or surgeries.', '## How to Perform Quad Sets', '### Steps to Execute Quad Sets', '1. **Positioning:** Sit or lie down with your legs straight.', '2. **Tightening:** Tighten the quadriceps muscles while keeping the leg straight. You should see the kneecap move upward.', '3. **Holding:** Maintain the contraction for about 5 seconds.', '4. **Releasing:** Relax the muscle after the hold.', '5. **Repetitions:** Aim for 10 to 15 repetitions, gradually increasing as strength improves.', '### Tips for Effective Quad Sets', '- Ensure no other muscles are contracting to assist the quadriceps.', '- Perform the exercise on a flat surface, like a bed or couch, with a towel or pillow under your heel for comfort.', '- It is recommended to do these exercises multiple times a day, especially during the early stages of recovery.', '## Benefits of Quad Sets', '- **Restores Muscle Function:** Helps rebuild strength in the quadriceps.', '- **Improves Stability:** Enhances stability in the knee joint.', '- **Increases Range of Motion:** Aids in regaining mobility after injury or surgery.', 'Incorporating quad sets into your rehabilitation routine can significantly aid in recovery and improve overall knee function.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'aboksz'
),
