  'radio taiso',
  'Radio Taiso',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Video can be found here : https://www.youtube.com/watch?v=SGPBSqxKGAc', 'Full-body mobility and dynamic warm-up routine (3–5 minutes) to prepare joints, muscles, and the cardiovascular system for workout.', 'Movement Flow:', 'Deep Breathing & Arm Raises: Inhale while raising arms laterally overhead, exhale as you lower them.', 'Knee Bends: Soft, rhythmic knee flexions synchronized with arm swings.', 'Arm Circles: Large full-range arm rotations forward, then backward to open up the chest and shoulder girdle.', 'Chest Expansion: Cross arms in front of the chest and open wide to the sides.', 'Side Bends: Reach overhead to stretch the lateral torso left and right with a smooth side flexion.', 'Forward & Back Bends: Gently hinge at the hips to reach forward, then return upright with a mild spinal extension.', 'Torso Twists: Swing arms side-to-side to rotate the spine and loosen the core.', 'Ankle Mobility / Light Bounces: Soft heel lifts or light bouncing on toes to warm up lower leg joints and tendons.']::text[],
  null,
  null,
