(
  '4d23b1b8-f6b5-5eac-8e48-11ad46ca923d',
  'push return stance',
  'Return Push from Stance',
  'shoulders',
  'medicine ball',
  'shoulders',
  ARRAY['chest', 'triceps']::text[],
  ARRAY['You will need a partner for this drill.', 'Begin in an athletic 2 or 3 point stance.', 'At the signal, move into a position to receive the pass from your partner.', 'Catch the medicine ball with both hands and immediately throw it back to your partner.', 'You can modify this drill by running different routes.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Return_Push_from_Stance/0.jpg',
