  'core',
  'bodyweight',
  'abdominals',
  ARRAY['hip flexors']::text[],
  ARRAY['Step:1 Settle onto your back with your arms extended along your sides.', 'Step:2 Before moving, bend your knees and lift your feet off the ground, bringing your thighs perpendicular to the floor.', 'Step:3 Set the pelvis and keep the neck relaxed before curling upward.', 'Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.', 'Step:5 Leave a little space between the chin and chest, keep the movement in the torso.', 'Step:6 Lower the shoulders or torso with control before the next curl.']::text[],
