  '{}'::text[],
  ARRAY['1. Stand with a good posture holding a cable in each hand opposite the machine', '2. Starting with the hands in front of your chest pull the arms out to', 'your side into the shape of a T with the elbows nearly straight', '3. Slowly release the arms forward to the start', '4. Repeat with the arms moving into the shape of a Y', '5. Repeat with the arms in the shape of a W', '6. Repeat with the arms in the shape of an L by your side']::text[],
