(
  '83d8248f-950a-58c5-b17b-1e5ffd5d91db',
  'bentover reverse row',
  'Reverse Grip Bent-Over Rows',
  'back',
  'barbell',
  'middle back',
  ARRAY['biceps', 'lats', 'shoulders']::text[],
  ARRAY['Stand erect while holding a barbell with a supinated grip (palms facing up).', 'Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.', 'While keeping the torso stationary, lift the barbell as you breathe out, keeping the elbows close to the body and not doing any force with the forearm other than holding the weights. On the top contracted position, squeeze the back muscles and hold for a second.', 'Slowly lower the weight again to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Grip_Bent-Over_Rows/0.jpg',
  'image',
