),
(
  'f9bcf80b-f321-579a-ab7c-18a095bd9427',
  'extension hyper reverse stabilityball',
  'reverse hyper extension (on stability ball)',
  'legs',
  'stability ball',
  'glutes',
  ARRAY['hamstrings', 'erector spinae']::text[],
  ARRAY['Step:1 Position yourself face down on a stability ball with your hips resting on the ball and your legs extended straight behind you.', 'Step:2 Set your hands on the ground in front of you for stability.', 'Step:3 Secure the hips and feet on the support before lifting.', 'Step:4 Raise your torso or legs until they line up with your body, without arching sharply at the lower back.', 'Step:5 Keep the ball steady and use the feet to manage your balance.', 'Step:6 Ease back to the start before repeating.']::text[],
