  ARRAY['Step:1 Position yourself face down on a flat bench with your hips at the edge and your legs hanging off the bench.', 'Step:2 Use the bench for stability.', 'Step:3 Secure the hips and feet on the support before lifting.', 'Step:4 Raise your torso or legs until they line up with your body, without arching sharply at the lower back.', 'Step:5 Finish in a straight body line, before the lower back overarches.', 'Step:6 Bring the weight or body back to its starting position without rushing.']::text[],
