  'leg lift plank reverse',
  'reverse plank with leg lift',
  'core',
  'bodyweight',
  'abdominals',
  ARRAY['glutes', 'hamstrings', 'deltoids']::text[],
  ARRAY['Step:1 Take a seat on the ground with your legs extended in front of you and your hands resting on the ground behind you, fingers pointing toward your feet.', 'Step:2 Before moving, press through your hands and lift your hips off the ground, coming into a reverse plank position.', 'Step:3 Brace the abdomen and find a position you can maintain without holding your breath.', 'Step:4 Brace your midsection and hold the position while breathing normally.', 'Step:5 Keep breathing steadily as you maintain the same body line.', 'Step:6 Keep the shape for the planned time, then come out of it with control.']::text[],
