(
  '367a4e6f-0d4f-58e6-80f4-1af7ed3b5c04',
  'bench press reverse triceps',
  'Reverse Triceps Bench Press',
  'triceps',
  'barbell',
  'triceps',
  ARRAY['chest', 'shoulders']::text[],
  ARRAY['Lie back on a flat bench. Using a close, supinated grip (around shoulder width), lift the bar from the rack and hold it straight over you with your arms locked extended in front of you and perpendicular to the floor. This will be your starting position.', 'As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that as opposed to a regular bench press, you keep the elbows close to the torso at all times in order to maximize triceps involvement.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the bar back in the rack.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Triceps_Bench_Press/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'e853e812-a3df-525d-a2a6-5637390e55e4',
  'reverse squat v',
  'Reverse V-Squat',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Step into the V-squat machine facing the pad, the opposite way from the regular V-squat, so that your chest rests against the pad and your shoulders sit under the shoulder pads. Place your feet on the platform about shoulder width apart and release the safety.', 'Brace your core and lower yourself by bending your knees and pushing the hips back until your thighs are roughly parallel to the platform. Drive back up through the heels without locking out the knees.', 'Compared to the regular V-squat, the reversed position shifts the emphasis towards the glutes and hamstrings.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'aboksz'
),
