  ARRAY['* Attach a looping resistance band to a rack below knee height', '* Grip the other end of the band like holding a baseball bat with both hands', '* Stretch the band facing it', '* Start with your hands at the side of your hips, knees bent', '* Rotate your hips while moving your hands towards over the top of your opposite shoulder', '* Imagine the motion as striking a baseball with a bat']::text[],
