  ARRAY['Step:1 Take hold of the pull-up bar with palms facing up, hands about shoulder width.', 'Step:2 Suspend yourself from the bar with your arms straight and your body straight.', 'Step:3 Begin from a controlled hang with the shoulders active rather than slack.', 'Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.', 'Step:5 Keep the palms in the chosen grip without bending the wrists back.', 'Step:6 Lower to long arms without dropping suddenly from the top.']::text[],
