  'other',
  'forearms',
  ARRAY['abdominals', 'calves', 'glutes', 'hamstrings', 'lower back', 'quadriceps', 'traps']::text[],
  ARRAY['Position the frame at the starting point, and load with the appropriate weight. Standing in the center of the frame, begin by gripping the handles and driving through your heels to lift the frame. Ensure your chest and head are up and your back is straight.', 'Immediately begin walking briskly with quick, controlled steps. Keep your chest up and head forward, and make sure you continue breathing. Bring the frame to the ground after you have reached the end point.']::text[],
