  ARRAY['Begin in a relaxed stance with your feet shoulder width apart and hold your arms close to the body.', 'To initiate the move, squat down halfway and explode back up as high as possible.', 'Fully extend your entire body, reaching overhead as far as possible. As you land, absorb your impact through the legs.']::text[],
