  'legs',
  'bodyweight',
  'glutes',
  ARRAY['hamstrings', 'quadriceps']::text[],
  ARRAY['Step:1 Begin by kneeling on the ground with your knees about hip width.', 'Step:2 Set your hands on the ground in front of you for support.', 'Step:3 Settle into the starting position and take an easy breath before moving deeper.', 'Step:4 Ease toward the stretch until you feel mild tension, keep breathing and avoid bouncing.', 'Step:5 Stay in a mild stretch rather than pulling farther with momentum.', 'Step:6 Hold the position with steady breathing, then release gently, repeat on the other side if needed.']::text[],
