  ARRAY['deltoids', 'triceps', 'core']::text[],
  ARRAY['Step:1 Begin in a plank position with your forearms on the roller and your body in a straight line.', 'Step:2 Brace your trunk and With control roll the roller forward, extending your body as far as you can while maintaining control.', 'Step:3 Tighten the abdomen and keep the pelvis tucked before the arms reach away.', 'Step:4 Reach the arms away while keeping your ribs and pelvis aligned, stop before the lower back sags.', 'Step:5 Stop reaching when the lower back starts to sag.', 'Step:6 Pull back to the start through your shoulders and abdominals, keeping the same body line.']::text[],
