  ARRAY['deltoids', 'triceps']::text[],
  ARRAY['Step:1 Take a seat on a flat surface with your legs extended in front of you.', 'Step:2 Take hold of the roller with both hands, palms facing down, and place it on your thighs.', 'Step:3 Brace the torso and align the wrists with the forearms.', 'Step:4 Press the weight or handles away while keeping your trunk braced.', 'Step:5 Keep the wrists stacked and use a shoulder path that feels natural.', 'Step:6 Lower the weight to its starting height under control before pressing again.']::text[],
