(
  'f339918b-c38a-543c-a621-b5c3f267258b',
  'romaniandeadlift',
  'Romanian Deadlift',
  'legs',
  'barbell',
  'hamstrings',
  ARRAY['calves', 'glutes', 'lower back']::text[],
  ARRAY['Put a barbell in front of you on the ground and grab it using a pronated (palms facing down) grip that a little wider than shoulder width. Tip: Depending on the weight used, you may need wrist wraps to perform the exercise and also a raised platform in order to allow for better range of motion.', 'Bend the knees slightly and keep the shins vertical, hips back and back straight. This will be your starting position.', 'Keeping your back and arms completely straight at all times, use your hips to lift the bar as you exhale. Tip: The movement should not be fast but steady and under control.', 'Once you are standing completely straight up, lower the bar by pushing the hips back, only slightly bending the knees, unlike when squatting. Tip: Take a deep breath at the start of the movement and keep your chest up. Hold your breath as you lower and exhale as you complete the movement.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Romanian_Deadlift/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'd17dff9e-2b67-52ea-8e44-f9e03baeaeaf',
  'deficit romaniandeadlift',
  'Romanian Deadlift from Deficit',
  'legs',
  'barbell',
  'hamstrings',
  ARRAY['forearms', 'glutes', 'lower back', 'traps']::text[],
  ARRAY['Begin standing while holding a bar at arm''s length in front of you. You can stand on a raised platform to increase the range of motion.', 'Begin by flexing the knees slightly, and then flex at the hip, moving your butt back as far as possible, lowering the torso as far as flexibility allows. The back should remain in absolute extension at all times, and the bar should remain in contact with the legs. If done properly, there should be heavy tension felt in the hamstrings.', 'Reverse the motion to return to the starting position.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Romanian_Deadlift_from_Deficit/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'e21b45eb-2d38-5405-bca1-b0b7a9d3e591',
