  'upper back',
  ARRAY['forearms', 'biceps', 'deltoids']::text[],
  ARRAY['Step:1 Face the rope from a stable stance with feet about shoulder width.', 'Step:2 Take hold of the rope with both hands, palms facing toward you.', 'Step:3 Begin from a controlled hang with the shoulders active rather than slack.', 'Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.', 'Step:5 Avoid swinging the legs to clear the bar.', 'Step:6 Lower to long arms without dropping suddenly from the top.']::text[],
  'https://static.exercisedb.dev/media/yaAxcQr.gif',
