),
(
  '7ea99273-07b5-51ae-8391-a58926600699',
  'jumping rope',
  'Rope Jumping',
  'legs',
  'other',
  'quadriceps',
  ARRAY['calves', 'hamstrings']::text[],
  ARRAY['Hold an end of the rope in each hand. Position the rope behind you on the ground. Raise your arms up and turn the rope over your head bringing it down in front of you. When it reaches the ground, jump over it. Find a good turning pace that can be maintained. Different speeds and techniques can be used to introduce variation.', 'Rope jumping is exciting, challenges your coordination, and requires a lot of energy. A 150 lb person will burn about 350 calories jumping rope for 30 minutes, compared to over 450 calories running.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rope_Jumping/0.jpg',
  'image',
