  ARRAY['quadriceps', 'hamstrings', 'calves']::text[],
  ARRAY['Step:1 Begin by standing upright with your feet about hip width.', 'Step:2 Brace your trunk and keep your upper body relaxed.', 'Step:3 Start at a pace that lets the feet and arms move in sync.', 'Step:4 Move at a repeatable pace, keeping the motion smooth and your breathing steady.', 'Step:5 Keep the pattern repeatable as speed increases.', 'Step:6 Keep the rhythm for the planned interval, slowing if your form starts to slip.']::text[],
