  'Russian Push Ups',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Russian Push-Ups', 'Start in a standard push-up position with your hands slightly wider than shoulder-width apart. Lower your chest toward the floor, then shift your body forward while keeping your chest close to the ground. Extend your arms to return to the starting position, then reverse the movement smoothly. Keep your core tight and maintain controlled movement throughout the exercise.']::text[],
