  'bodyweight',
  'abdominals',
  ARRAY['obliques']::text[],
  ARRAY['Step:1 Take a seat on the ground with your knees bent and feet planted.', 'Step:2 Lean back slightly while with your spine steady and your core engaged.', 'Step:3 Set the pelvis and make the turn through the rib cage.', 'Step:4 Turn through the torso while the hips and lower body stay as steady as the setup allows.', 'Step:5 Keep the turn smooth instead of throwing the arms across the body.', 'Step:6 Return through center before turning to the other side.']::text[],
