(
  'e1e9b784-cceb-5d34-808c-3ad35651c999',
  'load sandbag',
  'Sandbag Load',
  'legs',
  'other',
  'quadriceps',
  ARRAY['abdominals', 'biceps', 'calves', 'forearms', 'glutes', 'hamstrings', 'lower back', 'middle back', 'shoulders', 'traps']::text[],
  ARRAY['To load sandbags or other objects, begin with the implements placed a distance from the loading platform, typically 50 feet.', 'Begin by lifting the sandbag. Sandbags are extremely awkward, and the manner of lifting them can vary depending on the particular sandbag used. Reach as far around it as possible, extending through the hips and knees to pull it up high. Shouldering is usually not allowed.', 'Move as quickly as possible to the platform, and load it, extending through your hips, knees, and ankles to get it as high as possible. Place it onto the platform, ensuring it doesn''t fall off.', 'Return to the starting position to retrieve the next sandbag, and repeat until the event is completed.']::text[],
