  'trapezius',
  ARRAY['rhomboids', 'deltoids']::text[],
  ARRAY['Step:1 Begin by standing with your feet about shoulder width and your arms extended in front of you.', 'Step:2 Bend your knees slightly and hinge forward at the hips, with your spine steady.', 'Step:3 Set the shoulders down and keep the elbows pointed mostly behind you.', 'Step:4 Bend the elbows to lower between the supports, stop at a comfortable shoulder depth.', 'Step:5 Choose a depth that lets the shoulders stay comfortable.', 'Step:6 Press through the hands to rise, then reset the shoulders before another rep.']::text[],
