  ARRAY['biceps', 'rhomboids', 'rear deltoids']::text[],
  ARRAY['Step:1 Begin by hanging from a pull-up bar with your palms turned away from you and your arms straight.', 'Step:2 Draw back your shoulder blades by pulling them down and back.', 'Step:3 Begin from a controlled hang with the shoulders active rather than slack.', 'Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.', 'Step:5 Avoid swinging the legs to clear the bar.', 'Step:6 Lower to long arms without dropping suddenly from the top.']::text[],
