  'bodyweight',
  'cardiovascular system',
  ARRAY['quadriceps', 'hamstrings', 'calves']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width.', 'Step:2 Jump off the ground and simultaneously cross your right leg ahead of your left leg.', 'Step:3 Bend the hips and knees slightly to load the jump.', 'Step:4 Load the legs with a small bend, then drive through the floor and land softly.', 'Step:5 Land with bent hips and knees and let the feet absorb the impact.', 'Step:6 Absorb the landing through the hips and knees before repeating.']::text[],
