  '',
  '{}'::text[],
  ARRAY['Scissors is an abdominal exercise that strengthens the transverse abdominals, helping flatten your belly and strengthen your entire core. Scissors is not only a core strength move, but it is also a great stretch for your hamstrings and your lower back. Everyone is looking for new ways to work the core, to flatten the belly and to improve flexibility. If you learn how to do Scissors you will get everything rolled together in one move.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'vkylamba'
),
(
  'e98fecc9-4724-5581-9346-56b1806ef161',
  'jump scissors',
  'Scissors Jump',
  'legs',
  'body only',
  'quadriceps',
  ARRAY['glutes', 'hamstrings']::text[],
  ARRAY['Assume a lunge stance position with one foot forward with the knee bent, and the rear knee nearly touching the ground.', 'Ensure that the front knee is over the midline of the foot. Extending through both legs, jump as high as possible, swinging your arms to gain lift.', 'As you jump as high as you can, switch the position of your legs, moving your front leg to the back and the rear leg to the front.', 'As you land, absorb the impact through the legs by adopting the lunge position, and repeat.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Scissors_Jump/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '0b1960cd-1cef-5156-9aa4-44c3a3785cdb',
  'kick scorpion',
  'Scorpion Kick',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['**Get into the push-up position with your shoulders directly above your hands and your feet hip-width apart.**', '**Make sure that your body forms a straight line from your head to your heels.**', '**Now pull your right knee towards your chest. While keeping your knee bent, lift your right leg as high as possible with your lower right leg pointing straight up.**', '**Now rotate your hips so that your right foot swings over your left leg.**', '**Continue to rotate and move your right foot towards the floor until you are forced to roll onto the outside of your left standing foot. Make sure that you do not rotate your upper body.**', '**Now return to the starting position and repeat the exercise with your left leg.**']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'lxmx'
),
(
  'f0a5658c-2241-52a7-a5a3-e9b3fa1c00ce',
  'back extension machine seated',
  'Seated Back Extension Machine',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['1. Adjust the seat and the back pad so that the pad sits at the height of your shoulder blades or mid-back.', '2. Sit in the machine with your hips and lower back against the seat and backrest and your feet on the platform. Cross your arms over your chest or hold the handles.', '3. Exhale and push the pad backwards using your lower back muscles until your spine is in line with your hips. Pause for a second at the end position.', '4. Inhale and slowly return to the starting position, without letting the weight stack slam down.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'Franpol'
),
(
  'acbd54a1-064b-5ea3-8e2d-61a94116202e',
  'band curl hamstring seated',
  'Seated Band Hamstring Curl',
  'legs',
  'other',
  'hamstrings',
  '{}'::text[],
  ARRAY['Secure a band close to the ground and place a bench a couple feet away from it.', 'Seat yourself on the bench and secure the band behind your ankles, beginning with your legs straight. This will be your starting position.', 'Flex the knees, bringing your feet towards the bench. You may need to lean back slightly to keep your feet from striking the floor.', 'Pause at the completion of the movement, and then slowly return to the starting position.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Band_Hamstring_Curl/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '822674a9-c0ca-53a6-a057-9ebaa118c321',
  'band row seated',
  'Seated Band Row',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Sit on the floor with your legs straight out in front of you and your back tall. Loop a resistance band around the soles of both feet and hold one end in each hand, arms extended and a slight bend in the knees. Pull the band toward your lower ribs by driving your elbows straight back and squeezing your shoulder blades together. Keep your chest up and your torso still rather than rocking backward to move the band. Extend the arms slowly to return. Because the torso stays upright and supported, this is a useful row when a bent-over position is uncomfortable, and it needs no anchor point.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'trs1800'
),
(
  '2e1fc184-3c1c-5eaa-acfe-f098350a0412',
  'barbell military press seated',
  'Seated Barbell Military Press',
  'shoulders',
  'barbell',
  'shoulders',
  ARRAY['triceps']::text[],
  ARRAY['Sit on a Military Press Bench with a bar behind your head and either have a spotter give you the bar (better on the rotator cuff this way) or pick it up yourself carefully with a pronated grip (palms facing forward). Tip: Your grip should be wider than shoulder width and it should create a 90-degree angle between the forearm and the upper arm as the barbell goes down.', 'Once you pick up the barbell with the correct grip length, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.', 'Lower the bar down to the collarbone slowly as you inhale.', 'Lift the bar back up to the starting position as you exhale.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Barbell_Military_Press/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'c84164ab-d602-5582-b5db-87f2620b23da',
  'bench press seated',
  'Seated Bench Press',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Set up the chest press machine so that the grips are aligned with your lower chest when you sit down. Make sure you''re sitting with your back flat against the seat. Grab a handle in each hand, stick your chest out, and keep your head against the headrest. Breathe deeply and slowly push the handles forward until your arms are almost fully extended. Pause just before the lockout, then slowly return the handles to the starting position. Pause just before the handles come to a complete stop and perform another repetition.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'colundrum'
),
(
  '92b063cf-921d-58db-8262-7cc66189ff53',
  'bentover dumbbell extension seated singlearm triceps',
  'Seated Bent-Over One-Arm Dumbbell Triceps Extension',
  'triceps',
  'dumbbell',
  'triceps',
  '{}'::text[],
  ARRAY['Sit down at the end of a flat bench with a dumbbell in one arm using a neutral grip (palms of the hand facing you).', 'Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Make sure that you keep the head up.', 'The upper arm with the dumbbell should be close to the torso and aligned with it (lifted up until it is parallel to the floor while the forearms are pointing towards the floor as the hands hold the weights). Tip: There should be a 90-degree angle between the forearms and the upper arm. This is your starting position.', 'Keeping the upper arm stationary, use the triceps to lift the weight as you exhale until the forearm is parallel to the floor and the whole arm is extended. Like many other arm exercises, only the forearm moves.', 'After a second contraction at the top, slowly lower the dumbbell back to the starting position as you inhale.', 'Repeat the movement for the prescribed amount of repetitions.', 'Switch arms and repeat the exercise.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Bent-Over_One-Arm_Dumbbell_Triceps_Extension/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '1fe70f94-eeb7-52af-a96f-e1d3c0db0bc0',
  'bentover delt raise rear seated',
  'Seated Bent-Over Rear Delt Raise',
  'shoulders',
  'dumbbell',
  'shoulders',
  '{}'::text[],
  ARRAY['Place a couple of dumbbells looking forward in front of a flat bench.', 'Sit on the end of the bench with your legs together and the dumbbells behind your calves.', 'Bend at the waist while keeping the back straight in order to pick up the dumbbells. The palms of your hands should be facing each other as you pick them. This will be your starting position.', 'Keeping your torso forward and stationary, and the arms slightly bent at the elbows, lift the dumbbells straight to the side until both arms are parallel to the floor. Exhale as you lift the weights. (Note: avoid swinging the torso or bringing the arms back as opposed to the side.)', 'After a one second contraction at the top, slowly lower the dumbbells back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Bent-Over_Rear_Delt_Raise/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '7a8a2dde-0e2b-51a9-9cf2-c4ac524e9a30',
  'arm bentover dumbbell extension seated triceps',
  'Seated Bent-Over Two-Arm Dumbbell Triceps Extension',
  'triceps',
  'dumbbell',
  'triceps',
  '{}'::text[],
  ARRAY['Sit down at the end of a flat bench with a dumbbell in both arms using a neutral grip (palms of the hand facing you).', 'Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Make sure that you keep the head up.', 'The upper arms with the dumbbells should be close to the torso and aligned with it (lifted up until they are parallel to the floor while the forearms are pointing towards the floor as the hands hold the weights). Tip: There should be a 90-degree angle between the forearms and the upper arm. This is your starting position.', 'Keeping the upper arms stationary, use the triceps to lift the weight as you exhale until the forearms are parallel to the floor and the whole arm is extended. Like many other arm exercises, only the forearm moves.', 'After a second contraction at the top, slowly lower the dumbbells back to the starting position as you inhale.', 'Repeat the movement for the prescribed amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension/0.jpg',
  'image',
