),
(
  '00169b00-b1d3-5dbd-b9b9-5cf77317e900',
  'biceps seated',
  'Seated Biceps',
  'biceps',
  'body only',
  'biceps',
  ARRAY['chest', 'shoulders']::text[],
  ARRAY['Sit on the floor with your knees bent and your partner standing behind you. Extend your arms straight behind you with your palms facing each other. Your partner will hold your wrists for you. This will be the starting position.', 'Attempt to flex your elbows, while your partner prevents any actual movement.', 'After 10-20 seconds, relax your arms while your partner gently pulls your wrists up to stretch your biceps. Be sure to let your partner know when the stretch is appropriate to prevent injury or overstretching.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Biceps/0.jpg',
  'image',
