),
(
  '05ed58cd-6f9e-56a2-a1cf-777afd6c2bf8',
  'cable chest fly seated',
  'Seated Cable chest fly',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['1. Place a bench between two cable pulleys and adjust the pulleys so they are at chest/shoulder height when you are seated.', '2. Grab the handles with a neutral grip and lean against the upright backrest.', '3. Bring your arms together in front of your chest in a controlled motion, focusing on squeezing your chest muscles. Keep your elbows slightly bent throughout the movement.', '4. Pause briefly at the top position.', '5. Slowly lower your arms back to the starting position while maintaining control of the movement.', '6. Repeat for reps.']::text[],
  null,
  null,
