(
  '980813a3-ee0e-521d-a94c-3bd45b9f4406',
  'cable press seated shoulder',
  'Seated Cable Shoulder Press',
  'shoulders',
  'cable',
  'shoulders',
  ARRAY['triceps']::text[],
  ARRAY['Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 90 degrees to the body, with your head and chest up. The elbows should also be bent to about 90 degrees. This will be your starting position.', 'Begin by extending through the elbow, pressing the handles together above your head.', 'After pausing at the top, return the handles to the starting position. Ensure that you maintain tension on the cables.', 'You can also execute this movement with your back off the pad and alternate hands.']::text[],
