),
(
  '495a355c-31e7-564e-bd79-29685cfcdb8f',
  'calf raise seated',
  'Seated Calf Raise',
  'other',
  'machine',
  'calves',
  '{}'::text[],
  ARRAY['Sit on the machine and place your toes on the lower portion of the platform provided with the heels extending off. Choose the toe positioning of your choice (forward, in, or out) as per the beginning of this chapter.', 'Place your lower thighs under the lever pad, which will need to be adjusted according to the height of your thighs. Now place your hands on top of the lever pad in order to prevent it from slipping forward.', 'Lift the lever slightly by pushing your heels up and release the safety bar. This will be your starting position.', 'Slowly lower your heels by bending at the ankles until the calves are fully stretched. Inhale as you perform this movement.', 'Raise the heels by extending the ankles as high as possible as you contract the calves and breathe out. Hold the top contraction for a second.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Calf_Raise/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '38d5edd6-0aee-5d3c-8cc3-c9dc9f976f3d',
  'calf seated stretch',
  'Seated Calf Stretch',
  'legs',
  'bodyweight',
  'calves',
  ARRAY['hamstrings']::text[],
  ARRAY['Step:1 Take a seat on the edge of a chair or bench with your feet planted.', 'Step:2 Reach one leg straight out in front of you, keeping your heel on the ground.', 'Step:3 Settle into the starting position and take an easy breath before moving deeper.', 'Step:4 Ease the heel down and shift until the calf stretches, keep the foot pointed ahead.', 'Step:5 Stay in a mild stretch rather than pulling farther with momentum.', 'Step:6 Hold the position with steady breathing, then release gently, repeat on the other side if needed.']::text[],
  'https://static.exercisedb.dev/media/17bqEXD.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  'f978fe5f-7906-52dc-972a-4c43bf514727',
  'corkscrew seated',
  'Seated Corkscrew',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['To', 'do this abs and obliques exercise, start with your hands back behind your body', 'and bring your knees in and across, really trying to contract the obliques.', 'Then extend your legs back out to starting position and repeat toward the', 'opposite side of the abs.', 'Beginners', 'might find that they can’t even get through the first 45 seconds of this', 'challenging reverse crunches variation. That’s ok because it gives you a', 'place to start and something to improve upon.']::text[],
  null,
  null,
  'wger',
