  'Moffi'
),
(
  '0ee91048-05f3-5826-a6ef-313600788a87',
  'curl down dumbbell palms seated wrist',
  'Seated Dumbbell Palms-Down Wrist Curl',
  'forearms',
  'dumbbell',
  'forearms',
  '{}'::text[],
  ARRAY['Start out by placing two dumbbells on the floor in front of a flat bench.', 'Sit down on the edge of the flat bench with your legs at about shoulder width apart. Make sure to keep your feet on the floor.', 'Use your arms to grab both of the dumbbells and bring them up so that your forearms are resting against your thighs with the palms of the hands facing down. Your wrists should be hanging over the edge of your thighs.', 'Start out by curling your wrist upwards and exhaling.', 'Slowly lower your wrists back down to the starting position while inhaling. Make sure to inhale during this part of the exercise. Tip: Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.', 'Repeat for the recommended amount of repetitions.', 'When finished, simply lower the dumbbells to the floor.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Dumbbell_Palms-Down_Wrist_Curl/0.jpg',
  'image',
