(
  'b31cfbb0-1ec2-55fd-8105-7666ce407fb0',
  'bench leg pull seated',
  'Seated Flat Bench Leg Pull-In',
  'core',
  'body only',
  'abdominals',
  '{}'::text[],
  ARRAY['Sit on a bench with the legs stretched out in front of you slightly below parallel and your arms holding on to the sides of the bench. Your torso should be leaning backwards around a 45-degree angle from the bench. This will be your starting position.', 'Bring the knees in toward you as you move your torso closer to them at the same time. Breathe out as you perform this movement.', 'After a second pause, go back to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[],
