(
  '212f0a7f-6db3-52d0-a4be-37891c170211',
  'deltoid front seated',
  'Seated Front Deltoid',
  'shoulders',
  'body only',
  'shoulders',
  ARRAY['chest']::text[],
  ARRAY['Sit upright on the floor with your legs bent, your partner standing behind you. Stick your arms straight out to your sides, with your palms facing the ground. Attempt to move them as far behind you as possible, as your assistant holds your wrists. This will be your starting position.', 'Keeping your elbows straight, attempt to move your arms to the front, with your partner gently restraining you to prevent any actual movement for 10-20 seconds.', 'Now, relax your muscles and allow your partner to gently increase the stretch on the shoulders and chest. Hold for 10 to 20 seconds.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Front_Deltoid/0.jpg',
  'image',
