  'Unlicense',
  null
),
(
  '74b7a18f-87be-5443-8c8a-68b47a2fe7bd',
  'glute seated',
  'Seated Glute',
  'legs',
  'body only',
  'glutes',
  ARRAY['adductors']::text[],
  ARRAY['In a seated position with your knees bent, cross one ankle over the opposite knee. Your partner will stand behind you. Now, lean forward as your partner braces your shoulders with their hands. This will be your starting position.', 'Attempt to push your torso back for 10-20 seconds, as your partner prevents any actual movement of your torso.', 'Now relax your muscles as your partner increases the stretch by gently pushing your torso forward for 10-20 seconds.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Glute/0.jpg',
