(
  '6be69ca2-5efb-5f28-bc0d-ae083b246f9c',
  'glute seated stretch',
  'seated glute stretch',
  'legs',
  'bodyweight',
  'glutes',
  ARRAY['hamstrings']::text[],
  ARRAY['Step:1 Take a seat on the ground with your legs extended in front of you.', 'Step:2 Before moving, bend your right knee and cross your right ankle over your left thigh.', 'Step:3 Settle into the starting position and take an easy breath before moving deeper.', 'Step:4 Ease toward the stretch until you feel mild tension, keep breathing and avoid bouncing.', 'Step:5 Stay in a mild stretch rather than pulling farther with momentum.', 'Step:6 Hold the position with steady breathing, then release gently, repeat on the other side if needed.']::text[],
  'https://static.exercisedb.dev/media/DeDThfG.gif',
