  'AscendAPI'
),
(
  '1b0875b7-7ef9-52fb-9a92-3e30eaf1ca45',
  'good mornings seated',
  'Seated Good Mornings',
  'back',
  'barbell',
  'lower back',
  ARRAY['glutes']::text[],
  ARRAY['Set up a box in a power rack. The pins should be set at an appropriate height. Begin by stepping under the bar and placing it across the back of the shoulders, not on top of your traps. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders.', 'Remove the bar from the rack, creating a tight arch in your lower back. Keep your head facing forward. With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. This will be your starting position.', 'Keeping the bar tight, bend forward at the hips as much as possible. If you set the pins to what would be parallel, you not only have a safety if you fail, but know when to stop.', 'Pause just above the pins and reverse the motion until your torso it upright.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Good_Mornings/0.jpg',
  'image',
