(
  '196e3d19-8ea9-5d61-89db-8df07d918b75',
  'calf hamstring seated stretch',
  'Seated Hamstring and Calf Stretch',
  'legs',
  'other',
  'hamstrings',
  ARRAY['calves']::text[],
  ARRAY['Loop a belt, rope, or band around one foot. Sit down with both legs extended . This will be your starting position.', 'Leaning forward slightly, pull on the belt to draw the toes of your foot back. Hold this position for 10-20 seconds and then repeat with the other leg.']::text[],
