(
  '739178f4-e45a-5bb0-a834-037270d68cc8',
  'harness head neck resistance seated',
  'Seated Head Harness Neck Resistance',
  'neck',
  'other',
  'neck',
  '{}'::text[],
  ARRAY['Place a neck strap on the floor at the end of a flat bench. Once you have selected the weights, sit at the end of the flat bench with your feet wider than shoulder width apart from each other. Your toes should be pointed out.', 'Slowly move your torso forward until it is almost parallel with the floor. Using both hands, securely position the neck strap around your head. Tip: Make sure the weights are still lying on the floor to prevent any strain on the neck. Now grab the weight with both hands while elevating your torso back until it is almost perpendicular to the floor. Note: Your head and torso needs to be slightly tilted forward to perform this exercise.', 'Now place both hands on top of your knees. This is the starting position.', 'Slowly lower your neck down until your chin touches the upper part of your chest while breathing in.', 'While exhaling, bring your neck back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Head_Harness_Neck_Resistance/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '53897f52-2a69-5b08-8c62-72fe7d2165b8',
  'abduction hip seated',
  'Seated Hip Abduction',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Starting Position:', '* Adjust the seat height so that your knees are aligned with the pivot point of the machine.', '* Sit with your back flat against the backrest, maintaining good posture.', '* Place the outside of your thighs against the machine''s padded levers.', '* Position your feet flat on the footrests or platform of the machine.', '* Grasp the handles or sides of the seat for stability.', '* Ensure your spine is neutral and your core is slightly engaged.', 'Movement:', '* Exhale as you slowly push your legs outward against the resistance pads.', '* Focus on initiating the movement from your hips, not your knees.', '* Continue opening your legs until you feel a strong contraction in your outer hips and thighs.', '* Hold the fully abducted position briefly (1-2 seconds) to maximize muscle engagement.', '* Inhale as you slowly control the return of your legs to the starting position, resisting the weight throughout the movement.', '* Avoid allowing the weight stack to touch down between repetitions to maintain constant tension on the muscles.', '* Repeat for the desired number of repetitions, maintaining control throughout the set.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'Iko'
),
