(
  '7aec7eb7-32b2-5f72-869e-595133479454',
  'extension knee overpressure seated',
  'Seated Knee Extension with Overpressure',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['A gentle stretch to restore full knee extension. Sit with one leg stretched out in front of you and the heel propped on the floor or a low surface, so the knee is unsupported. Place both hands on the thigh just above the kneecap. Keeping the leg relaxed, gently press down through the hands toward the floor until you feel a stretch behind the knee, and hold for about three seconds before releasing. The pressure should produce a stretch, never sharp pain. Repeat for the prescribed number of repetitions, then switch legs.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'trs1800'
),
