),
(
  '39d2aebf-33af-5986-acfa-3219d6187168',
  'leg raise seated',
  'seated leg raise',
  'core',
  'bodyweight',
  'abdominals',
  ARRAY['hip flexors']::text[],
  ARRAY['Step:1 Take a seat on a flat bench with your back straight and your feet planted.', 'Step:2 Set your hands on the sides of the bench for support.', 'Step:3 Brace the abdomen and keep the shoulders anchored to the support.', 'Step:4 Lift your legs by bracing your trunk and moving at the hips rather than swinging.', 'Step:5 Slow the legs before they pull the lower back out of position.', 'Step:6 Lower the legs slowly without swinging or losing your trunk position.']::text[],
  'https://static.exercisedb.dev/media/Hgs6Nl1.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
