(
  'd5e6b034-b126-5ca9-aa2f-9a10c5fb75bf',
  'back lower seated stretch',
  'seated lower back stretch',
  'back',
  'bodyweight',
  'latissimus dorsi',
  ARRAY['glutes', 'hamstrings']::text[],
  ARRAY['Step:1 Take a seat on the edge of a chair with your feet planted.', 'Step:2 Set your hands on your thighs or on the sides of the chair for support.', 'Step:3 Settle into the starting position and take an easy breath before moving deeper.', 'Step:4 Ease toward the stretch until you feel mild tension, keep breathing and avoid bouncing.', 'Step:5 Stay in a mild stretch rather than pulling farther with momentum.', 'Step:6 Hold the position with steady breathing, then release gently, repeat on the other side if needed.']::text[],
  'https://static.exercisedb.dev/media/QFmz6ch.gif',
