(
  'fd6f0189-919b-5eef-a3e5-0b3384e4f1dd',
  'cable pulley row seated singlearm',
  'Seated One-arm Cable Pulley Rows',
  'back',
  'cable',
  'middle back',
  ARRAY['biceps', 'lats', 'traps']::text[],
  ARRAY['To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.', 'Lean over as you keep the natural alignment of your back and grab the single handle attachment with your left arm using a palms-down grip.', 'With your arm extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lat as you hold the bar in front of you. The right arm can be kept by the waist. This is the starting position of the exercise.', 'Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it as you rotate the wrist, so that by the time your hand is by your abdominals it is in a neutral position (palms facing the torso). Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard.', 'Hold that contraction for a second and slowly go back to the original position while breathing in. Tip: Remember to rotate the wrist as you go back to the starting position so that the palms are facing down again.', 'Repeat for the recommended amount of repetitions and then perform the same movement with the right hand.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_One-arm_Cable_Pulley_Rows/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '32874e45-12d7-5338-b454-783359f0ec0a',
  'curl down dumbbell palms seated singlearm wrist',
  'Seated One-Arm Dumbbell Palms-Down Wrist Curl',
  'forearms',
  'dumbbell',
  'forearms',
  '{}'::text[],
  ARRAY['Sit on a flat bench with a dumbbell in your right hand.', 'Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart.', 'Lean forward and place your right forearm on top of your upper right thigh with your palm down. Tip: Make sure that the back of the wrist lies on top of your knees. This will be your starting position.', 'Lower the dumbbell as far as possible as you keep a tight grip on the dumbbell. Inhale as you perform this movement.', 'Now curl the dumbbell as high as possible as you contract the forearms and as you exhale. Keep the contraction for a second before you lower again. Tip: The only movement should happen at the wrist.', 'Perform for the recommended amount of repetitions, switch arms and repeat the movement.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_One-Arm_Dumbbell_Palms-Down_Wrist_Curl/0.jpg',
  'image',
