  'Seated Roller Shoulder Flexion And Retraction',
  'chest',
  'roller',
  'pectorals',
  ARRAY['deltoids', 'triceps']::text[],
  ARRAY['Step:1 Take a seat on a flat surface with your legs extended in front of you.', 'Step:2 Take hold of the roller with both hands, palms facing down, and place it on your thighs.', 'Step:3 Tighten the abdomen and keep the pelvis tucked before the arms reach away.', 'Step:4 Roll the roller away along your legs as the arms reach forward, then draw it back toward your thighs.', 'Step:5 Stop reaching when the lower back starts to sag.', 'Step:6 Pull back to the start through your shoulders and abdominals, keeping the same body line.']::text[],
