  'crunch seated side wall',
  'seated side crunch (wall)',
  'core',
  'bodyweight',
  'abdominals',
  ARRAY['obliques']::text[],
  ARRAY['Step:1 Take a seat on the floor with your back against a wall and your legs extended in front of you.', 'Step:2 Bend your knees and place your feet planted, about hip width.', 'Step:3 Set the pelvis and keep the neck relaxed before curling upward.', 'Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.', 'Step:5 Leave a little space between the chin and chest, keep the movement in the torso.', 'Step:6 Lower the shoulders or torso with control before the next curl.']::text[],
