(
  'bf9ef722-c10b-5eb1-82e7-5368eae6228c',
  'lateral raise seated side',
  'Seated Side Lateral Raise',
  'shoulders',
  'dumbbell',
  'shoulders',
  '{}'::text[],
  ARRAY['Pick a couple of dumbbells and sit at the end of a flat bench with your feet firmly on the floor. Hold the dumbbells with your palms facing in and your arms straight down at your sides at arms'' length. This will be your starting position.', 'While maintaining the torso stationary (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as you execute this movement and pause for a second at the top.', 'Lower the dumbbells back down slowly to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Side_Lateral_Raise/0.jpg',
  'image',
