  'Unlicense',
  null
),
(
  '853c2cac-df34-5bdd-b9e3-d7cb5cbdb3ca',
  'press seated triceps',
  'Seated Triceps Press',
  'triceps',
  'dumbbell',
  'triceps',
  '{}'::text[],
  ARRAY['Sit down on a bench with back support and grasp a dumbbell with both hands and hold it overhead at arm''s length. Tip: a better way is to have somebody hand it to you especially if it is very heavy. The resistance should be resting in the palms of your hands with your thumbs around it. The palm of the hand should be facing inward. This will be your starting position.', 'Keeping your upper arms close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semi-circular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.', 'Go back to the starting position by using the triceps to raise the dumbbell. Breathe out as you perform this step.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Triceps_Press/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'e8db1b2a-0fde-52c0-b749-51cc35c82820',
  'arm curl low palms pulley seated up wrist',
  'Seated Two-Arm Palms-Up Low-Pulley Wrist Curl',
  'forearms',
  'cable',
  'forearms',
  '{}'::text[],
  ARRAY['Put a bench in front of a low pulley machine that has a barbell or EZ Curl attachment on it.', 'Move the bench far enough away so that when you bring the handle to the top of your thighs tension is created on the cable due to the weight stack being moved up.', 'Now hold the handle with both hands, palms up, using a shoulder-width grip.', 'Step back and sit on the bench with your feet about shoulder width apart, firmly on the floor.', 'Lean forward and place the forearms on your thighs with the back of your wrists over your knees. This will be your starting position.', 'Lower the bar as far as possible, while inhaling and keeping a tight grip.', 'Now curl the bar up as high as possible while contracting the forearms. Tip: Only the wrist should move, not the forearms.', 'After a second contraction at the top go back to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Two-Arm_Palms-Up_Low-Pulley_Wrist_Curl/0.jpg',
  'image',
  'public_domain',
