(
  'acab7189-2eb4-5102-9d9d-ca8e0bb2ad08',
  'alternate press saw see side',
  'See-Saw Press (Alternating Side Press)',
  'shoulders',
  'dumbbell',
  'shoulders',
  ARRAY['abdominals', 'triceps']::text[],
  ARRAY['Grab a dumbbell with each hand and stand up erect.', 'Clean (lift) the dumbbells to the chest/shoulder level and then rotate your wrists so that your palms are facing towards you as if you were getting ready to perform an Arnold Press. This will be your starting position.', 'Now start extending your left arm overhead as you rotate the wrist so that the palm of your hand faces forward as you go up. Your elbows should come out also as you lift the weight. Simultaneously, you will also be bending from your hip to your opposite side. Tip: If you perform the exercise correctly, is should look as if you are trying to reach for something overhead on the right hand side of your body, but with your left arm. Breathe out as you perform this movement.', 'Once you reach the top position breathe in. Then, with the weight fully extended overhead and you bent over to your right hand side, begin the movement to the left side.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/See-Saw_Press_Alternating_Side_Press/0.jpg',
