  ARRAY['Step:1 Position yourself face down on a leg curl machine with your legs extended and your ankles hooked under the padded lever.', 'Step:2 Set your hands on the side handles of the machine for support.', 'Step:3 Line the knees up with the machine or bench edge before starting the curl.', 'Step:4 Bend your knees to draw the pad toward you without lifting your hips from the support.', 'Step:5 Keep the hips still while the knees bend.', 'Step:6 Ease back to the start before repeating.']::text[],
