  ARRAY['Step:1 Stand and set your feet about shoulder width.', 'Step:2 Before moving, bend your knees and lower your body into a squat position.', 'Step:3 Brace the abdomen and spread pressure across the whole foot.', 'Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Step:5 Drive upward with the chest and hips rising together, keep the knees from collapsing inward.', 'Step:6 Stand fully, reset your footing and breathing, then begin the next descent.']::text[],
