  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['1. Stand facing a wall. Place your forearms vertically against the wall so your elbows and wrists are both touching it.', '2. Point your arms slightly outwards from "straight up".', '3. Protract your shoulders had, then slide your forearms up the wall until your elbows are about level with your chin.', '4. Slide your forearms back down the wall. Repeat as necessary.']::text[],
