(
  'bdc763e9-5d0b-57c6-9238-f0b87b7bbf3a',
  'ir shinbox stretch',
  'Shinbox IR Stretch',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['* **Starting Position:** Sit on the floor with both hips and knees bent at 90-degree angles.', '* **Leg Placement:**', 'Place one leg in front of you (external rotation) and the other leg out', 'to the side/behind you (internal rotation). The shins and knees should', 'remain flat on the ground.', '* **The Movement:**', 'Keeping your hips square, hinge your torso forward or tilt it laterally', '(side-to-side) toward the front leg to deepen the stretch.', '* **Target Areas:**', 'Stretches the glutes and piriformis (front leg) and the hip flexors and', 'quads (back leg). Engages the core and obliques during lateral flexion.', '* **Goal:** Improves hip mobility, specifically internal and external rotation, and relieves lower back tension.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'teus_ergaster'
),
