  ARRAY['Step:1 Begin by lying on your side with your legs extended and stacked on top of each other.', 'Step:2 Set your bottom hand on the ground directly under your shoulder, fingers pointing forward.', 'Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Step:4 Bend your elbows to lower your chest while keeping your body in one line.', 'Step:5 Keep the head in line with the spine as the elbows bend.', 'Step:6 Press back to straight arms, keeping the body line intact.']::text[],
