  ARRAY['Begin standing with your feet hip width apart in an athletic stance. Your head and chest should be up, knees and hips slightly bent. This will be your starting position.', 'Leaning to your right, extend through your hips, knees, and ankles to jump into the air. Block with the arms to lead the movement, jumping as far to your right as you can.', 'Land facing the same direction with your feet hip width apart, absorbing the impact through your lower body.']::text[],
