  ARRAY['Stand to one side of the box with your left foot resting on the middle of it.', 'To begin, jump up and over to the other side of the box, landing with your right foot on top of the box and your left foot on the floor. Swing your arms to aid your movement.', 'Continue shuffling back and forth across the box.']::text[],
