(
  '32f63940-126d-51dc-95e4-38e408337a84',
  'chins side',
  'Side To Side Chins',
  'back',
  'other',
  'lats',
  ARRAY['biceps', 'forearms', 'middle back', 'shoulders']::text[],
  ARRAY['Grab the pull-up bar with the palms facing forward using a wide grip.', 'As you have both arms extended in front of you holding the bar at a wide grip, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.', 'Pull your torso up while leaning to the left hand side until the bar almost touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space (no swinging) and only the arms should move. The forearms should do no other work other than hold the bar.', 'After a second of contraction, inhale as you go back to the starting position.', 'Now, pull your torso up while leaning to the right hand side until the bar almost touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.', 'After a second of contraction, inhale as you go back to the starting position.', 'Repeat steps 3-6 until you have performed the prescribed amount of repetitions for each side.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_To_Side_Chins/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'b6a88a8d-d3d2-5d63-b790-52b5a285b4ac',
