  '61b19a7c-879d-5039-ad01-f29497eb5558',
  'breathing kick kickboard side',
  'Side-Kick Breathing (Kickboard)',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Push off the wall on your side (not flat on your stomach), one arm extended forward holding the board or just extended, kicking continuously. Keep your head in a neutral position looking at the bottom of the pool, and when you need air, rotate your head sideways (one ear stays in the water, other faces up) to breathe, then rotate back to neutral. Swim a length like this, then repeat on the other side. This teaches the exact head position and rotation you''ll use once full stroke breathing comes in.']::text[],
