  ARRAY['Step:1 Begin by standing with one foot on a platform or slide board.', 'Step:2 Before moving, bend your knee slightly and slide the foot on the platform backward, extending your leg.', 'Step:3 Set your stance wide enough to balance before bending either knee.', 'Step:4 Step into the movement and bend both knees, keeping your front foot planted.', 'Step:5 Keep the front foot planted and avoid collapsing inward at the knee.', 'Step:6 Push through the lead foot to return to the start, then change legs as planned.']::text[],
