  'bodyweight',
  'glutes',
  ARRAY['quadriceps', 'hamstrings', 'calves']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width and arms extended in front of you.', 'Step:2 Before moving, lift your right foot off the ground and extend it forward.', 'Step:3 Brace the abdomen and spread pressure across the whole foot.', 'Step:4 Extend the free leg ahead of you as you squat on the standing leg, keeping its heel grounded.', 'Step:5 Drive upward with the chest and hips rising together, keep the knees from collapsing inward.', 'Step:6 Stand fully, reset your footing and breathing, then begin the next descent.']::text[],
