  'against singlearm wall',
  'Single-Arm Against Wall',
  'back',
  'bodyweight',
  'latissimus dorsi',
  ARRAY['deltoids', 'triceps']::text[],
  ARRAY['Step:1 Face the wall from a stable stance with feet about shoulder width.', 'Step:2 Reach one arm straight out in front of you and place your palm against the wall.', 'Step:3 Brace the abdomen and find a position you can maintain without holding your breath.', 'Step:4 Brace your midsection and hold the position while breathing normally.', 'Step:5 Keep both shoulders level and resist turning toward the working arm.', 'Step:6 Keep the shape for the planned time, then come out of it with control, switch sides when the set calls for it.']::text[],
