  'cable',
  'pectorals',
  ARRAY['deltoids', 'trapezius']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width, facing a cable machine.', 'Step:2 Hold the handle with one hand and step back to create tension on the cable.', 'Step:3 Start with a manageable load and a small bend in the elbows.', 'Step:4 Raise the arms out to the sides to about shoulder height without leaning or shrugging.', 'Step:5 Keep both shoulders level and resist turning toward the working arm.', 'Step:6 Lower the arms slowly to your sides without swinging the weight, switch sides when the set calls for it.']::text[],
