(
  '1397d839-7f07-594f-93e0-7aeb572cc715',
  'cable crossover singlearm',
  'Single-Arm Cable Crossover',
  'chest',
  'cable',
  'chest',
  '{}'::text[],
  ARRAY['Begin by moving the pulleys to the high position, select the resistance to be used, and take a handle in each hand.', 'Step forward in front of both pulleys with your arms extended in front of you, bringing your hands together. Your head and chest should be up as you lean forward, while your feet should be staggered. This will be your starting position.', 'Keeping your left arm in place, allow your right arm to extend out to the side, maintaining a slight bend at the elbow. The right arm should be perpendicular to the body at approximately shoulder level.', 'Return your arm back to the starting position by pulling your hand back to the midline of the body.', 'Hold for a second at the starting position and repeat the movement on the opposite side. Continue alternating back and forth for the prescribed number of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single-Arm_Cable_Crossover/0.jpg',
