(
  '6195fd4e-8a6d-5111-908c-1acb7ae99f3b',
  'cable pushdown singlearm',
  'Single-arm cable pushdown',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Single-arm cable pushdown is a unilateral isolation exercise that targets the triceps brachii. By working one arm at a time, it helps correct strength imbalances between sides while also engaging the core for stability.', 'Starting position:', 'Stand facing the cable machine with your feet shoulder-width apart. Attach a single handle to the high pulley. Grab the handle with one hand using an overhand grip (pronated), with your elbow bent at approximately 90° and tucked close to your body. Keep your core braced and your back straight.', 'Execution:', 'Push the handle downward in a controlled motion by extending your elbow until your arm is fully extended. Hold the contraction for 1 second at the bottom, then slowly return to the starting position.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'evtimovgeorg'
),
