  ARRAY['Step:1 Connect a rope handle to a low pulley cable machine.', 'Step:2 Face the machine from a stable stance with feet about shoulder width.', 'Step:3 Set the working upper arm against the preacher pad and leave the elbow free to bend.', 'Step:4 Curl the weight while your upper arms stay in contact with the pad.', 'Step:5 Keep both shoulders level and resist turning toward the working arm.', 'Step:6 Lower until the elbows are nearly straight, keeping the upper arms still, switch sides when the set calls for it.']::text[],
