  ARRAY['Step:1 Face the pull-up bar from a stable stance with feet about shoulder width.', 'Step:2 Reach up to hold the bar with palms facing up, with one hand gripping the bar and the other hand holding your wrist for support.', 'Step:3 Begin from a controlled hang with the shoulders active rather than slack.', 'Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.', 'Step:5 Keep both shoulders level and resist turning toward the working arm.', 'Step:6 Lower to long arms without dropping suddenly from the top, switch sides when the set calls for it.']::text[],
