  ARRAY['pectorals', 'deltoids']::text[],
  ARRAY['Step:1 Face the away from a bench or chair, from a stable stance with feet about shoulder width.', 'Step:2 Set one hand on the bench or chair behind you, fingers pointing toward your body.', 'Step:3 Set the shoulders down and keep the elbows pointed mostly behind you.', 'Step:4 Bend the elbows to lower between the supports, stop at a comfortable shoulder depth.', 'Step:5 Keep both shoulders level and resist turning toward the working arm.', 'Step:6 Press through the hands to rise, then reset the shoulders before another rep, switch sides when the set calls for it.']::text[],
