  ARRAY['triceps', 'forearms']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width, holding a kettlebell in one hand.', 'Step:2 Bend your knees slightly and hinge forward at the hips, with your spine steady.', 'Step:3 Brace the torso and align the wrists with the forearms.', 'Step:4 Bring the kettlebell to the rack position, then press it overhead with the wrist stacked above the shoulder.', 'Step:5 Keep both shoulders level and resist turning toward the working arm.', 'Step:6 Lower the weight to its starting height under control before pressing again, switch sides when the set calls for it.']::text[],
