  'core',
  'medicine ball',
  'abdominals',
  ARRAY['deltoids', 'back']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width, holding the medicine ball with one hand ahead of your waist.', 'Step:2 Bend your knees slightly and Brace your trunk.', 'Step:3 Set a firm stance and leave enough clear space for the ball to travel.', 'Step:4 Drive the ball away forcefully, using the arms and trunk together, catch or retrieve it before resetting.', 'Step:5 Keep both shoulders level and resist turning toward the working arm.', 'Step:6 Return along the same path at a controlled pace, switch sides when the set calls for it.']::text[],
