  ARRAY['biceps', 'forearms']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width, knees soft, and hold a towel with one hand.', 'Step:2 Bend forward at the waist, with your spine steady and your core engaged.', 'Step:3 Set the torso and allow the arms to reach forward without rounding excessively.', 'Step:4 Draw your elbows back and bring the handle or weight toward your torso.', 'Step:5 Keep both shoulders level and resist turning toward the working arm.', 'Step:6 Reach the arms forward again without letting the torso lurch, switch sides when the set calls for it.']::text[],
