(
  'ec129057-8d21-56aa-8860-7240e11e9fdf',
  'balance closed eyes singleleg',
  'Single-Leg Balance with Eyes Closed',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['A balance and proprioception drill. Stand on one leg with the knee slightly bent and the other foot lifted clear of the floor, then close your eyes and hold the position. Without visual feedback the ankle and hip stabilisers have to do the work, so expect noticeable wobble. Stand within reach of a wall, counter or chair so you can steady yourself if needed. Hold for the prescribed time, then switch legs. Commonly prescribed in rehabilitation after ankle or knee injury.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'trs1800'
),
(
  '7e2f02f7-78b9-58ac-981f-4cdbccc87665',
  'balance circles kettlebell singleleg',
  'Single-Leg Balance with Kettlebell Circles',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['A balance drill that adds a moving load. Stand on one leg with the knee slightly bent, holding a kettlebell in one hand. Pass the kettlebell around your body in a circle, handing it from one hand to the other in front and behind you, while keeping your balance on the standing leg. Keep the hips level and the torso upright, the shifting weight of the bell constantly changes your centre of mass, which is what trains the hip and ankle stabilisers. Complete the prescribed number of circles, reverse direction, then switch legs. Use a light bell to start.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'trs1800'
),
(
  '6e18ccda-ce78-5c8d-a534-f6608f5db9b4',
  'balance bosu singleleg',
  'Single-leg BOSU balance',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['# Single-Leg BOSU Balance Exercise', 'The exercise for balancing on a BOSU ball while standing on one leg is known as the single-leg BOSU balance exercise. This exercise is effective for enhancing balance, coordination, and core stability.', '## Benefits of the Single-Leg BOSU Balance Exercise', '* **Improves Balance:** Standing on one leg challenges your stability.', '* **Enhances Coordination:** Engaging different muscle groups helps improve overall coordination.', '* **Strengthens Core:** The exercise activates core muscles, promoting better posture and stability.', '## How to Perform the Single-Leg BOSU Balance Exercise', '1. **Positioning:** Stand on the dome side of the BOSU ball with one leg.', '2. **Balance:** Keep your opposite leg lifted and your core engaged.', '3. **Duration:** Aim to hold the position for 10-20 seconds, gradually increasing the time as you improve.', '## Progression Tips', '* **Add Movement:** Try reaching for objects around you while maintaining balance.', '* **Close Your Eyes:** This increases the challenge by removing visual stability cues.', '* **Use a Ball:** Catch or toss a ball while balancing to further engage your core and coordination.', 'This exercise is a great way to build foundational balance skills before progressing to more complex movements.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'aboksz'
),
(
  'b4fd3b8d-c001-506c-a54b-25d096b39607',
