  'Single-Leg Donkey Calf Raise',
  'legs',
  'bodyweight',
  'calves',
  ARRAY['hamstrings', 'glutes']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width, toes pointing forward.', 'Step:2 Set your hands on a stable surface for support, such as a wall or a bar.', 'Step:3 Let the ankles move freely while the rest of the body stays quiet.', 'Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Step:5 Keep the pelvis level as the supporting leg does the work.', 'Step:6 Lower the heels at a measured pace before rising again, switch sides when the set calls for it.']::text[],
  'https://static.exercisedb.dev/media/A2upspL.gif',
