(
  '845e09c7-b90f-50f9-80b4-6cc79e36fb7f',
  'kettlebell lunge singleleg',
  'Single-Leg Lunge with Kettlebell:',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['How to do a single-leg kettlebell lunge', 'Preparation: Stand with your feet together. Hold the kettlebell with both hands by the handle, keeping it close to your chest, or hold it with one hand (on the same side as the working leg).', 'Step and Lower: Take a large step forward (or backward, which is safer for your knees) with one leg, lowering your hips until both knees form a 90-degree angle.', 'Focus: Shift your weight onto your front (or bent) leg, keeping your back straight and your torso upright.', 'Return: Push off with your front leg to return to the starting position.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'Tierrasverdes'
),
(
  '23949fad-1fcd-56ea-a7ce-2335b1b24245',
  'glute press side singleleg',
  'Single-leg side glute press',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['The Single-Leg Side Glute Press is a leg press machine variation where you angle your body sideways on the pad, placing one foot high and slightly angled to press the weight, powerfully targeting the outer glute (gluteus medius/minimus) and hamstrings for balanced leg development and stability, requiring focus on pushing through the heel and maintaining control without locking out.', 'How to Perform:', 'Setup: Sit in the leg press machine, rotate your body to one hip, placing one foot high on the platform at about a 45-degree angle with toes pointed slightly out/forward.', 'Positioning: Keep your hip, knee, and ankle aligned, and ensure your lower back stays on the pad.', 'Descent: Slowly lower the weight, allowing your knee to bend deeply (near 90 degrees), feeling a stretch in your glute and hamstring.', 'Press: Drive through your heel (not your toes) to press the weight back up, squeezing your glutes and hamstrings, stopping just before your leg fully extends.', 'Control: Avoid bouncing and don''t let your lower back lift off the pad, maintain tension throughout the movement.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'Tierrasverdes'
),
(
  '7aaa7536-f050-5ca2-ab2c-0855727cd97d',
  'holds landing singleleg soft',
  'Single-Leg Soft-Landing Holds',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['# Single-Leg Soft-Landing Holds', 'Single-leg soft-landing holds are exercises that focus on balance and stability by landing softly on one leg and holding the position. This exercise helps improve proprioception and can be beneficial for rehabilitation and athletic training.', '## Overview', 'Single-leg soft-landing holds are exercises designed to enhance balance, stability, and proprioception. They involve landing softly on one leg and maintaining that position for a brief period. This exercise is particularly useful in rehabilitation settings and for athletes looking to improve their performance.', '## Benefits', '- **Improves balance:** Enhances stability by training the body to control weight distribution on one leg.', '- **Enhances proprioception:** Increases awareness of body position, which is crucial for injury prevention.', '- **Supports rehabilitation:** Helps individuals recover from lower-limb injuries by strengthening muscles and improving joint stability.', '## How to Perform Single-Leg Soft-Landing Holds', '### Steps', '1. **Preparation:** Stand on a stable surface or a box.', '2. **Takeoff:** Step off the box or surface with one leg, ensuring that you do not jump.', '3. **Landing:** Land softly on the target leg, allowing the knee and hip to bend slightly.', '4. **Hold position:** Maintain balance in the landed position for up to 2 seconds.', '5. **Reset:** Return to the starting position and repeat.', '### Key Points to Remember', '- Keep your chest up and engage your core for better stability.', '- Ensure your knee aligns with the midline of your foot during landing.', '- Focus on a controlled descent to minimize impact.', '## Conclusion', 'Incorporating single-leg soft-landing holds into your training routine can significantly enhance your balance and stability, making it a valuable exercise for both rehabilitation and athletic performance.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'aboksz'
),
(
  'd3d4d9f6-7e15-5163-8742-965a33a6ccc0',
