  'glutes',
  ARRAY['quadriceps', 'hamstrings', 'calves']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width.', 'Step:2 Reach one leg forward, keeping it off the ground.', 'Step:3 Brace the abdomen and spread pressure across the whole foot.', 'Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Step:5 Keep the pelvis level as the supporting leg does the work.', 'Step:6 Stand fully, reset your footing and breathing, then begin the next descent, switch sides when the set calls for it.']::text[],
