  ARRAY['1. Start standing on the platform with your feet hip-width apart.', '2. Reach overhead to grip the handles with your palms facing in.', '3. Soften your knees, then simultaneously drive your butt back as if you''re closing a door behind you while pulling your arms straight down past your hips until your hands pass by the side of your knees.', '4. Next, bring your arms back overhead while thrusting your hips forward until you''re standing with your arms fully extended.', '5. Repeat for reps, time or distance.']::text[],
