  'abdominals',
  ARRAY['forearms', 'deltoids']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width and hold the sledge hammer with both hands.', 'Step:2 Brace your trunk and Keep your spine in a comfortable neutral position.', 'Step:3 Start at a pace that lets the feet and arms move in sync.', 'Step:4 Swing the hammer down with a coordinated hip turn, then reset your grip and stance.', 'Step:5 Keep the palms facing each other and the wrists straight.', 'Step:6 Keep the rhythm for the planned interval, slowing if your form starts to slip.']::text[],
