  'sledgehammer swings',
  'Sledgehammer Swings',
  'core',
  'other',
  'abdominals',
  ARRAY['calves', 'forearms', 'lats', 'middle back', 'shoulders']::text[],
  ARRAY['You will need a tire and a sledgehammer for this exercise. Stand in front of the tire about two feet away from it with a staggered stance. Grip the sledgehammer.', 'If you are right handed, your left hand should be at the bottom of the handle, and your right hand should be choking up closer to the head.', 'As you bring the sledge up, your right hand slides toward the head, as you swing down, your right hand will slide down to join your left hand. Slam it down as hard as you can against the tire. Control the bounce of the hammer off of the tire.', 'Repeat on the other side.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Sledgehammer_Swings/0.jpg',
  'image',
