  ARRAY['Step:1 Set yourself on the smith machine with your back against the pad and your feet about shoulder width.', 'Step:2 Set your hands on the barbell, just beyond shoulder width.', 'Step:3 Plant the feet and keep the ribs from flaring as the hips prepare to rise.', 'Step:4 Press through the feet and lift your hips until your torso and thighs line up.', 'Step:5 Stop when the hips line up with the torso, do not arch higher through the lower back.', 'Step:6 Lower the hips steadily and keep the feet planted for the next lift.']::text[],
