  '7cfc9dfe-3d51-57b8-8fb8-b2e43b94ecdf',
  'back behind shrug smith',
  'Smith Machine Behind the Back Shrug',
  'back',
  'machine',
  'traps',
  ARRAY['shoulders']::text[],
  ARRAY['With the bar at thigh level, load an appropriate weight.', 'Stand with the bar behind you, taking a shoulder-width, pronated grip on the bar and unhook the weight. You should be standing up straight with your head and chest up and your arms extended. This will be your starting position.', 'Initiate the movement by shrugging your shoulders straight up. Do not flex the arms or wrist during the movement.', 'After a brief pause return the weight to the starting position.', 'Repeat for the desired number of repetitions before engaging the hooks to rack the weight.']::text[],
