  ARRAY['Step:1 Set the height of the smith machine bar to be at waist level.', 'Step:2 Face the smith machine from a stable stance with feet about shoulder width.', 'Step:3 Set the shoulders and upper arms before bending the elbows.', 'Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Step:5 Keep the torso quiet and let the elbow bend lift the weight.', 'Step:6 Lower until the elbows are nearly straight, keeping the upper arms still.']::text[],
