(
  'faf22a10-509b-5d65-9afb-30a83ba92477',
  'clean hang power smith',
  'Smith Machine Hang Power Clean',
  'legs',
  'machine',
  'hamstrings',
  ARRAY['glutes', 'lower back', 'quadriceps', 'shoulders', 'traps']::text[],
  ARRAY['Position the bar at knee height and load it to an appropriate weight.', 'Take a pronated grip on the bar outside of shoulder width and unhook the bar from the machine. Your arms should be fully extended with your head and chest up. Your elbows should be pointed out with your shoulders back and down. Your hips should be back, loading the tension into the hamstrings. This will be your starting position.', 'Initate the movement by forcefully extending the hips and knees, accelerating into the bar. Ensure that you keep your arms straight during this part of the motion.', 'Upon full extension, rebend the hips and knees to lower your receiving position.', 'Allow the arms to flex at this point, rotating the elbows around the bar to receive it on your shoulders.', 'Extend through the hips and knees to come to a standing position with the bar racked on your shoulders to complete the movement.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Hang_Power_Clean/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
