  '01e8a58d-9914-5931-a8f8-0dc86da6a848',
  'row singlearm smith upright',
  'Smith Machine One-Arm Upright Row',
  'shoulders',
  'machine',
  'shoulders',
  ARRAY['biceps', 'traps']::text[],
  ARRAY['With the bar at thigh level, load an appropriate weight.', 'Take a wide grip on the bar and unhook the weight, removing your off hand from the bar. Your arm should be extended as you stand up straight with your head and chest up. This will be your starting position.', 'Begin the movement by flexing the elbow, raising the upper arm with the elbow pointed out. Continue until your upper arm is parallel to the floor.', 'After a brief pause, return the weight to the starting position.', 'Repeat for the desired number of repetitions before engaging the hooks to rack the weight.']::text[],
