(
  'cd2473be-46e5-5c5d-9ea8-f709d0bb8d22',
  'overhead press shoulder smith',
  'Smith Machine Overhead Shoulder Press',
  'shoulders',
  'machine',
  'shoulders',
  ARRAY['triceps']::text[],
  ARRAY['To begin, place a flat bench (or preferably one with back support) underneath a smith machine. Position the barbell at a height so that when seated on the flat bench, the arms must be almost fully extended to reach the barbell.', 'Once you have the correct height, sit slightly in behind the barbell so that there is an imaginary straight line from the tip of your nose to the barbell. Your feet should be stationary. Grab the barbell with the palms facing forward, unlock it and lift it up so that your arms are fully extended. This is the starting position.', 'Slowly begin to lower the barbell until it is level with your chin while inhaling.', 'Then lift the barbell back to the starting position using your shoulders while exhaling.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Overhead_Shoulder_Press/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'fe9b4571-acf2-5abc-a443-326473c57c86',
  'pistol smith squat',
  'Smith Machine Pistol Squat',
  'legs',
  'machine',
  'quadriceps',
  ARRAY['calves', 'glutes', 'hamstrings']::text[],
  ARRAY['To begin, first set the bar to a position that best matches your height. Step under it and position the bar across the back of your shoulders.', 'Take the bar with your hands facing forward, unlock it and lift it off the rack by extending your legs. 3', 'Move one foot forward about 12 inches in front of the bar. Extend the other leg out in front of you, holding it off the ground. Look forward at all times and maintain a neutral or slightly arched spine. This will be your starting position.', 'Maintaining good posture, lower yourself by flexing the knee and hip, going down as far as flexibility allows.', 'Pause briefly at the bottom and then return to the starting position by driving through the heel of your foot, extending the knee and hip.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Pistol_Squat/0.jpg',
  'image',
  'public_domain',
