  '8ddd3627-8b3c-5177-88a9-dca4e2c0365f',
  'incline press slight smith',
  'Smith Machine Slight Incline Press',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['**Execution**', '**Start position:**', '- Unrack the bar and hold it above your upper chest with arms fully extended.', '- Keep your shoulder blades **retracted and pressed into the bench**.', '**Lowering phase (eccentric):**', '- Slowly bring the bar down to just below your collarbone or upper chest.', '- Maintain control — don’t bounce the bar.', '**Pressing phase (concentric):**', '- Push the bar upward in a straight line until your arms are fully extended.', '- Focus on **squeezing your upper chest** at the top.', '**Lock and repeat:**', '- Complete your reps, then safely rack the bar back into the hooks.']::text[],
