(
  '3456901f-184e-5bad-a11a-f24834b81573',
  'smith split squat',
  'Smith Machine Split Squat',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['The **"Smith Machine Split Squat"** is a strength exercise', 'performed on the Smith machine, ideal for targeting the legs and glutes.', 'It involves placing one foot forward and the other back, lowering the', 'body until the front thigh is parallel to the ground while the bar', 'slides vertically along the machine. This exercise helps improve', 'stability, correct muscle imbalances, and reduces stress on the back,', 'providing a safe environment for strength training.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'workout@rooven.anonaddy.me'
),
(
  '1f3669cd-5fa8-5d1c-a63a-7d5576a98ee0',
  'deadlift legged smith stiff',
  'Smith Machine Stiff-Legged Deadlift',
  'legs',
  'machine',
  'hamstrings',
  ARRAY['glutes', 'lower back']::text[],
  ARRAY['To begin, set the bar on the smith machine to a height that is around the middle of your thighs. Once the correct height is chosen and the bar is loaded, grasp the bar using a pronated (palms forward) grip that is shoulder width apart. You may need some wrist wraps if using a significant amount of weight.', 'Lift the bar up by fully extending your arms while keeping your back straight. Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.', 'Keeping the knees stationary, lower the barbell to over the top of your feet by bending at the waist while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Exhale as you perform this movement', 'Start bringing your torso up straight again as soon as you feel the hamstrings stretch by extending your hips and waist until you are back at the starting position. Inhale as you perform this movement.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Stiff-Legged_Deadlift/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
