(
  '867c5b8c-a0a7-55f6-9667-25c78e416112',
  'down snap',
  'Snap Down',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Begin in a standing position with your', 'arms up over your head and your toes pushing into the ground raising', 'your heels up becoming as tall as you can. From this position, perform a', 'small hop with both feet slightly coming off of the ground. As you', 'land, bend your knees and begin to hinge forward at your hips absorbing', 'the landing. Return to the starting position and repeat.', 'You should feel the muscles in your lower body working.', 'Start with your arms and knees fully', 'straightened out. Keep a stable balance as you land and briefly hold', 'that end position, don’t go too fast and become off balanced. Keep your', 'chest up.', 'For a detailed video on landing mechanics, click here: https://youtu.be/RThUCYRDyZw']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'mountain.potato'
),
(
  '7f7836ce-f67a-52fa-b540-521b56e68e4b',
  'snatch',
  'Snatch',
  'legs',
  'barbell',
  'quadriceps',
  ARRAY['biceps', 'glutes', 'hamstrings', 'lower back', 'shoulders', 'traps', 'triceps']::text[],
  ARRAY['Place your feet at a shoulder width stance with the barbell resting right above the connection between the toes and the rest of the foot.', 'With a palms facing down grip, bend at the knees and keeping the back flat grab the bar using a wider than shoulder width grip. Bring the hips down and make sure that your body drops as if you were going to sit on a chair. This will be your starting position.', 'Start pushing the floor as if it were a moving platform with your feet and simultaneously start lifting the barbell keeping it close to your legs.', 'As the bar reaches the middle of your thighs, push the floor with your legs and lift your body to a complete extension in an explosive motion.', 'Lift your shoulders back in a shrugging movement as you bring the bar up while lifting your elbows out to the side and keeping them above the bar for as long as possible.', 'Now in a very quick but powerful motion, you have to get your body under the barbell when it has reached a high enough point where it can be controlled and drop while locking your arms and holding the barbell overhead as you assume a squat position.', 'Finalize the movement by rising up out of the squat position to finish the lift. At the end of the lift both feet should be on line and the arms fully extended holding the barbell overhead.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Snatch/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'dee4e783-b952-51f4-8999-3a5f434d53b8',
  'balance snatch',
  'Snatch Balance',
  'legs',
  'barbell',
  'quadriceps',
  ARRAY['calves', 'glutes', 'hamstrings', 'shoulders', 'triceps']::text[],
  ARRAY['Begin with the feet in the pulling position, the bar racked across the back of the shoulders, and the hands placed in a wide snatch grip.', 'Pop the bar with an abrupt dip and drive of the knees, and aggressively drive under the bar, transitioning the feet into the receiving position.', 'Receive the bar locked out overhead near the bottom of the squat. The torso should remain vertical, lowering the hips between the legs.', 'Continue to descend to full depth, and return to a standing position. Carefully lower the weight.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Snatch_Balance/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'def6ac4a-e93f-5712-bd98-b3a433c29470',
  'deadlift snatch',
  'Snatch Deadlift',
  'legs',
  'barbell',
  'hamstrings',
  ARRAY['forearms', 'glutes', 'hamstrings', 'lower back', 'quadriceps', 'traps']::text[],
  ARRAY['The snatch deadlift strengthens the first pull of the snatch. Begin with a wide snatch grip with the barbell placed on the platform. The feet should be directly under the hips, with the feet turned out. Squat down to the bar, keeping the back in absolute extension with the head facing forward.', 'Initiate the movement by driving through the heels, raising the hips. The back angle should remain the same until the bar passes the knees.', 'At that point, drive your hips through the bar as you lay back. Return the bar to the platform by reversing the motion.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Snatch_Deadlift/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'ea045234-617f-5289-b757-0264927c3850',
  'blocks snatch',
  'Snatch from Blocks',
  'legs',
  'barbell',
  'quadriceps',
  ARRAY['calves', 'forearms', 'glutes', 'hamstrings', 'lower back', 'shoulders', 'traps', 'triceps']::text[],
  ARRAY['Begin with a loaded barbell on boxes or stands of the desired height. A wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar, with the elbows pointed out. This will be the starting position.', 'Begin the first pull by driving through the front of the heels, raising the bar from the boxes.', 'Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side.', 'As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. The feet should move to just outside the hips, turned out as necessary. Receive the bar with your body as low as possible and the arms fully extended overhead.', 'Keeping the bar aligned over the front of the heels, your head and chest up, drive through heels of the feet to move to a standing position. Carefully return the weight to the boxes.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Snatch_from_Blocks/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
