(
  '09421361-e0f1-5137-9f57-54a9e7a6c9af',
  'pull snatch',
  'snatch pull',
  'legs',
  'barbell',
  'quadriceps',
  ARRAY['hamstrings', 'glutes', 'calves']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width and the barbell on the ground in front of you.', 'Step:2 Bend your knees and hinge at the hips to lower into a squat position, gripping the barbell with palms facing down.', 'Step:3 Brace before the pull and keep the load close to the body.', 'Step:4 Drive through the legs and hips, then guide the weight to its receiving position.', 'Step:5 Receive the load with the torso braced and feet stable.', 'Step:6 Stand tall to finish, then lower the weight under control before the next rep.']::text[],
