  ARRAY['For this exercise anchor a band to the ground. We used an incline bench and anchored the band to the base, standing over the bench. Alternatively, this could be performed standing on the band.', 'To begin, pull the band behind your head, holding it with a pronated grip and your elbows up. This will be your starting position.', 'To perform the movement, extend through the elbow to to straighten your arms, ensuring that you keep your upper arm in place.', 'Pause, and then return to the starting position.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Speed_Band_Overhead_Triceps/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '3c363710-216c-5115-b39c-d56ba627e273',
  'box speed squat',
  'Speed Box Squat',
  'legs',
  'barbell',
  'quadriceps',
  ARRAY['calves', 'glutes', 'hamstrings']::text[],
  ARRAY['Attach bands to the bar that are securely anchored near the ground. You may need to choke the bands to get adequate tension.', 'Use a box of an appropriate height for this exercise. Load the bar to a weight that still requires effort, but isn''t so heavy that speed is compromised. Typically, that will be between 50-70% of your one rep max.', 'Position the bar on your upper back, shoulder blades retracted, back arched and everything tight head to toe. This will be the starting position.', 'Unrack the bar and position yourself in front of the box. Sit back with your hips until you are seated on the box, ensuring that you descend under control and don''t crash onto the surface.', 'Pause briefly, and explode off of the box, extending through the hips and knees.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Speed_Box_Squat/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
