(
  '44ae896a-ea07-5954-9512-55f2ed77af50',
  'speed squat',
  'Speed Squats',
  'legs',
  'barbell',
  'quadriceps',
  ARRAY['calves', 'glutes', 'hamstrings', 'lower back']::text[],
  ARRAY['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance which targets overall development, however you can choose any of the three stances discussed in the foot stances section).', 'Begin to lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the bar as fast as possible without involving momentum as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position. Note: You should perform these exercises as fast as possible but without breaking perfect form and without involving momentum.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Speed_Squats/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'b33ee0d9-bab9-5fd3-8128-36f27d33be21',
  'caster spell',
  'spell caster',
  'core',
  'dumbbell',
  'abdominals',
  ARRAY['obliques', 'erector spinae']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width and hold a dumbbell in one hand.', 'Step:2 Bend your knees slightly and hinge forward at the waist, with your spine steady.', 'Step:3 Set the pelvis and make the turn through the rib cage.', 'Step:4 Turn through the torso while the hips and lower body stay as steady as the setup allows.', 'Step:5 Keep the turn smooth instead of throwing the arms across the body.', 'Step:6 Return through center before turning to the other side.']::text[],
  'https://static.exercisedb.dev/media/p9cCe2r.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  '0b837442-c0b2-555d-9e96-71a2bd855f7a',
  'sphinx',
  'sphinx',
  'back',
  'bodyweight',
  'erector spinae',
  ARRAY['glutes', 'hamstrings']::text[],
  ARRAY['Step:1 Position yourself face down on the ground with your forearms flat on the floor, elbows directly under your shoulders.', 'Step:2 Brace your trunk and lift your chest off the ground, keeping your forearms and toes on the floor.', 'Step:3 Settle into the starting position and take an easy breath before moving deeper.', 'Step:4 Ease toward the stretch until you feel mild tension, keep breathing and avoid bouncing.', 'Step:5 Stay in a mild stretch rather than pulling farther with momentum.', 'Step:6 Hold the position with steady breathing, then release gently, repeat on the other side if needed.']::text[],
  'https://static.exercisedb.dev/media/DIVyqrU.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  'e3bda88f-c4fb-5697-99b6-806cde456198',
  'crawl spider',
  'Spider Crawl',
  'core',
  'body only',
  'abdominals',
  ARRAY['chest', 'shoulders', 'triceps']::text[],
  ARRAY['Begin in a prone position on the floor. Support your weight on your hands and toes, with your feet together and your body straight. Your arms should be bent to 90 degrees. This will be your starting position.', 'Initiate the movement by raising one foot off of the ground. Externally rotate the leg and bring the knee toward your elbow, as far forward as possible.', 'Return this leg to the starting position and repeat on the opposite side.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Spider_Crawl/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '48794344-1b72-5f2e-8b50-05efc232660c',
  'crawl pushup spider',
  'spider crawl push up',
  'legs',
  'bodyweight',
  'glutes',
  ARRAY['core', 'pectorals', 'deltoids']::text[],
  ARRAY['Step:1 Begin in a push-up position with your hands just beyond shoulder width and your feet together.', 'Step:2 Bring your right knee toward your right elbow, keeping it off the ground.', 'Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Step:4 Bend your elbows to lower your chest while keeping your body in one line.', 'Step:5 Keep the head in line with the spine as the elbows bend.', 'Step:6 Press back to straight arms, keeping the body line intact.']::text[],
  'https://static.exercisedb.dev/media/P9GFBME.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  '651edd05-a449-5959-96b4-c9bc9af3f9c8',
  'curl spider',
  'Spider Curl',
  'biceps',
  'e-z curl bar',
  'biceps',
  '{}'::text[],
  ARRAY['Start out by setting the bar on the part of the preacher bench that you would normally sit on. Make sure to align the barbell properly so that it is balanced and will not fall off.', 'Move to the front side of the preacher bench (the part where the arms usually lay) and position yourself to lay at a 45 degree slant with your torso and stomach pressed against the front side of the preacher bench.', 'Make sure that your feet (especially the toes) are well positioned on the floor and place your upper arms on top of the pad located on the inside part of the preacher bench.', 'Use your arms to grab the barbell with a supinated grip (palms facing up) at about shoulder width apart or slightly closer from each other.', 'Slowly begin to lift the barbell upwards and exhale. Hold the contracted position for a second as you squeeze the biceps.', 'Slowly begin to bring the barbell back to the starting position as your breathe in. .', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Spider_Curl/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'c21d2189-7472-589c-8f9c-d67d05c91601',
  'spinal stretch',
  'Spinal Stretch',
  'back',
  '',
  'middle back',
  ARRAY['lats', 'lower back', 'neck', 'traps']::text[],
  ARRAY['Sit in a chair so your back is straight and your feet planted on the floor.', 'Interlace your fingers behind your head, elbows out and your chin down.', 'Twist your upper body to one side about 3 times as far as you can. Then lean forward and twist your torso to reach your elbow to the floor on the inside of your knee.', 'Return to upright position and then repeat for your other side.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Spinal_Stretch/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
