  'bodyweight',
  'erector spinae',
  ARRAY['hamstrings', 'glutes']::text[],
  ARRAY['Step:1 Take a seat on the ground with your legs extended in front of you.', 'Step:2 Set your hands on the ground behind you, fingers pointing toward your body.', 'Step:3 Settle into the starting position and take an easy breath before moving deeper.', 'Step:4 Ease toward the stretch until you feel mild tension, keep breathing and avoid bouncing.', 'Step:5 Stay in a mild stretch rather than pulling farther with momentum.', 'Step:6 Hold the position with steady breathing, then release gently, repeat on the other side if needed.']::text[],
