(
  'e9e5784c-c011-5ba5-8d9c-16bd814e4b2f',
  'clean split',
  'Split Clean',
  'legs',
  'barbell',
  'quadriceps',
  ARRAY['calves', 'forearms', 'glutes', 'hamstrings', 'lower back', 'shoulders', 'traps']::text[],
  ARRAY['With a barbell on the floor close to the shins, take an overhand grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.', 'Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.', 'Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight, at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.', 'As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so.', 'Receive the bar with the feet split, aggressively moving one foot forward and one foot back. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom position, which will help in the recovery.', 'Immediately recover by driving through the heels, keeping the torso upright and elbows up. Bring the feet together as you stand up.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Split_Clean/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'a17486ac-d005-57a5-8a85-e9e9064d017e',
  'jerk split',
  'Split Jerk',
  'legs',
  'barbell',
  'quadriceps',
  ARRAY['glutes', 'hamstrings', 'shoulders', 'triceps']::text[],
  ARRAY['Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward.', 'Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders. At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible.', 'In the brief moment the feet are not actively driving against the platform, the athlete''s effort to push the bar up will drive them down. The feet should be moved to a split stance, one foot forward, one foot back, with the knees partially bent. Receive the bar with the arms locked out overhead.', 'Return to a standing position, bringing the feet together.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Split_Jerk/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '1912b723-22f0-59ac-b4a1-65ca4421be0d',
  'jump split',
  'Split Jump',
  'legs',
  'body only',
  'quadriceps',
  ARRAY['calves', 'glutes', 'hamstrings']::text[],
  ARRAY['Assume a lunge stance position with one foot forward with the knee bent, and the rear knee nearly touching the ground.', 'Ensure that the front knee is over the midline of the foot.', 'Extending through both legs, jump as high as possible, swinging your arms to gain lift.', 'As you jump, bring your feet together, and move them back to their initial positions as you land.', 'Absorb the impact by reverting back to the starting position.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Split_Jump/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '40f2158c-b4c4-5b07-b0ad-ad4a6e2686f0',
  'snatch split',
  'Split Snatch',
  'legs',
  'barbell',
  'hamstrings',
  ARRAY['calves', 'forearms', 'glutes', 'hamstrings', 'lower back', 'quadriceps', 'shoulders', 'traps', 'triceps']::text[],
  ARRAY['Begin with a loaded barbell on the floor. The bar should be close to or touching the shins, and a wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position.', 'Begin the first pull by driving through the front of the heels, raising the bar from the ground. The back angle should stay the same until the bar passes the knees.', 'Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side.', 'As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. The feet should move forcefully to a split position, one foot forward one foot back. Receive the bar with your body as low as possible and the arms fully extended overhead.', 'Keeping the bar aligned over the front of the heels, your head and chest up, drive through heels of the feet to move to a standing position, bringing your feet together.', 'Carefully return the weight to floor.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Split_Snatch/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '7661d492-a6d9-50fb-840e-0d09366bf959',
  'dumbbell split squat',
  'Split Squat with Dumbbells',
  'legs',
  'dumbbell',
  'quadriceps',
  ARRAY['glutes', 'hamstrings']::text[],
  ARRAY['Position yourself into a staggered stance with the rear foot elevated and front foot forward.', 'Hold a dumbbell in each hand, letting them hang at the sides. This will be your starting position.', 'Begin by descending, flexing your knee and hip to lower your body down. Maintain good posture througout the movement. Keep the front knee in line with the foot as you perform the exercise.', 'At the bottom of the movement, drive through the heel to extend the knee and hip to return to the starting position.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Split_Squat_with_Dumbbells/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
