  ARRAY['Step:1 Start with the barbell resting on your shoulders, with your feet about shoulder width.', 'Step:2 Before moving, lower your body into a squat position, keeping your chest up and your knees tracking over your toes.', 'Step:3 Brace before the pull and keep the load close to the body.', 'Step:4 Drive through the legs and hips, then guide the weight to its receiving position.', 'Step:5 Receive the load with the torso braced and feet stable.', 'Step:6 Stand tall to finish, then lower the weight under control before the next rep.']::text[],
