(
  '7f1ed5a0-d347-560a-874f-f25b7458e6eb',
  'bands squat',
  'Squat with Bands',
  'legs',
  'barbell',
  'quadriceps',
  ARRAY['adductors', 'calves', 'glutes', 'hamstrings', 'lower back']::text[],
  ARRAY['Set up the bands on the sleeves, secured to either band pegs, the rack, or dumbbells so that there is appropriate tension.', 'Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wide for more emphasis on the back, glutes, adductors, and hamstrings. Keep your head facing forward.', 'With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips as much as possible. Ideally, your shins should be perpendicular to the ground. Lower bar position necessitates a greater torso lean to keep the bar over the heels. Continue until you break parallel, which is defined as the crease of the hip being in line with the top of the knee.', 'Keeping the weight on your heels and pushing your feet and knees out, drive upward as you lead the movement with your head. Continue upward, maintaining tightness head to toe, until you have returned to the starting position.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Squat_with_Bands/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'bcc45c3a-fe94-56ec-bd53-916694b6a565',
  'chains squat',
  'Squat with Chains',
  'legs',
  'barbell',
  'quadriceps',
  ARRAY['adductors', 'calves', 'glutes', 'hamstrings', 'lower back']::text[],
  ARRAY['To set up the chains, begin by looping the leader chain over the sleeves of the bar. The heavy chain should be attached using a snap hook. Adjust the length of the lead chain so that a few links are still on the floor at the top of the movement.', 'Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wide for more emphasis on the back, glutes, adductors, and hamstrings. Keep your head facing forward.', 'With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips as much as possible. Ideally, your shins should be perpendicular to the ground. Lower bar position necessitates a greater torso lean to keep the bar over the heels. Continue until you break parallel, which is defined as the crease of the hip being in line with the top of the knee.', 'Keeping the weight on your heels and pushing your feet and knees out, drive upward as you lead the movement with your head. Continue upward, maintaining tightness head to toe, until you have returned to the starting position.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Squat_with_Chains/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'c3cfde1f-d130-5cae-a75f-4afbb42df1e7',
  'movers plate squat',
  'Squat with Plate Movers',
  'legs',
  'barbell',
  'quadriceps',
  ARRAY['abductors', 'adductors', 'calves', 'glutes', 'hamstrings']::text[],
  ARRAY['To begin, first set the bar on a rack to just below shoulder level. Position a weight plate on the ground a couple feet back from the rack. Once the bar is loaded, step under it and place the back of your shoulders across it.', 'Hold on to the bar with both hands and lift it off the rack by first pushing with your legs and at the same time straighten your torso.', 'Step away from the rack and adopt a wide stance with the toes slightly pointed out, with one foot on the weight plate. Keep your head up at all times. This will be your starting position.', 'Begin to slowly lower the bar by bending the knees and hips. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees.', 'Raise the bar as you exhale by pushing the floor with the heels of your feet as you extend the hips and knees.', 'At the top of the movement, side step, bringing your feet together on the opposite side of the plate.', 'Using your inside foot, push the weight plate, sliding it across the floor to where you were just standing.', 'Place your inside foot on the weight plate, adopting a wide stance for the next repetition.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Squat_with_Plate_Movers/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'fc6f4f3e-e7aa-5c9b-b246-477b48be7451',
  'squat',
  'Squats',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Place a barbell in a rack just below shoulder-height. Dip under the bar to put it behind the neck across the top of the back, and grip the bar with the hands wider than shoulder-width apart. Lift the chest up and squeeze the shoulder blades together to keep the straight back throughout the entire movement. Stand up to bring the bar off the rack and step backwards, then place the feet so that they are a little wider than shoulder-width apart. Sit back into hips and keep the back straight and the chest up, squatting down so the hips are below the knees. From the bottom of the squat, press feet into the ground and push hips forward to return to the top of the standing position.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'wger.de'
),
