(
  '68ce61fa-9e38-5a22-b991-d3ec2e266054',
  'behind crunch head range stabilityball',
  'stability ball crunch (full range hands behind head)',
  'core',
  'stability ball',
  'abdominals',
  ARRAY['hip flexors']::text[],
  ARRAY['Step:1 Take a seat on the stability ball with your feet planted and your knees bent at a 90-degree angle.', 'Step:2 Set your hands behind your head with your elbows pointing outwards.', 'Step:3 Set the pelvis and keep the neck relaxed before curling upward.', 'Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.', 'Step:5 Keep the ball steady and use the feet to manage your balance.', 'Step:6 Lower the shoulders or torso with control before the next curl.']::text[],
  'https://static.exercisedb.dev/media/Gn5FwYT.gif',
