  'master stair',
  'Stair Master',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['cardio and lower-body strength machine designed to simulate climbing stairs. It provides a low-impact, high-intensity workout that targets the legs, glutes, and core while improving cardiovascular endurance.']::text[],
