),
(
  'd59a7272-4cb0-5c54-bd65-8ca59a907581',
  'stairmaster',
  'Stairmaster',
  'legs',
  'machine',
  'quadriceps',
  ARRAY['calves', 'glutes', 'hamstrings']::text[],
  ARRAY['To begin, step onto the stairmaster and select the desired option from the menu. You can choose a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise.', 'Pump your legs up and down in an established rhythm, driving the pedals down but not all the way to the floor. It is recommended that you maintain your grip on the handles so that you don''t fall. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity.', 'Stairmasters offer convenience, cardiovascular benefits, and usually have less impact than running outside. They are typically much harder than other cardio equipment. A 150 lb person will typically burn over 300 calories in 30 minutes, compared to about 175 calories walking.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Stairmaster/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '85d70627-7661-55f8-85b6-d5ea7f080462',
  'press stalder',
  'stalder press',
  'triceps',
  'bodyweight',
  'triceps',
  ARRAY['deltoids', 'core']::text[],
  ARRAY['Step:1 Begin by standing with your feet about shoulder width and your arms extended overhead.', 'Step:2 Bend your knees slightly and Brace your trunk.', 'Step:3 Brace the torso and align the wrists with the forearms.', 'Step:4 Press the weight or handles away while keeping your trunk braced.', 'Step:5 Keep the wrists stacked and use a shoulder path that feels natural.', 'Step:6 Lower the weight to its starting height under control before pressing again.']::text[],
  'https://static.exercisedb.dev/media/zd4P4B2.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
