(
  'b95c600f-a700-568e-a8c0-676527fd53e1',
  'alternate dumbbell press standing',
  'Standing Alternating Dumbbell Press',
  'shoulders',
  'dumbbell',
  'shoulders',
  ARRAY['triceps']::text[],
  ARRAY['Stand with a dumbbell in each hand. Raise the dumbbells to your shoulders with your palms facing forward and your elbows pointed out. This will be your starting position.', 'Extend one arm to press the dumbbell straight up, keeping your off hand in place. Do not lean or jerk the weight during the movement.', 'After a brief pause, return the weight to the starting position.', 'Repeat for the opposite side, continuing to alternate between arms.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Alternating_Dumbbell_Press/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '9f570f4b-b983-55eb-9519-c347d8d0e953',
  'archer standing',
  'standing archer',
  'back',
  'bodyweight',
  'upper back',
  ARRAY['deltoids', 'biceps', 'forearms']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width and your knees soft.', 'Step:2 Reach your arms straight out in front of you at shoulder height, parallel to the ground.', 'Step:3 Set the pelvis and make the turn through the rib cage.', 'Step:4 Turn through the torso while the hips and lower body stay as steady as the setup allows.', 'Step:5 Keep the turn smooth instead of throwing the arms across the body.', 'Step:6 Return through center before turning to the other side.']::text[],
  'https://static.exercisedb.dev/media/JF8AkMX.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  '28f70049-1412-5b8b-9c0c-ff9599903bcf',
  'barbell behind neck press standing',
  'Standing Barbell Press Behind Neck',
  'shoulders',
  'barbell',
  'shoulders',
  ARRAY['triceps']::text[],
  ARRAY['This exercise is best performed inside a squat rack for easier pick up of the bar. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Your back should be kept straight while performing this exercise. This will be your starting position.', 'Elevate the barbell overhead by fully extending your arms while breathing out.', 'Hold the contraction for a second and lower the barbell back down to the starting position by inhaling.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Barbell_Press_Behind_Neck/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
