  'deltoids',
  ARRAY['triceps', 'upper back']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width and hold the barbell behind your neck with palms facing down.', 'Step:2 Keep your spine in a comfortable neutral position and core engaged.', 'Step:3 Brace the torso and align the wrists with the forearms.', 'Step:4 Press the weight or handles away while keeping your trunk braced.', 'Step:5 Keep the wrists stacked and use a shoulder path that feels natural.', 'Step:6 Lower the weight to its starting height under control before pressing again.']::text[],
  'https://static.exercisedb.dev/media/xDh0lJr.gif',
