(
  '8dbc6955-4d65-5bc9-a5b8-47c3e6deeebd',
  'biceps cable curl standing',
  'Standing Biceps Cable Curl',
  'biceps',
  'cable',
  'biceps',
  '{}'::text[],
  ARRAY['Stand up with your torso upright while holding a cable curl bar that is attached to a low pulley. Grab the cable bar at shoulder width and keep the elbows close to the torso. The palm of your hands should be facing up (supinated grip). This will be your starting position.', 'While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle.', 'Slowly begin to bring the curl bar back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Biceps_Cable_Curl/0.jpg',
