(
  '6a9e386a-1248-5eb5-b8b3-23e09b36274e',
  'bradford press standing',
  'Standing Bradford Press',
  'shoulders',
  'barbell',
  'shoulders',
  ARRAY['triceps']::text[],
  ARRAY['Place a loaded bar at shoulder level in a rack. With a pronated grip at shoulder width, begin with the bar racked across the front of your shoulders. This is your starting position.', 'Initiate the lift by extending the elbows to press the bar overhead. Avoid locking out the elbow as you move the weight behind your head.', 'Lower the bar down to the back of the head until your elbow forms a right angle.', 'Lift the bar back over your head by extending the elbows', 'Lower the bar down to the starting position.', 'Alternate in this manner until you complete the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Bradford_Press/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '9a6a08dd-1b34-563e-b501-fcf569ee73cc',
  'cable chest press standing',
  'Standing Cable Chest Press',
  'chest',
  'cable',
  'chest',
  ARRAY['shoulders', 'triceps']::text[],
  ARRAY['Position dual pulleys to chest height and select an appropriate weight. Stand a foot or two in front of the cables, holding one in each hand. You can stagger your stance for better stability.', 'Position the upper arm at a 90 degree angle with the shoulder blades together. This will be your starting position.', 'Keeping the rest of the body stationary, extend through the elbows to press the handles forward, drawing them together in front of you.', 'Pause at the top of the motion, and return to the starting position.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Cable_Chest_Press/0.jpg',
  'image',
