),
(
  'eddb16a1-e31e-5876-92f9-157d186f1ea9',
  'cable chop standing wood',
  'Standing Cable Wood Chop',
  'core',
  'cable',
  'abdominals',
  ARRAY['shoulders']::text[],
  ARRAY['Connect a standard handle to a tower, and move the cable to the highest pulley position.', 'With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Your outstretched arm should be aligned with the cable.', 'With your feet positioned shoulder width apart, reach upward with your other hand and grab the handle with both hands. Your arms should still be fully extended.', 'In one motion, pull the handle down and across your body to your front knee while rotating your torso.', 'Keep your back and arms straight and core tight while you pivot your back foot and bend your knees to get a full range of motion.', 'Maintain your stance and straight arms. Return to the neutral position in a slow and controlled manner.', 'Repeat to failure.', 'Then, reposition and repeat the same series of movements on the opposite side.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Cable_Wood_Chop/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
