(
  'bc6a0be0-bdbd-5a18-9b80-b3e02eb27c67',
  'calf raise staircase standing',
  'standing calf raise (on a staircase)',
  'legs',
  'bodyweight',
  'calves',
  ARRAY['ankles', 'feet']::text[],
  ARRAY['Step:1 Step onto the edge of a step or a sturdy platform with your heels hanging off and your toes on the step.', 'Step:2 Use a railing or wall for balance if needed.', 'Step:3 Let the ankles move freely while the rest of the body stays quiet.', 'Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Step:5 Pause at the top without rolling the ankles outward.', 'Step:6 Lower the heels at a measured pace before rising again.']::text[],
  'https://static.exercisedb.dev/media/6HmFgmx.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  '6c0feeb2-413f-59a6-b9c9-1bd832f4c56e',
  'calf raise standing',
  'Standing Calf Raises',
  'other',
  'machine',
  'calves',
  '{}'::text[],
  ARRAY['Adjust the padded lever of the calf raise machine to fit your height.', 'Place your shoulders under the pads provided and position your toes facing forward (or using any of the two other positions described at the beginning of the chapter). The balls of your feet should be secured on top of the calf block with the heels extending off it. Push the lever up by extending your hips and knees until your torso is standing erect. The knees should be kept with a slight bend, never locked. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.', 'Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.', 'Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Calf_Raises/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
