  ARRAY['Step:1 Stand and set your feet about shoulder width, toes pointing forward.', 'Step:2 Before moving, raise your heels off the ground as high as possible, standing on your toes.', 'Step:3 Let the ankles move freely while the rest of the body stays quiet.', 'Step:4 Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Step:5 Pause at the top without rolling the ankles outward.', 'Step:6 Lower the heels at a measured pace before rising again.']::text[],
