  'standing calves calf stretch',
  'legs',
  'bodyweight',
  'calves',
  ARRAY['hamstrings', 'glutes']::text[],
  ARRAY['Step:1 Face a wall or sturdy object, about an arm''s length away.', 'Step:2 Set your hands on the wall or object at shoulder height.', 'Step:3 Let the ankles move freely while the rest of the body stays quiet.', 'Step:4 Ease the heel down and shift until the calf stretches, keep the foot pointed ahead.', 'Step:5 Pause at the top without rolling the ankles outward.', 'Step:6 Lower the heels at a measured pace before rising again.']::text[],
