(
  'd2780303-6659-515e-8e1b-8c4f64ae2018',
  'above arm delt dumbbell front head raise standing straight',
  'Standing Dumbbell Straight-Arm Front Delt Raise Above Head',
  'shoulders',
  'dumbbell',
  'shoulders',
  '{}'::text[],
  ARRAY['Hold the dumbbells in front of your thighs, palms facing your thighs.', 'Keep your arms straight with a slight bend at the elbows but keep them locked. This will be your starting position.', 'Raise the dumbbells in a semicircular motion to arm''s length overhead as you exhale.', 'Slowly return to the starting position using the same path as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Dumbbell_Straight-Arm_Front_Delt_Raise_Above_Head/0.jpg',
  'image',
