  'elevated quad standing stretch',
  'Standing Elevated Quad Stretch',
  'legs',
  'other',
  'quadriceps',
  '{}'::text[],
  ARRAY['Start by standing with your back about two to three feet away from a bench or step.', 'Lift one leg behind you and rest your foot on the step,either on your instep or the ball of your foot, whichever you find most comfortable.', 'Keep your supporting knee slightly bent and avoid letting that knee extend out beyond your toes. Switch sides.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Elevated_Quad_Stretch/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
