  'calf gastrocnemius standing stretch',
  'Standing Gastrocnemius Calf Stretch',
  'other',
  '',
  'calves',
  ARRAY['hamstrings']::text[],
  ARRAY['Place your right heel on a step with your knee extended and lean forward to grab your right toe with your right hand. Your left knee should be slightly bent and your back should be straight.', 'Support your weight on your left leg and place your left hand on your left thigh.', 'Pull your right toes toward your knee until you feel a stretch in your calf.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Gastrocnemius_Calf_Stretch/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'b03c52f9-c831-58ec-b543-657fcd97e0dc',
  'calf hamstring standing stretch',
  'Standing Hamstring and Calf Stretch',
  'legs',
  'other',
  'hamstrings',
  '{}'::text[],
  ARRAY['Being by looping a belt, band, or rope around one foot. While standing, place that foot forward.', 'Bend your back leg, while keeping the front one straight. Now raise the toes of your front foot off of the ground and lean forward.', 'Using the belt, pull on the top of the foot to increase the stretch in the calf. Hold for 10-20 seconds and repeat with the other foot.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Hamstring_and_Calf_Stretch/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '502c5232-5837-5b28-97de-41e29af26e48',
  'calf hamstring standing strap stretch',
  'standing hamstring and calf stretch with strap',
  'legs',
  'rope',
  'hamstrings',
  ARRAY['calves']::text[],
  ARRAY['Step:1 Stand upright with your feet about shoulder width.', 'Step:2 Take hold of the strap with both hands and place it around the ball of your foot.', 'Step:3 Settle into the starting position and take an easy breath before moving deeper.', 'Step:4 Ease the heel down and shift until the calf stretches, keep the foot pointed ahead.', 'Step:5 Stay in a mild stretch rather than pulling farther with momentum.', 'Step:6 Hold the position with steady breathing, then release gently, repeat on the other side if needed.']::text[],
  'https://static.exercisedb.dev/media/xTjr103.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  '3c2a017c-fee5-5b6d-8232-e245929c0c38',
  'circles hip standing',
  'Standing Hip Circles',
  'legs',
  'body only',
  'abductors',
  ARRAY['adductors']::text[],
  ARRAY['Begin standing on one leg, holding to a vertical support.', 'Raise the unsupported knee to 90 degrees. This will be your starting position.', 'Open the hip as far as possible, attempting to make a big circle with your knee.', 'Perform this movement slowly for a number of repetitions, and repeat on the other side.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Hip_Circles/0.jpg',
