(
  '3ea026ff-a28e-5408-b914-01174c862423',
  'flexors hip standing',
  'Standing Hip Flexors',
  'legs',
  '',
  'quadriceps',
  '{}'::text[],
  ARRAY['Stand up straight with the spine vertical, the left foot slightly in front of the right.', 'Bend both knees and lift the back heel off the floor as you press the right hip forward. You can''t get a thorough, deep stretch in this position, however, because it''s hard to relax the hip flexor and stand on it at the same time. Switch sides.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Hip_Flexors/0.jpg',
  'image',
  'public_domain',
