(
  '156c6614-7272-5c88-bb14-f6edf060803d',
  'lateral standing stretch',
  'standing lateral stretch',
  'back',
  'bodyweight',
  'latissimus dorsi',
  ARRAY['deltoids', 'obliques']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width and your knees soft.', 'Step:2 Reach your arms straight out to the sides, parallel to the ground.', 'Step:3 Settle into the starting position and take an easy breath before moving deeper.', 'Step:4 Ease toward the stretch until you feel mild tension, keep breathing and avoid bouncing.', 'Step:5 Stay in a mild stretch rather than pulling farther with momentum.', 'Step:6 Hold the position with steady breathing, then release gently, repeat on the other side if needed.']::text[],
  'https://static.exercisedb.dev/media/1jXLYEw.gif',
