),
(
  'cb9a0ceb-7a35-5aaf-9da6-77a6e6279d1f',
  'curl leg standing',
  'Standing Leg Curl',
  'legs',
  'machine',
  'hamstrings',
  '{}'::text[],
  ARRAY['Adjust the machine lever to fit your height and lie with your torso bent at the waist facing forward around 30-45 degrees (since an angled position is more favorable for hamstrings recruitment) with the pad of the lever on the back of your right leg (just a few inches under the calves) and the front of the right leg on top of the machine pad.', 'Keeping the torso bent forward, ensure your leg is fully stretched and grab the side handles of the machine. Position your toes straight. This will be your starting position.', 'As you exhale, curl your right leg up as far as possible without lifting the upper leg from the pad. Once you hit the fully contracted position, hold it for a second.', 'As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions.', 'Perform the same exercise now for the left leg.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Leg_Curl/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'b16106bd-62fc-5b3c-b974-fb69f2da74e3',
  'jump long standing',
  'Standing Long Jump',
  'legs',
  'body only',
  'quadriceps',
  ARRAY['calves', 'glutes', 'hamstrings']::text[],
  ARRAY['This drill is best done in sand or other soft landing surface. Ensure that you are able to measure distance. Stand in a partial squat stance with feet shoulder width apart.', 'Utilizing a big arm swing and a countermovement of the legs, jump forward as far as you can.', 'Attempt to land with your feet out in front you, reaching as far as possible with your legs.', 'Measure the distance from your landing point to the starting point and track results.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Long_Jump/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '1e298a20-f4f6-5bbf-94cc-90dcc4a8d103',
  'deltoid low pulley raise standing',
  'Standing Low-Pulley Deltoid Raise',
  'shoulders',
  'cable',
  'shoulders',
  ARRAY['forearms']::text[],
  ARRAY['Start by standing to the right side of a low pulley row. Use your left hand to come across the body and grab a single handle attached to the low pulley with a pronated grip (palms facing down). Rest your arm in front of you. Your right hand should grab the machine for better support and balance.', 'Make sure that your back is erect and your feet are shoulder width apart from each other. This is the starting position.', 'Begin to use the left hand and come across your body out until it is elevated to shoulder height while exhaling.', 'Feel the contraction at the top for a second and begin to slowly lower the handle back down to the original starting position while inhaling.', 'Repeat for the recommended amount of repetitions.', 'Switch arms and repeat the exercise.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Low-Pulley_Deltoid_Raise/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'd05ba786-11b3-54f3-8e71-324ca7200ff6',
  'extension low pulley singlearm standing triceps',
  'Standing Low-Pulley One-Arm Triceps Extension',
  'triceps',
  'cable',
  'triceps',
  ARRAY['chest', 'shoulders']::text[],
  ARRAY['Grab a single handle with your left arm next to the low pulley machine. Turn away from the machine keeping the handle to the side of your body with your arm fully extended. Now use both hands to elevate the single handle directly above the head with the palm facing forward. Keep your upper arm completely vertical (perpendicular to the floor) and put your right hand on your left elbow to help keep it steady. This is the starting position.', 'Keeping your upper arms close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.', 'Go back to the starting position by using the triceps to raise the single handle. Breathe out as you perform this step.', 'Repeat for the recommended amount of repetitions.', 'Switch arms and repeat the exercise.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Low-Pulley_One-Arm_Triceps_Extension/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '8cbb4412-6591-5b67-9ec9-1e46dd33473d',
  'military press standing',
  'Standing Military Press',
  'shoulders',
  'barbell',
  'shoulders',
  ARRAY['triceps']::text[],
  ARRAY['Start by placing a barbell that is about chest high on a squat rack. Once you have selected the weights, grab the barbell using a pronated (palms facing forward) grip. Make sure to grip the bar wider than shoulder width apart from each other.', 'Slightly bend the knees and place the barbell on your collar bone. Lift the barbell up keeping it lying on your chest. Take a step back and position your feet shoulder width apart from each other.', 'Once you pick up the barbell with the correct grip length, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.', 'Lower the bar down to the collarbone slowly as you inhale.', 'Lift the bar back up to the starting position as you exhale.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Military_Press/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'cfbb2265-cfb0-5ee0-b6ab-facf93ee69c0',
  'olympic plate squeeze standing',
  'Standing Olympic Plate Hand Squeeze',
  'forearms',
  'other',
  'forearms',
  ARRAY['biceps']::text[],
  ARRAY['To begin, stand straight while holding a weight plate by the ridge at arm''s length in each hand using a neutral grip (palms facing in). You feet should be shoulder width apart from each other. This will be your starting position.', 'Lower the plates until the fingers are nearly extended but can still hold weights. Inhale as you lower the plates.', 'Now raise the plates back to the starting position as you exhale by closing your hands.', 'Repeat for the recommended amount of repetitions prescribed in your program.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Olympic_Plate_Hand_Squeeze/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'a672fe28-f837-5d0f-b2aa-d7095192a43c',
  'cable curl singlearm standing',
  'Standing One-Arm Cable Curl',
  'biceps',
  'cable',
  'biceps',
  '{}'::text[],
  ARRAY['Start out by grabbing single handle next to the low pulley machine. Make sure you are far enough from the machine so that your arm is supporting the weight.', 'Make sure that your upper arm is stationary, perpendicular to the floor with elbows in and palms facing forward. Your non lifting arm should be grabbing your waist. This will allow you to keep your balance.', 'Slowly begin to curl the single handle upwards while keeping the upper arm stationary until your forearm touches your bicep while exhaling. Tip: Only the forearm should move.', 'Hold the contraction position as you squeeze the bicep and then lower the single handle back down to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.', 'Switch arms while performing this exercise.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_One-Arm_Cable_Curl/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'd26596fb-d922-5f9a-a3b3-bf996bfc5992',
  'dumbbell extension singlearm standing triceps',
  'Standing One-Arm Dumbbell Triceps Extension',
  'triceps',
  'dumbbell',
  'triceps',
  ARRAY['chest', 'shoulders']::text[],
  ARRAY['To begin, stand up with a dumbbell held in one hand. Your feet should be about shoulder width apart from each other. Now fully extend the arm with the dumbbell over your head. Tip: The small finger of your hand should be facing the ceiling and the palm of your hand should be facing forward. The dumbbell should be above your head.', 'This will be your starting position.', 'Keeping your upper arm close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearm touch your bicep. Tip: The upper arm should remain stationary and only the forearm should move. Breathe in as you perform this step.', 'Go back to the starting position by using the triceps to raise the dumbbell. Breathe out as you perform this step.', 'Repeat for the recommended amount of repetitions.', 'Switch arms and repeat the exercise.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_One-Arm_Dumbbell_Triceps_Extension/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '0dfec93a-c28d-5f90-9669-6eb346a76b9d',
  'dumbbell palms press standing',
  'Standing Palms-In Dumbbell Press',
  'shoulders',
  'dumbbell',
  'shoulders',
  ARRAY['triceps']::text[],
  ARRAY['Start by having a dumbbell in each hand with your arm fully extended to the side using a neutral grip. Your feet should be shoulder width apart from each other. Now slowly lift the dumbbells up until you create a 90 degree angle with your arms. Note: Your forearms should be perpendicular to the floor. This the starting position.', 'Continue to maintain a neutral grip throughout the entire exercise. Slowly lift the dumbbells up until your arms are fully extended.', 'While inhaling lower the weights down until your arm is at a 90 degree angle again.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Palms-In_Dumbbell_Press/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '81cc32b4-d642-574e-b6da-0b6fff423385',
  'back barbell behind curl palms standing up wrist',
  'Standing Palms-Up Barbell Behind The Back Wrist Curl',
  'forearms',
  'barbell',
  'forearms',
  '{}'::text[],
  ARRAY['Start by standing straight and holding a barbell behind your glutes at arm''s length while using a pronated grip (palms will be facing back away from the glutes) and having your hands shoulder width apart from each other.', 'You should be looking straight forward while your feet are shoulder width apart from each other. This is the starting position.', 'While exhaling, slowly elevate the barbell up by curling your wrist in a semi-circular motion towards the ceiling. Note: Your wrist should be the only body part moving for this exercise.', 'Hold the contraction for a second and lower the barbell back down to the starting position while inhaling.', 'Repeat for the recommended amount of repetitions.', 'When finished, lower the barbell down to the squat rack or the floor by bending the knees. Tip: It is easiest to either pick it up from a squat rack or have a partner hand it to you.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Palms-Up_Barbell_Behind_The_Back_Wrist_Curl/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
