(
  'f7e62e9b-7be6-51a1-9a59-d182df53bebb',
  'pelvic standing tilt',
  'standing pelvic tilt',
  'back',
  'bodyweight',
  'erector spinae',
  ARRAY['abdominals']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width and your knees soft.', 'Step:2 Set your arms at your sides, or set your hands at your waist.', 'Step:3 Relax the shoulders and find a comfortable neutral starting position.', 'Step:4 Gently roll the pelvis to flatten and release the lower back through a small range.', 'Step:5 Use a small range and avoid forcing the lower back into the floor.', 'Step:6 Release the tilt gently and repeat without forcing the range.']::text[],
