(
  'a775ab97-2779-5485-9c82-3819fbb417c8',
  'crunch rope standing',
  'Standing Rope Crunch',
  'core',
  'cable',
  'abdominals',
  '{}'::text[],
  ARRAY['Attach a rope to a high pulley and select an appropriate weight.', 'Stand with your back to the cable tower. Take the rope with both hands over your shoulders, holding it to your upper chest. This will be your starting position.', 'Perform the movement by flexing the spine, crunching the weight down as far as you can.', 'Hold the peak contraction for a moment before returning to the starting position.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Rope_Crunch/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '9e349e29-3368-5683-9e36-9d6d794ceed0',
  'forearm rope standing',
  'Standing Rope Forearm',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Grab a wrist roller tool with both hands while standing with your feet about shoulder width apart. If your gym does not have a wrist roller tool, you can easily put one together. All you need is a 5 or 10 pound weight plate, a strong thin rope about 3 feet long and a 6-8 inch stick or bar. Securely fasten the rope to the middle of the bar/stick and tie the other end of the rope to the weight plate. To begin this exercise, grab the bar/stick with both hands using an overhand grip. Extend both arms straight out in front of you, parallel to the floor. Next, roll the weight up from the floor by rapidly twisting the bar/stick with your hands and wrists. Once the weight reaches the top, slowly lower the plate back to the floor by reversing the motion of your hands and wrists. Repeat (if you can!).']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'pwiltrout'
),
(
  'fe843fd2-3e6a-5def-a666-359c2fc6b626',
  'crunch side standing',
  'Standing Side Crunches',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Standing side crunches are a dynamic exercise that targets the obliques while improving balance and stability. Stand upright with your feet shoulder-width apart and hands behind your head or holding a dumbbell in one hand. Lean your torso to one side, contracting your obliques, while bringing your elbow toward your hip (or crunching toward the weight if using a dumbbell). Return to the starting position and alternate sides or perform all repetitions on one side before switching.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'hpmbala@gmail.com'
),
(
  'a340cd1c-3179-57c5-87ad-8b3549ec7526',
  'curl singleleg standing',
  'standing single leg curl',
  'legs',
  'bodyweight',
  'hamstrings',
  ARRAY['glutes']::text[],
  ARRAY['Step:1 Stand and set your feet about hip width and your hands on your hips.', 'Step:2 Transfer your weight onto your left leg and lift your right foot off the ground, bending your knee.', 'Step:3 Line the knees up with the machine or bench edge before starting the curl.', 'Step:4 Bend your knees to draw the pad toward you without lifting your hips from the support.', 'Step:5 Keep the hips still while the knees bend.', 'Step:6 Ease back to the start before repeating.']::text[],
  'https://static.exercisedb.dev/media/C5jncD2.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  '4b7faf07-a6b2-5cd7-992f-a378973277d7',
  'achilles soleus standing stretch',
  'Standing Soleus And Achilles Stretch',
  'other',
  '',
  'calves',
  '{}'::text[],
  ARRAY['Stand with your feet hip-distance apart, one foot slightly in front of the other.', 'Bend both knees, keeping your back heel on the floor. Switch sides.']::text[],
