  'standing toe touch',
  'Standing Toe Touch',
  'legs',
  'bodyweight',
  'glutes',
  ARRAY['hamstrings', 'calves']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width and your arms by your sides.', 'Step:2 Bend forward at the waist, with your spine steady and your knees soft.', 'Step:3 Settle into the starting position and take an easy breath before moving deeper.', 'Step:4 Fold forward from the hips and let your hands travel toward your feet without forcing the reach.', 'Step:5 Stay in a mild stretch rather than pulling farther with momentum.', 'Step:6 Hold briefly at a comfortable depth, then rise by extending the hips.']::text[],
  'https://static.exercisedb.dev/media/BbfB8Gb.gif',
