  'hamstrings',
  ARRAY['calves']::text[],
  ARRAY['Stand with some space in front and behind you.', 'Bend at the waist, keeping your legs straight, until you can relax and let your upper body hang down in front of you. Let your arms and hands hang down naturally. Hold for 10 to 20 seconds.']::text[],
