  'shoulders',
  ARRAY['chest', 'lats']::text[],
  ARRAY['Stand with your feet shoulder width apart holding a medicine ball in both hands. To begin, reach the medicine ball deep behind your head as you bend the knees slightly and lean back.', 'Violently throw the ball forward, flexing at the hip and using your whole body to complete the movement.', 'The medicine ball can be thrown to a partner or to a wall, receiving it as it bounces back.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Two-Arm_Overhead_Throw/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'bda98858-dc4f-5e20-a2ef-7a63b53b1abd',
  'rollout standing wheel',
  'Standing Wheel Rollout',
  'core',
  'ab wheel',
  'abdominals',
  ARRAY['erector spinae', 'deltoids']::text[],
  ARRAY['Step:1 Begin by standing tall with your feet about shoulder width and the wheel roller in front of you.', 'Step:2 Bend at your waist and With control roll the wheel forward, with your spine steady and your core engaged.', 'Step:3 Tighten the abdomen and keep the pelvis tucked before the arms reach away.', 'Step:4 Reach the arms away while keeping your ribs and pelvis aligned, stop before the lower back sags.', 'Step:5 Stop reaching when the lower back starts to sag.', 'Step:6 Pull back to the start through your shoulders and abdominals, keeping the same body line.']::text[],
  'https://static.exercisedb.dev/media/KtRomty.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  '8a4b313b-8cd5-5824-a1b2-6da5149ca749',
