  'bodyweight',
  'cardiovascular system',
  ARRAY['quadriceps', 'hamstrings', 'calves']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width and your arms by your sides.', 'Step:2 Before moving, bend your knees slightly and jump up explosively.', 'Step:3 Bend the hips and knees slightly to load the jump.', 'Step:4 Load the legs with a small bend, then drive through the floor and land softly.', 'Step:5 Land with bent hips and knees and let the feet absorb the impact.', 'Step:6 Absorb the landing through the hips and knees before repeating.']::text[],
  'https://static.exercisedb.dev/media/HtfCpfi.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
