(
  '3699309e-1b3f-5998-93f5-6bae478196f0',
  'bike cardio stationary',
  'Stationary bike cardio',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['**Benefits of Stationary Bike Cardio**', 'Stationary bike cardio is an excellent form of exercise that offers multiple benefits for health and well-being. Here are some of the most notable ones:', '**Improved Cardiovascular Health**', '- **Strengthens the heart:** Regular exercise helps improve the heart''s efficiency and reduce the risk of cardiovascular disease.', '- **Increases circulation:** It improves blood flow, which can help lower blood pressure.', '**Calorie Burning and Weight Loss**', '- **Efficient for burning calories:** Depending on the intensity, you can burn between 400 and 600 calories per hour.', '- **Helps with weight loss:** Combined with a balanced diet, stationary bike cardio can be effective for losing weight.', '**Muscle Strengthening**', '- **Tones the legs:** It mainly works the leg muscles, including the quadriceps, hamstrings and calves.', '- **Improves muscular endurance:** Over time, you can increase the endurance and strength in your legs.', '**Mental Health Benefits**', '- **Reduces stress:** Exercise releases endorphins, which can improve your mood and reduce stress.', '- **Boosts energy:** Regular physical activity can raise your energy levels and improve sleep quality.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'Tierrasverdes'
),
(
  '38906fe6-bbd4-5a23-b074-44be75769de5',
  'bike run stationary',
  'stationary bike run',
  'cardio',
  'stationary bike',
  'cardiovascular system',
  ARRAY['quadriceps', 'hamstrings', 'calves']::text[],
  ARRAY['Step:1 Set the seat height and position to ensure proper alignment.', 'Step:2 Set your feet on the pedals and secure them with the straps if available.', 'Step:3 Start at a pace that lets the feet and arms move in sync.', 'Step:4 Move at a repeatable pace, keeping the motion smooth and your breathing steady.', 'Step:5 Keep the pattern repeatable as speed increases.', 'Step:6 Keep the rhythm for the planned interval, slowing if your form starts to slip.']::text[],
  'https://static.exercisedb.dev/media/H1PESYI.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
