  'cardiovascular system',
  ARRAY['quadriceps', 'hamstrings', 'calves']::text[],
  ARRAY['Step:1 Set the seat height and position on the stationary bike to ensure proper alignment.', 'Step:2 Set your feet on the pedals and secure them with the straps if available.', 'Step:3 Start at a pace that lets the feet and arms move in sync.', 'Step:4 Move at a repeatable pace, keeping the motion smooth and your breathing steady.', 'Step:5 Keep the pattern repeatable as speed increases.', 'Step:6 Keep the rhythm for the planned interval, slowing if your form starts to slip.']::text[],
