(
  'd30e747a-0b4c-5a7e-a835-a6bd46fc52f7',
  'calf step stretch',
  'Step Calf Stretch',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Stand on a step or a sturdy raised surface with the balls of both feet on the edge and the heels hanging off, holding a rail or wall for balance. Let one or both heels drop below the level of the step until you feel a stretch through the calf, and hold. Keep the knee straight to stretch the gastrocnemius, or bend the knee slightly to bias the soleus lower down. Hold for the prescribed time, typically 30 seconds, without bouncing, then switch sides if stretching one leg at a time.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'trs1800'
),
(
  '242945b7-52b7-5b19-9340-92ad0ec019bc',
  'jack step',
  'Step Jack',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['The Step Jack is a low-impact plyometric-style move that provides cardiovascular benefits without the joint stress of jumping. It works the entire body, specifically targeting the legs, core, and shoulders. This move is ideal for beginners, individuals with joint sensitivities, or as a dynamic warm-up to gradually elevate the heart rate.', 'Notes (Instructions):', '1. ​Stand upright with your feet together and arms at your sides.', '2. ​Step your right foot out to the side while simultaneously swinging both arms up above your head.', '3. Bring your right foot back to the center and lower your arms.', '4. ​Immediately repeat the movement, stepping out with your left foot.', '5. ​Continue alternating sides at a steady, rhythmic pace.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'Anon#2'
),
(
  'eeca2844-7a5e-5e5b-8e21-39b0bfb3edc3',
  'mill step',
  'Step Mill',
  'legs',
  'machine',
  'quadriceps',
  ARRAY['calves', 'glutes', 'hamstrings']::text[],
  ARRAY['To begin, step onto the stepmill and select the desired option from the menu. You can choose a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Use caution so that you don''t trip as you climb the stairs. It is recommended that you maintain your grip on the handles so that you don''t fall.', 'Stepmills offer convenience, cardiovascular benefits, and usually have less impact than running outside while offering a similar rate of calories burned. They are typically much harder than other cardio equipment. A 150 lb person will typically burn over 300 calories in 30 minutes, compared to about 175 calories walking.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Step_Mill/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '9347dd73-3324-5c04-b50a-980158502fd1',
  'knee raise step up',
  'Step-up with Knee Raise',
  'legs',
  'body only',
  'glutes',
  ARRAY['hamstrings', 'quadriceps']::text[],
  ARRAY['Stand facing a box or bench of an appropriate height with your feet together. This will be your starting position.', 'Begin the movement by stepping up, putting your left foot on the top of the bench. Extend through the hip and knee of your front leg to stand up on the box. As you stand on the box with your left leg, flex your right knee and hip, bringing your knee as high as you can.', 'Reverse this motion to step down off the box, and then repeat the sequence on the opposite leg.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Step-up_with_Knee_Raise/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
