(
  'b264f98c-a136-5f1a-810b-677e3b981b8c',
  'barbell deadlift legged stiff',
  'Stiff-Legged Barbell Deadlift',
  'legs',
  'barbell',
  'hamstrings',
  ARRAY['glutes', 'lower back']::text[],
  ARRAY['Grasp a bar using an overhand grip (palms facing down). You may need some wrist wraps if using a significant amount of weight.', 'Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.', 'Keeping the knees stationary, lower the barbell to over the top of your feet by bending at the hips while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Inhale as you perform this movement.', 'Start bringing your torso up straight again by extending your hips until you are back at the starting position. Exhale as you perform this movement.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Stiff-Legged_Barbell_Deadlift/0.jpg',
  'image',
  'public_domain',
