  'deadlift dumbbell legged stiff',
  'Stiff-Legged Dumbbell Deadlift',
  'legs',
  'dumbbell',
  'hamstrings',
  ARRAY['glutes', 'lower back']::text[],
  ARRAY['Grasp a couple of dumbbells holding them by your side at arm''s length.', 'Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.', 'Keeping the knees stationary, lower the dumbbells to over the top of your feet by bending at the waist while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Exhale as you perform this movement', 'Start bringing your torso up straight again by extending your hips and waist until you are back at the starting position. Inhale as you perform this movement.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Stiff-Legged_Dumbbell_Deadlift/0.jpg',
  'image',
