  'bodyweight',
  'abdominals',
  ARRAY['deltoids', 'triceps', 'pectorals']::text[],
  ARRAY['Step:1 Begin in a push-up position with your hands about shoulder width and your feet spread wide apart.', 'Step:2 Brace your trunk and With control shift your weight forward, bringing your shoulders over your hands.', 'Step:3 Brace the abdomen and find a position you can maintain without holding your breath.', 'Step:4 Brace your midsection and hold the position while breathing normally.', 'Step:5 Keep breathing steadily as you maintain the same body line.', 'Step:6 Keep the shape for the planned time, then come out of it with control.']::text[],
