  ARRAY['Step:1 Settle onto your side with your legs straight and stacked on top of each other.', 'Step:2 Set your bottom arm under your head for support.', 'Step:3 Square the pelvis before moving the working leg.', 'Step:4 Move the working leg sideways from the hip without swinging your torso.', 'Step:5 Move only as far as the pelvis can remain steady.', 'Step:6 Return along the same path at a controlled pace.']::text[],
