  'crossover jump stride',
  'Stride Jump Crossover',
  'legs',
  'other',
  'quadriceps',
  ARRAY['abductors', 'adductors', 'calves', 'hamstrings']::text[],
  ARRAY['Stand to the side of a box with your inside foot on top of it, close to the edge.', 'Begin by swinging the arms upward as you push through the top leg, jumping upward as high as possible. Attempt to drive the opposite knee upward.', 'Land in the opposite position that you started, on the opposite side of the box. The foot that was initially on the box will now be on the ground, with the opposite foot now on the box.', 'Repeat the movement, crossing back over to the other side.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Stride_Jump_Crossover/0.jpg',
