(
  'fd97f6d0-35e0-53c1-9090-8a61f40c2f33',
  'deadlift sumo',
  'Sumo Deadlift',
  'legs',
  'barbell',
  'hamstrings',
  ARRAY['adductors', 'forearms', 'glutes', 'lower back', 'middle back', 'quadriceps', 'traps']::text[],
  ARRAY['Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms.', 'Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.', 'As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.', 'Return the weight to the ground by bending at the hips and controlling the weight on the way down.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Sumo_Deadlift/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
