  ARRAY['Stand with your feet wider than your shoulders, with your toes pointed out at a 45 degree angle and barbell on your shoulder.', 'While keeping your back straight, descend slowly by bending at the knees and hips as if you are sitting down (squatting).', 'Lower yourself until your quadriceps and hamstrings are parallel to the floor.', 'Return to the starting position by pressing upwards and extending your legs while maintaining an equal distribution of weight on your forefoot and heel.']::text[],
