  'abdominals',
  ARRAY['obliques', 'hip flexors']::text[],
  ARRAY['Step:1 Connect a suspension trainer to a high anchor point and adjust the straps to waist height.', 'Step:2 Face away from the anchor point and hold the handles with your arms extended in front of you.', 'Step:3 Tighten the abdomen and keep the pelvis tucked before the arms reach away.', 'Step:4 Reach the arms away while keeping your ribs and pelvis aligned, stop before the lower back sags.', 'Step:5 Stop reaching when the lower back starts to sag.', 'Step:6 Pull back to the start through your shoulders and abdominals, keeping the same body line.']::text[],
