  ARRAY['hip flexors']::text[],
  ARRAY['Step:1 Suspend yourself from a pull-up bar with your arms straight and your palms turned away from you.', 'Step:2 Brace your trunk and lift your knees up toward your chest, curling your pelvis toward your ribcage.', 'Step:3 Set the pelvis and keep the neck relaxed before curling upward.', 'Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.', 'Step:5 Leave a little space between the chin and chest, keep the movement in the torso.', 'Step:6 Lower the shoulders or torso with control before the next curl.']::text[],
