  ARRAY['biceps', 'deltoids']::text[],
  ARRAY['Step:1 Prepare a suspension trainer at an appropriate height.', 'Step:2 Face the anchor point from a stable stance with feet about shoulder width.', 'Step:3 Set the torso and allow the arms to reach forward without rounding excessively.', 'Step:4 Draw your elbows back and bring the handle or weight toward your torso.', 'Step:5 Bring the elbows back without jerking the torso.', 'Step:6 Reach the arms forward again without letting the torso lurch.']::text[],
