  'quadriceps',
  ARRAY['glutes', 'hamstrings', 'calves']::text[],
  ARRAY['Step:1 Face the away from a suspension trainer from a stable stance with feet about shoulder width.', 'Step:2 Reach one leg forward and place the top of your foot in the foot cradle of the suspension trainer.', 'Step:3 Brace the abdomen and spread pressure across the whole foot.', 'Step:4 Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Step:5 Drive upward with the chest and hips rising together, keep the knees from collapsing inward.', 'Step:6 Stand fully, reset your footing and breathing, then begin the next descent.']::text[],
