  ARRAY['forearms', 'shoulders', 'triceps']::text[],
  ARRAY['Begin in a standing position.', 'Press two lightweight plates together with your hands. Hold the plates together close to your chest to create an isometric contraction in your chest muscles. Your fingers should be pointed forward. This is your starting position.', 'Squeeze the plates between your palms and extend your arms directly out in front of you in a controlled motion.', 'Pause at the top of the motion, and then slowly return to the starting position.']::text[],
