  'glutes',
  ARRAY['hamstrings', 'quadriceps', 'calves']::text[],
  ARRAY['Step:1 Position yourself face down on a mat with your arms extended overhead.', 'Step:2 Brace your trunk and lift your chest and legs off the ground simultaneously.', 'Step:3 Brace the trunk lightly before moving a limb.', 'Step:4 Move the working arm or leg while keeping the trunk steady and the breathing even.', 'Step:5 Keep the pelvis from rocking as the arm or leg moves.', 'Step:6 Reset your posture before changing sides or beginning the next rep.']::text[],
