  ARRAY['deltoids', 'core']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width and knees soft.', 'Step:2 Keep your arms straight out in front of you, parallel to the ground.', 'Step:3 Set the shoulders and let the weight move back between the legs as the hips hinge.', 'Step:4 Hinge back, then drive the hips forward to send the weight up, let the arms guide it.', 'Step:5 Let the hips, not the shoulders, provide the power.', 'Step:6 Let the weight fall naturally and hinge again for the next swing.']::text[],
