(
  '3b3f212a-fbe6-5b1f-aca1-4c9a14a3cc65',
  'abductor thigh',
  'Thigh Abductor',
  'legs',
  'machine',
  'abductors',
  ARRAY['glutes']::text[],
  ARRAY['To begin, sit down on the abductor machine and select a weight you are comfortable with. When your legs are positioned properly, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.', 'Slowly press against the machine with your legs to move them away from each other while exhaling.', 'Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary to prevent any injuries from occurring.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Thigh_Abductor/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'd7567ad8-c6b4-52e3-84b5-836429cb2a84',
  'adductor thigh',
  'Thigh Adductor',
  'legs',
  'machine',
  'adductors',
  ARRAY['glutes', 'hamstrings']::text[],
  ARRAY['To begin, sit down on the adductor machine and select a weight you are comfortable with. When your legs are positioned properly on the leg pads of the machine, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.', 'Slowly press against the machine with your legs to move them towards each other while exhaling.', 'Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary and avoid fast jerking motions in order to prevent any injuries from occurring.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Thigh_Adductor/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
