(
  'e83cfdfc-8732-5476-b272-0dd52115cfb4',
  'flip tire',
  'tire flip',
  'legs',
  'tire',
  'glutes',
  ARRAY['hamstrings', 'quadriceps', 'core']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width, facing the tire.', 'Step:2 Before moving, bend your knees and hinge at the hips, lowering into a squat position.', 'Step:3 Unlock the knees and brace the abdomen before moving the hips back.', 'Step:4 Push the hips back while keeping the load close and the spine steady.', 'Step:5 Keep the weight close to the legs and stop when the back would begin to round.', 'Step:6 Drive the hips forward to stand tall without leaning back at the top.']::text[],
