(
  '4841c287-f0fd-58c9-bbb1-6edc01c6bd11',
  'taps toe',
  'Toe Taps',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Toe taps are a core-focused exercise performed lying on your back. Lie flat with your arms by your sides and your legs raised to a tabletop position (knees bent at 90 degrees). Slowly lower one foot to gently tap the floor, keeping your core engaged and your lower back pressed into the ground. Return to the starting position and alternate legs. This exercise strengthens the core while minimizing strain on the lower back.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'hpmbala@gmail.com'
),
(
  'd679d605-e9b6-5686-adb6-3bdbe2d4162d',
  'toe touchers',
  'Toe Touchers',
  'core',
  'body only',
  'abdominals',
  '{}'::text[],
  ARRAY['To begin, lie down on the floor or an exercise mat with your back pressed against the floor. Your arms should be lying across your sides with the palms facing down.', 'Your legs should be touching each other. Slowly elevate your legs up in the air until they are almost perpendicular to the floor with a slight bend at the knees. Your feet should be parallel to the floor.', 'Move your arms so that they are fully extended at a 45 degree angle from the floor. This is the starting position.', 'While keeping your lower back pressed against the floor, slowly lift your torso and use your hands to try and touch your toes. Remember to exhale while perform this part of the exercise.', 'Slowly begin to lower your torso and arms back down to the starting position while inhaling. Remember to keep your arms straight out pointing towards your toes.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Toe_Touchers/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '3075015e-4686-5aa6-a8b7-45fac32263b9',
  'bar toes',
  'Toes to bar',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['The name "Toes to Bar" says it all: This exercise, in which you hang from a pull-up bar, involves bringing your toes toward the bar, pointing toward your face. This really works your abdominal muscles. "Toes to Bar" is popular in functional fitness programs like Freeletics and CrossFit, and is an effective exercise for six-pack training.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'florian.bussmann'
),
