  'Torso Rotation',
  'core',
  'exercise ball',
  'abdominals',
  '{}'::text[],
  ARRAY['Stand upright holding an exercise ball with both hands. Extend your arms so the ball is straight out in front of you. This will be your starting position.', 'Rotate your torso to one side, keeping your eyes on the ball as you move. Now, rotate back to the opposite direction. Repeat for 10-20 repetitions.']::text[],
