(
  'b311ee8c-a090-5542-9943-aa100b29c923',
  'rotation stretch torso',
  'Torso rotation stretch',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['The torso rotation stretch helps improve spinal mobility and relieves tension in the lower back and obliques. It can be performed standing or seated.', '1. **Standing Variation**: Stand upright with your feet shoulder-width apart. Place your hands on your hips or extend your arms in front of you. Slowly rotate your torso to one side, keeping your hips stable. Hold for a few seconds, then rotate to the opposite side.', '2. **Seated Variation**: Sit on a chair with your feet flat on the floor. Place one hand on the outside of your opposite thigh and gently twist your torso toward that side. Hold the stretch before switching sides.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'hpmbala@gmail.com'
),
(
  '1daf37b1-8b28-5863-95d2-9a6a546df8fb',
  'torso twist',
  'Torso Twist',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Standing Torso Twist WorkoutTarget your core and improve flexibility with this dynamic standing exercise! The Standing Torso Twist Workout involves twisting your torso while keeping your feet and hips stable, engaging your obliques, and stretching your entire upper body. This movement helps to:Strengthen core musclesIncrease flexibility in the spine and torsoImprove posture and balanceEnhance overall athletic performancePerform 3 sets of 10-15 reps, twisting to each side, to feel the benefits of this effective and efficient workout!']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'brucem'
),
