  '{}'::text[],
  ARRAY['In this exercise, you lie flat on your stomach, hold a', 'towel with your arms extended in front of you, and pull it apart to', 'create tension. Then, you move it forward and back under your stomach.', 'This exercise targets the back and shoulder muscles as well as core', 'stability.']::text[],
