  ARRAY['Step:1 Stand and set your feet about shoulder width and the trap bar on the ground in front of you.', 'Step:2 Bend at the hips and knees to lower yourself down and grip the handles of the trap bar with palms facing down.', 'Step:3 Unlock the knees and brace the abdomen before moving the hips back.', 'Step:4 Push the hips back while keeping the load close and the spine steady.', 'Step:5 Keep the weight close to the legs and stop when the back would begin to round.', 'Step:6 Drive the hips forward to stand tall without leaning back at the top.']::text[],
