(
  '32f996a7-31ea-5ed3-b4d4-3dfc25acff46',
  'cardio treadmill',
  'Treadmill Cardio',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['It''s a cardiovascular workout performed on a treadmill to improve endurance, burn calories, and promote heart health. It offers multiple benefits, such as the ability to easily adjust speed and incline, allowing for a variety of workouts, from hill walking to high-intensity interval training (HIIT) and tempo runs. To optimize results, it''s important to vary your workouts.', 'Benefits of Treadmill Cardio:', '- Improved Cardiovascular Health:', 'Regular aerobic exercise on a treadmill strengthens the heart and lungs, which can help prevent heart disease.', '- Weight Loss:', 'By burning calories, treadmill training can be an effective tool for weight loss and maintaining a healthy weight.', '- Muscle Strengthening:', 'It strengthens the muscles in the legs and glutes, helping to prevent muscle loss, which is especially important with age.', '- Training Flexibility:', 'Allows you to vary speed, incline, and intervals, making your workout more dynamic and adaptable to different fitness levels.', 'Types of Treadmill Training:', '- Hill Walking:', 'Increasing the incline of the treadmill and walking at a brisk pace can improve endurance and work your leg muscles.', '- Endurance Jog:', 'A run at a comfortable, steady pace that keeps your heart rate in a target zone (such as Zone 2) to build endurance.', '- Interval Training:', 'Alternating periods of high intensity (fast running) with periods of low intensity (easy walking or jogging) to maximize calorie burn and cardiovascular improvement.', '- Tempo Run:', 'A run at a steady, sustained pace that is slightly faster than a normal jog, which challenges your ability to sustain a more intense effort for an extended period.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'Tierrasverdes'
),
(
  'b1155d7e-752e-549b-bc6f-3e61499c4bd2',
  'dumbbell kickback tricep',
  'Tricep Dumbbell Kickback',
  'triceps',
  'dumbbell',
  'triceps',
  '{}'::text[],
  ARRAY['Start with a dumbbell in each hand and your palms facing your torso. Keep your back straight with a slight bend in the knees and bend forward at the waist. Your torso should be almost parallel to the floor. Make sure to keep your head up. Your upper arms should be close to your torso and parallel to the floor. Your forearms should be pointed towards the floor as you hold the weights. There should be a 90-degree angle formed between your forearm and upper arm. This is your starting position.', 'Now, while keeping your upper arms stationary, exhale and use your triceps to lift the weights until the arm is fully extended. Focus on moving the forearm.', 'After a brief pause at the top contraction, inhale and slowly lower the dumbbells back down to the starting position.', 'Repeat the movement for the prescribed amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Tricep_Dumbbell_Kickback/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'f3844b76-7ea9-5139-81fc-9146e22b795d',
  'cable pushdown tricep',
  'Tricep Pushdown on Cable',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['The cable rope push-down is a popular exercise targeting the triceps muscles. It''s easy to learn and perform, making it a favorite for everyone from beginners to advanced lifters. It is usually performed for moderate to high reps, such as 8-12 reps or more per set, as part of an upper-body or arm-focused workout.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'cshep442'
),
(
  'b2ca4e24-b025-5a5b-848d-662769a1305c',
  'pushdown rope tricep',
  'Tricep Rope Pushdowns',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['- **Setup:** Stand facing the cable, feet shoulder-width apart, with a slight forward lean.', '- **Grip:** Hold the rope with palms facing each other and elbows tucked tight to your ribs.', '- **Execution:** Push the rope down until arms are fully straight, pulling the ends apart at the bottom.', '- **Control:** Keep upper arms still and return to the start with a slow, controlled motion.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'nishant0712'
),
