  ARRAY['Step:1 Take a seat on the edge of a bench or chair with your hands gripping the edge, fingers pointing forward.', 'Step:2 Move your butt off the bench, supporting your weight with your hands.', 'Step:3 Set the shoulders down and keep the elbows pointed mostly behind you.', 'Step:4 Bend the elbows to lower between the supports, stop at a comfortable shoulder depth.', 'Step:5 Choose a depth that lets the shoulders stay comfortable.', 'Step:6 Press through the hands to rise, then reset the shoulders before another rep.']::text[],
