(
  '6c7d5b8f-25f8-5a18-9648-ba89ec581270',
  'extension overhead rope triceps',
  'Triceps Overhead Extension with Rope',
  'triceps',
  'cable',
  'triceps',
  '{}'::text[],
  ARRAY['Attach a rope to a low pulley. After selecting an appropriate weight, grasp the rope with both hands and face away from the cable.', 'Position your hands behind your head with your elbows point straight up. Your elbows should start out flexed, and you can stagger your stance and lean gently away from the machine to create greater stability. This will be your starting position.', 'To perform the movement, extend through the elbow while keeping the upper arm in position, raising your hands above your head.', 'Squeeze your triceps at the top of the movement, and slowly lower the weight back to the start position.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Triceps_Overhead_Extension_with_Rope/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
