(
  'c4963c6f-e523-55a8-a099-b96a48ed1529',
  'pushdown triceps',
  'Triceps Pushdown',
  'triceps',
  'cable',
  'triceps',
  '{}'::text[],
  ARRAY['Attach a straight or angled bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width.', 'Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the bar. This is your starting position.', 'Using the triceps, bring the bar down until it touches the front of your thighs and the arms are fully extended perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.', 'After a second hold at the contracted position, bring the bar slowly up to the starting point. Breathe in as you perform this step.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Triceps_Pushdown/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'b39ee234-4c30-5e86-a299-8db761ca12be',
  'attachment pushdown rope triceps',
  'Triceps Pushdown - Rope Attachment',
  'triceps',
  'cable',
  'triceps',
  '{}'::text[],
  ARRAY['Attach a rope attachment to a high pulley and grab with a neutral grip (palms facing each other).', 'Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the rope with the palms facing each other. This is your starting position.', 'Using the triceps, bring the rope down as you bring each side of the rope to the side of your thighs. At the end of the movement the arms are fully extended and perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.', 'After holding for a second, at the contracted position, bring the rope slowly up to the starting point. Breathe in as you perform this step.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Triceps_Pushdown_-_Rope_Attachment/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '32809e4f-4b2a-53cf-9e73-154548c29e42',
  'attachment bar pushdown triceps v',
  'Triceps Pushdown - V-Bar Attachment',
  'triceps',
  'cable',
  'triceps',
  '{}'::text[],
  ARRAY['Attach a V-Bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width.', 'Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the bar. The thumbs should be higher than the small finger. This is your starting position.', 'Using the triceps, bring the bar down until it touches the front of your thighs and the arms are fully extended perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.', 'After a second hold at the contracted position, bring the V-Bar slowly up to the starting point. Breathe in as you perform this step.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Triceps_Pushdown_-_V-Bar_Attachment/0.jpg',
