  ARRAY['Step:1 Settle onto your back with your knees bent and feet planted.', 'Step:2 Set your hands by your sides for support.', 'Step:3 Plant the feet and keep the ribs from flaring as the hips prepare to rise.', 'Step:4 Press through the feet and lift your hips until your torso and thighs line up.', 'Step:5 Stop when the hips line up with the torso, do not arch higher through the lower back.', 'Step:6 Lower the hips steadily and keep the feet planted for the next lift.']::text[],
