  ARRAY['obliques', 'hip flexors']::text[],
  ARRAY['Step:1 Settle onto your back with your legs extended and your arms by your sides.', 'Step:2 Bend your knees and lift your legs off the ground, bringing them toward your chest.', 'Step:3 Brace the abdomen and keep the shoulders anchored to the support.', 'Step:4 Lift your legs by bracing your trunk and moving at the hips rather than swinging.', 'Step:5 Slow the legs before they pull the lower back out of position.', 'Step:6 Lower the legs slowly without swinging or losing your trunk position.']::text[],
