  ARRAY['hamstrings', 'glutes']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width and your arms extended out to the sides.', 'Step:2 Bend forward at the waist, with your spine steady and your knees soft.', 'Step:3 Soften the knees and let the hips start the fold.', 'Step:4 Fold forward from the hips and let your hands travel toward your feet without forcing the reach.', 'Step:5 Keep the movement controlled throughout the range.', 'Step:6 Hold briefly at a comfortable depth, then rise by extending the hips.']::text[],
