(
  'dcef1a35-9a44-5637-bd21-0d67f272a6d2',
  'arm jerk kettlebell',
  'Two-Arm Kettlebell Jerk',
  'shoulders',
  'kettlebells',
  'shoulders',
  ARRAY['calves', 'quadriceps', 'triceps']::text[],
  ARRAY['Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you swing the kettlebells towards your shoulders. Rotate your wrists as you do so, so that the palms face forward. Squat down a few inches and reverse the motion rapidly driving both kettlebells overhead. Immediately after the initial push, squat down again and get under the kettlebells. Once the kettlebells are locked out, stand upright to complete the exercise.']::text[],
