(
  '82bf0151-47dd-5244-91a8-6c511c389f16',
  'pullup typewriter',
  'Typewriter Pull-ups',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Hang from a pull-up bar with an overhand grip, slightly wider than shoulder-width. Pull yourself up until your chin is above the bar. At the top position, instead of going straight down, shift your body to one side by extending one arm while keeping the other arm bent. Move smoothly from one side to the other, like a typewriter motion, before lowering yourself back down. This exercise increases time under tension and strengthens the lats, biceps, and shoulders while building unilateral pulling strength.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'tenebrizz'
),
(
  '37420d77-6d26-5e48-81cf-c8939bad98c3',
  'pushup tyson',
  'Tyson push-ups',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Starting Position', '• Feet: Place the soles of your feet flat against a vertical wall, with your toes or balls of your feet on the floor.', '• Hands: Position your hands on the floor shoulder-width apart, directly under your lower chest or solar plexus.', '• Body: Keep your core tight, glutes squeezed, and head in a neutral position. Your knees should hover a few inches above the floor without touching it.', 'Movement Pattern', '1. Lower Down: Flex your elbows (tucked around 45 degrees) to lower your chest toward the floor, stopping just a few centimeters short of touching the ground.', '2. Rock Back: As you press upward through your arms, push your hips backward and bend your knees, rocking your weight toward your heels while keeping your shins nearly parallel to the floor.', '3. Drive Forward: Explode forward from your lower-body/crouched position, shifting your weight back into the starting push-up plank stance to complete the repetition.', 'Key Tips for Proper Form', '• Keep Knees Low: Do not let your knees or hips pike high up in the air, keep the motion low and horizontal.', '• Maintain Wall Contact: Keep the soles of your feet pressed against the wall so you don''t lose your leverage.', '• Engage the Core: Avoid arching your lower back by tilting your pelvis backward and bracing your abs.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'yahoo.ivory'
),
